/**
 * Top-of-deck card lifts above the pile, then slides back down and tucks under it.
 * Used when putting cards from the top of the deck on the bottom (stays face down).
 */

import { useEffect, useState } from "react"
import { useLatestRef } from "@/hooks/useLatestRef"

import { sharedImages } from "@/assets/shared"
import { cn } from "@/lib/utils"

export type CardTuckUnderAnimationProps = {
  /** Deck pile rect the card starts on. */
  from: { x: number; y: number; w: number; h: number }
  onComplete: () => void
}

const LIFT_MS = 240
const TUCK_MS = 360

type Phase = "start" | "lifted" | "tucked"

export function CardTuckUnderAnimation({
  from,
  onComplete,
}: CardTuckUnderAnimationProps) {
  const [phase, setPhase] = useState<Phase>("start")
  const onCompleteRef = useLatestRef(onComplete)

  useEffect(() => {
    const raf = requestAnimationFrame(() => setPhase("lifted"))
    const tuck = window.setTimeout(() => setPhase("tucked"), LIFT_MS)
    const done = window.setTimeout(
      () => onCompleteRef.current(),
      LIFT_MS + TUCK_MS + 60
    )
    return () => {
      cancelAnimationFrame(raf)
      window.clearTimeout(tuck)
      window.clearTimeout(done)
    }
  }, [])

  const lift = Math.round(from.h * 0.6)
  const tuck = Math.round(from.h * 0.45)
  const tucked = phase === "tucked"

  return (
    <div
      className="pointer-events-none fixed"
      style={{
        left: from.x,
        top: from.y,
        width: from.w,
        height: from.h,
        transform: tucked
          ? `translate(10px, ${tuck}px) scale(0.72)`
          : phase === "lifted"
            ? `translate(0px, ${-lift}px) scale(1.02)`
            : "translate(0px, 0px) scale(1)",
        opacity: tucked ? 0.3 : 1,
        transition: tucked
          ? `transform ${TUCK_MS}ms cubic-bezier(0.4, 0.05, 0.2, 1), opacity ${TUCK_MS}ms ease-out`
          : `transform ${LIFT_MS}ms ease-out`,
        // Drop below the pile once it starts tucking so it reads as "underneath".
        zIndex: tucked ? 5 : 90,
      }}
    >
      <div
        className={cn(
          "h-full w-full overflow-hidden border border-cyan-400/50 bg-black/80",
          "clip-angled shadow-lg shadow-black/40"
        )}
      >
        <img
          src={sharedImages.CARD_BACK}
          alt=""
          draggable={false}
          className="h-full w-full object-cover"
        />
      </div>
    </div>
  )
}

/**
 * Face-up peek of library cards (Look at top X / Reveal top).
 * When `allowReorder` is set, drag cards to change top-of-deck order; Done commits.
 *
 * Pointer events (not HTML5 drag): the overlay is portalled but still bubbles
 * React events into the playtester surface, which cancels dragstart.
 */

import {
  useEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react"
import { createPortal } from "react-dom"

import { PlayingCard } from "@/components/Playtester/PlayingCard"
import type { PlayingCardInstance } from "@/components/Playtester/types"
import { useLatestRef } from "@/hooks/useLatestRef"
import { cn } from "@/lib/utils"

const DRAG_THRESHOLD_PX = 5
const GHOST_W = 112
const GHOST_H = 144

export type DeckPeekOverlayProps = {
  open: boolean
  title: string
  cards: PlayingCardInstance[]
  /** When true, player may drag to rearrange; Done returns the new order. */
  allowReorder?: boolean
  onClose: (orderedCards: PlayingCardInstance[]) => void
}

type DragState = {
  pointerId: number
  fromIndex: number
  card: PlayingCardInstance
  startX: number
  startY: number
  moved: boolean
  ghostX: number
  ghostY: number
  overIndex: number
}

function moveIndex<T>(list: T[], from: number, to: number): T[] {
  if (from === to || from < 0 || to < 0 || from >= list.length || to >= list.length) {
    return list
  }
  const next = [...list]
  const [item] = next.splice(from, 1)
  next.splice(to, 0, item!)
  return next
}

export function DeckPeekOverlay({
  open,
  title,
  cards,
  allowReorder = false,
  onClose,
}: DeckPeekOverlayProps) {
  const [ordered, setOrdered] = useState<PlayingCardInstance[]>(cards)
  const [drag, setDrag] = useState<DragState | null>(null)
  const dragRef = useRef<DragState | null>(null)
  /** Slot elements, keyed by instance id, for pointer hit-testing. */
  const slotRefs = useRef<Map<string, HTMLLIElement>>(new Map())
  const orderedRef = useLatestRef(ordered)

  useEffect(() => {
    if (!open) return
    setOrdered(cards)
    setDrag(null)
    dragRef.current = null
  }, [open, cards])

  useEffect(() => {
    if (!drag) return

    /** Index of the slot under the cursor (falls back to the dragged slot). */
    function slotIndexAt(clientX: number, clientY: number, fallback: number) {
      let found = fallback
      orderedRef.current.forEach((card, index) => {
        const el = slotRefs.current.get(card.instanceId)
        if (!el) return
        const r = el.getBoundingClientRect()
        if (
          clientX >= r.left &&
          clientX <= r.right &&
          clientY >= r.top &&
          clientY <= r.bottom
        ) {
          found = index
        }
      })
      return found
    }

    function onMove(event: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== event.pointerId) return
      const dist = Math.hypot(
        event.clientX - current.startX,
        event.clientY - current.startY
      )
      if (dist <= DRAG_THRESHOLD_PX && !current.moved) return
      const next: DragState = {
        ...current,
        moved: true,
        ghostX: event.clientX,
        ghostY: event.clientY,
        overIndex: slotIndexAt(
          event.clientX,
          event.clientY,
          current.fromIndex
        ),
      }
      dragRef.current = next
      setDrag(next)
    }

    function onUp(event: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== event.pointerId) return
      dragRef.current = null
      setDrag(null)
      if (!current.moved) return
      const to = slotIndexAt(event.clientX, event.clientY, current.overIndex)
      setOrdered((prev) => moveIndex(prev, current.fromIndex, to))
    }

    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
    return () => {
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onUp)
    }
  }, [drag])

  if (!open || typeof document === "undefined") return null

  function onSlotPointerDown(
    event: ReactPointerEvent<HTMLLIElement>,
    card: PlayingCardInstance,
    index: number
  ) {
    if (!allowReorder || event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    const next: DragState = {
      pointerId: event.pointerId,
      fromIndex: index,
      card,
      startX: event.clientX,
      startY: event.clientY,
      moved: false,
      ghostX: event.clientX,
      ghostY: event.clientY,
      overIndex: index,
    }
    dragRef.current = next
    setDrag(next)
  }

  return createPortal(
    <>
      <div
        className="fixed inset-0 z-[130] flex items-center justify-center bg-black/75 p-4"
        role="dialog"
        aria-modal="true"
        aria-label={title}
      >
        <div className="max-h-[85vh] w-full max-w-3xl overflow-auto border border-cyan-500/35 bg-black/95 p-4 shadow-xl">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h2 className="font-buahs93 text-sm tracking-wide text-cyan-100">
                {title}
              </h2>
              <p className="mt-1 font-mono text-[11px] text-cyan-100/60">
                {allowReorder
                  ? "Drag cards to rearrange. #1 is the top of the deck. Done applies the new order."
                  : "These cards stay in the deck in the same order."}
              </p>
            </div>
            <button
              type="button"
              className="font-buahs93 border border-cyan-500/40 px-3 py-1.5 text-xs text-cyan-100 hover:bg-cyan-500/10"
              onClick={() => onClose(orderedRef.current)}
            >
              Done
            </button>
          </div>
          {ordered.length === 0 ? (
            <p className="mt-6 font-mono text-xs text-white/40">No cards.</p>
          ) : (
            <ul className="mt-4 flex flex-wrap gap-3">
              {ordered.map((card, index) => (
                <li
                  key={card.instanceId}
                  ref={(el) => {
                    if (el) slotRefs.current.set(card.instanceId, el)
                    else slotRefs.current.delete(card.instanceId)
                  }}
                  onPointerDown={(event) =>
                    onSlotPointerDown(event, card, index)
                  }
                  className={cn(
                    "flex flex-col items-center gap-1",
                    allowReorder && "cursor-grab touch-none select-none",
                    drag?.moved &&
                      drag.fromIndex === index &&
                      "cursor-grabbing opacity-30",
                    drag?.moved &&
                      drag.overIndex === index &&
                      drag.fromIndex !== index &&
                      "ring-2 ring-cyan-400/70"
                  )}
                >
                  <span className="font-mono text-[10px] text-cyan-100/50">
                    #{index + 1}
                    {index === 0 ? " · top" : ""}
                  </span>
                  <PlayingCard
                    card={{ ...card, faceDown: false }}
                    className="pointer-events-none h-36 w-28"
                  />
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      {drag?.moved ? (
        <div
          className="pointer-events-none fixed z-[136] -translate-x-1/2 -translate-y-1/2"
          style={{
            left: drag.ghostX,
            top: drag.ghostY,
            width: GHOST_W,
            height: GHOST_H,
          }}
        >
          <PlayingCard
            card={{ ...drag.card, faceDown: false }}
            className="h-full w-full shadow-lg shadow-cyan-500/25"
          />
        </div>
      ) : null}
    </>,
    document.body
  )
}

/**
 * Draw deck / library pile.
 *
 * Under-stack stays still; top card lifts on hover and can be dragged
 * to hand / battlefield / trashyard (parent runs the flip animation).
 * Click (no drag) still draws to hand.
 */

import {
  forwardRef,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react"
import { createPortal } from "react-dom"

import { sharedImages } from "@/assets/shared"
import { CardEnlargeOverlay } from "@/components/Playtester/CardLargeOverlay"
import { elementCssPaintScale } from "@/components/Playtester/playFieldScale.logic"
import { scalePlayPile } from "@/components/Playtester/playPileScale.logic"
import type { PlayPileSize } from "@/components/Playtester/playtesterConstants"
import type { PlayingCardInstance } from "@/components/Playtester/types"
import { useLatestRef } from "@/hooks/useLatestRef"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"

const MAX_UNDER_LAYERS = 5
const STACK_STEP_X = 3
const STACK_STEP_Y = 3
const TOP_LIFT_PX = 14
const DRAG_THRESHOLD_PX = 5

export type DeckPileProps = {
  count: number
  className?: string
  label?: string
  /** True while a flip animation is running. */
  busy?: boolean
  /** Click with no drag — usually draw top card to hand. */
  onClickDraw?: () => void
  /**
   * Drag-release of the top card. Parent hit-tests zones and starts
   * the back→face fly animation.
   */
  onTopCardRelease?: (clientX: number, clientY: number) => void
  /** Right-click on the pile (shuffle / search / degrade / …). */
  onContextMenu?: (clientX: number, clientY: number) => void
  /** Current top library card — only rendered while `topRevealed`. */
  topCard?: PlayingCardInstance | null
  /** Play with the deck's top card face up on the pile. */
  topRevealed?: boolean
  /** Card footprint. Use `lg` to match the pilot column. */
  size?: PlayPileSize
  /**
   * Uniform shrink for short viewports (1 = full size). Applied to the face,
   * stack pad, and lift so layout + drag rects stay aligned.
   */
  scale?: number
  /**
   * Forced lift (peer sync). Combined with local hover so opp can see your
   * library peek without the pile being interactive on their client.
   */
  lift?: boolean
  /** Local hover changed — parent may relay over the net. */
  onHoverChange?: (hovered: boolean) => void
}

const FLIP_MS = 450
const faceShell =
  "absolute inset-0 overflow-hidden border bg-black/80 clip-angled shadow-md shadow-black/55 [backface-visibility:hidden]"

function CardBackFace({ className }: { className?: string }) {
  return (
    <div
      className={cn(
        "absolute inset-0 overflow-hidden border border-cyan-500/40 bg-black/80",
        "clip-angled shadow-md shadow-black/55",
        className
      )}
    >
      <img
        src={sharedImages.CARD_BACK}
        alt=""
        draggable={false}
        className="h-full w-full object-cover"
      />
    </div>
  )
}

/**
 * Top card that flips between its back and its face in place on the pile.
 * Every new top card starts face down, so each reveal replays the flip.
 */
function TopCardFace({
  card,
  revealed,
}: {
  card: PlayingCardInstance | null
  revealed: boolean
}) {
  const faceSrc = card ? cardArtUrl(card.artPath, card.artVersion) : null
  const [faceUp, setFaceUp] = useState(false)
  const instanceId = card?.instanceId ?? null

  useEffect(() => {
    setFaceUp(false)
    if (!revealed || !instanceId) return
    let inner = 0
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setFaceUp(true))
    })
    return () => {
      cancelAnimationFrame(outer)
      cancelAnimationFrame(inner)
    }
  }, [instanceId, revealed])

  return (
    <div className="absolute inset-0 [perspective:800px]">
      <div
        className="relative h-full w-full [transform-style:preserve-3d]"
        style={{
          transform: faceUp ? "rotateY(0deg)" : "rotateY(180deg)",
          transition: `transform ${FLIP_MS}ms ease-in-out`,
        }}
      >
        <div className={cn(faceShell, "border-cyan-400/60")}>
          {faceSrc ? (
            <img
              src={faceSrc}
              alt=""
              draggable={false}
              className="h-full w-full object-cover"
            />
          ) : (
            <span className="flex h-full items-center justify-center px-1 text-center font-mono text-[10px] text-cyan-100/80">
              {card?.name}
            </span>
          )}
        </div>
        <div
          className={cn(faceShell, "border-cyan-400/60")}
          style={{ transform: "rotateY(180deg)" }}
        >
          <img
            src={sharedImages.CARD_BACK}
            alt=""
            draggable={false}
            className="h-full w-full object-cover"
          />
        </div>
      </div>
    </div>
  )
}

type TopDrag = {
  pointerId: number
  startX: number
  startY: number
  moved: boolean
  ghostX: number
  ghostY: number
}

export const DeckPile = forwardRef<HTMLDivElement, DeckPileProps>(
  function DeckPile(
    {
      count,
      className,
      label = "Deck",
      busy = false,
      onClickDraw,
      onTopCardRelease,
      onContextMenu,
      topCard = null,
      topRevealed = false,
      size = "md",
      scale = 1,
      lift = false,
      onHoverChange,
    },
    ref
  ) {
    const { w: CARD_W, h: CARD_H } = scalePlayPile(size, scale)
    const stackStepX = Math.max(1, Math.round(STACK_STEP_X * scale))
    const stackStepY = Math.max(1, Math.round(STACK_STEP_Y * scale))
    const stackPadX = MAX_UNDER_LAYERS * stackStepX
    const topLiftPx = Math.max(1, Math.round(TOP_LIFT_PX * scale))
    const [hovered, setHovered] = useState(false)
    const [drag, setDrag] = useState<TopDrag | null>(null)
    const [enlarged, setEnlarged] = useState<PlayingCardInstance | null>(null)
    const dragRef = useRef<TopDrag | null>(null)
    const measureRef = useRef<HTMLDivElement | null>(null)
    const onReleaseRef = useLatestRef(onTopCardRelease)
    const onClickRef = useLatestRef(onClickDraw)
    const onHoverChangeRef = useLatestRef(onHoverChange)
    const [paintScale, setPaintScale] = useState({ sx: 1, sy: 1 })

    const interactive = !busy && count > 0
    const showLift = (lift || hovered) && !drag?.moved && count > 0
    const underCount =
      count <= 1 ? 0 : Math.min(MAX_UNDER_LAYERS, count - 1)
    const { sx: paintSx, sy: paintSy } = paintScale

    useLayoutEffect(() => {
      const el = measureRef.current
      if (!el) return
      const sync = () => setPaintScale(elementCssPaintScale(el))
      const raf = requestAnimationFrame(sync)
      const observer = new ResizeObserver(sync)
      observer.observe(el)
      return () => {
        cancelAnimationFrame(raf)
        observer.disconnect()
      }
    }, [])

    useEffect(() => {
      if (!drag) return

      function onMove(event: PointerEvent) {
        const current = dragRef.current
        if (!current || current.pointerId !== event.pointerId) return
        const dist = Math.hypot(
          event.clientX - current.startX,
          event.clientY - current.startY
        )
        if (dist <= DRAG_THRESHOLD_PX && !current.moved) return
        const next: TopDrag = {
          ...current,
          moved: true,
          ghostX: event.clientX,
          ghostY: event.clientY,
        }
        dragRef.current = next
        setDrag(next)
        setHovered(false)
        onHoverChangeRef.current?.(false)
      }

      function onUp(event: PointerEvent) {
        const current = dragRef.current
        if (!current || current.pointerId !== event.pointerId) return
        dragRef.current = null
        setDrag(null)
        setHovered(false)
        onHoverChangeRef.current?.(false)

        const moved = current.moved
        if (!moved) {
          onClickRef.current?.()
          return
        }
        onReleaseRef.current?.(event.clientX, event.clientY)
      }

      window.addEventListener("pointermove", onMove, true)
      window.addEventListener("pointerup", onUp, true)
      window.addEventListener("pointercancel", onUp, true)
      return () => {
        window.removeEventListener("pointermove", onMove, true)
        window.removeEventListener("pointerup", onUp, true)
        window.removeEventListener("pointercancel", onUp, true)
      }
    }, [drag])

    // Hold middle-mouse to peek (same as hand / trash / free-float).
    useEffect(() => {
      if (!enlarged) return
      function release() {
        setEnlarged(null)
      }
      window.addEventListener("pointerup", release)
      window.addEventListener("blur", release)
      return () => {
        window.removeEventListener("pointerup", release)
        window.removeEventListener("blur", release)
      }
    }, [enlarged])

    function onTopPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
      if (event.button === 1 && topRevealed && topCard) {
        event.preventDefault()
        event.stopPropagation()
        setEnlarged(topCard)
        return
      }
      if (event.button !== 0 || !interactive) return
      event.preventDefault()
      event.stopPropagation()
      const next: TopDrag = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        moved: false,
        ghostX: event.clientX,
        ghostY: event.clientY,
      }
      dragRef.current = next
      setDrag(next)
      try {
        event.currentTarget.setPointerCapture(event.pointerId)
      } catch {
        /* ignore */
      }
    }

    return (
      <>
        <div
          ref={measureRef}
          className={cn(
            "relative flex shrink-0 flex-col items-center self-stretch",
            className
          )}
          style={{ width: CARD_W + stackPadX }}
          onContextMenu={(event) => {
            event.preventDefault()
            event.stopPropagation()
            onContextMenu?.(event.clientX, event.clientY)
          }}
        >
          {/*
            Outer box owns the full visual footprint (face + right/up stack).
            Face sits bottom-left so overhang stays inside layout, not over trash.
          */}
          <div
            className="relative shrink-0 overflow-visible"
            style={{
              width: CARD_W + stackPadX,
              height: CARD_H,
            }}
          >
            <div
              ref={ref}
              className="absolute bottom-0 left-0"
              style={{ width: CARD_W, height: CARD_H }}
            >
              <div className="pointer-events-none absolute inset-0" aria-hidden>
                {Array.from({ length: underCount }, (_, i) => {
                  const depth = underCount - i
                  return (
                    <div
                      key={`under-${i}`}
                      className="absolute inset-0"
                      style={{
                        transform: `translate(${depth * stackStepX}px, ${-depth * stackStepY}px)`,
                        zIndex: i + 1,
                      }}
                    >
                      <CardBackFace />
                    </div>
                  )
                })}
              </div>

              {count > 0 ? (
                <div
                  role="button"
                  tabIndex={interactive ? 0 : -1}
                  aria-label={
                    topRevealed && topCard
                      ? `${label}, ${count} cards, top card ${topCard.name}`
                      : `${label}, ${count} cards`
                  }
                  aria-disabled={!interactive}
                  onPointerDown={onTopPointerDown}
                  onMouseEnter={() => {
                    if (!dragRef.current && interactive) {
                      setHovered(true)
                      onHoverChangeRef.current?.(true)
                    }
                  }}
                  onMouseLeave={() => {
                    if (!dragRef.current) {
                      setHovered(false)
                      onHoverChangeRef.current?.(false)
                    }
                  }}
                  className={cn(
                    "absolute inset-0 z-20 touch-none select-none p-0",
                    interactive ? "cursor-grab" : "cursor-default",
                    drag?.moved && "cursor-grabbing opacity-30"
                  )}
                  style={{
                    transform: showLift
                      ? `translateY(-${topLiftPx}px)`
                      : "translateY(0px)",
                    transition: drag?.moved
                      ? undefined
                      : "transform 150ms ease-out",
                  }}
                >
                  <TopCardFace card={topCard} revealed={topRevealed} />
                </div>
              ) : (
                <div
                  className={cn(
                    "absolute inset-0 flex items-center justify-center",
                    "border border-dashed border-cyan-500/25 bg-black/40 clip-angled"
                  )}
                >
                  <span className="font-mono text-[10px] text-white/35">
                    Empty
                  </span>
                </div>
              )}
            </div>
          </div>
          <p className="pointer-events-none mt-1 whitespace-nowrap font-mono text-[10px] tracking-wide text-cyan-100/70">
            {label} · {count}
          </p>
        </div>

        {drag?.moved
          ? createPortal(
              <div
                className="pointer-events-none fixed z-[80] -translate-x-1/2 -translate-y-1/2"
                style={{
                  left: drag.ghostX,
                  top: drag.ghostY,
                  width: CARD_W * paintSx,
                  height: CARD_H * paintSy,
                }}
              >
                <CardBackFace className="border-cyan-400/60 shadow-lg shadow-cyan-500/20" />
              </div>,
              document.body
            )
          : null}

        <CardEnlargeOverlay
          open={enlarged != null}
          name={enlarged?.name ?? ""}
          artSrc={
            enlarged?.isClassified
              ? null
              : enlarged
                ? cardArtUrl(enlarged.artPath, enlarged.artVersion)
                : null
          }
          classification={
            enlarged?.classification ??
            (enlarged?.isClassified ? "classified" : null)
          }
        />
      </>
    )
  }
)

/**
 * Search library: free-floating panel with a filter + scrolling card grid.
 * Drag the header to move, the corner grip to resize; both persist.
 * Copies of the same printing share one tile (×N badge); dragging a tile pulls
 * its topmost copy. Backdrop is pointer-events-none so cards can be dragged
 * onto play zones.
 */

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
  type RefObject,
} from "react"
import { createPortal } from "react-dom"

import { CardEnlargeOverlay } from "@/components/Playtester/CardLargeOverlay"
import { PlayingCard } from "@/components/Playtester/PlayingCard"
import {
  filterLibraryByName,
  groupCardsByPrinting,
} from "@/components/Playtester/deckActions.logic"
import {
  clampDeckSearchBox,
  currentViewport,
  defaultDeckSearchBox,
  readStoredDeckSearchBox,
  writeStoredDeckSearchBox,
  type DeckSearchBox,
} from "@/components/Playtester/deckSearchPanel.logic"
import type { PlayingCardInstance } from "@/components/Playtester/types"
import { LOCAL_SEAT, type PlayerSlot } from "@/components/Playtester/playtesterConstants"
import { MiddleMouseScroll } from "@/components/ui/MiddleMouseScroll"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"

const CARD_W = 72
const CARD_H = 96
const DRAG_THRESHOLD_PX = 5

export type DeckSearchModalProps = {
  open: boolean
  sessionCards: PlayingCardInstance[]
  owner?: PlayerSlot
  onCancel: () => void
  /** Drop a library card onto a zone under the floating panel. */
  onCardRelease: (
    instanceId: string,
    clientX: number,
    clientY: number
  ) => void
  /** Right-click a tile (view details). */
  onCardContextMenu?: (
    instanceId: string,
    clientX: number,
    clientY: number
  ) => void
}

/** Header drag (move) and corner drag (resize) share this gesture shape. */
type BoxDragState = {
  pointerId: number
  startX: number
  startY: number
  startBox: DeckSearchBox
}

type DragState = {
  pointerId: number
  instanceId: string
  startX: number
  startY: number
  moved: boolean
  ghostX: number
  ghostY: number
  card: PlayingCardInstance
}

export function DeckSearchModal({
  open,
  sessionCards,
  owner = LOCAL_SEAT,
  onCancel,
  onCardRelease,
  onCardContextMenu,
}: DeckSearchModalProps) {
  const [query, setQuery] = useState("")
  const [drag, setDrag] = useState<DragState | null>(null)
  const dragRef = useRef<DragState | null>(null)
  /** Middle-mouse hold zoom — local to this panel (same as hand / float zones). */
  const [enlarged, setEnlarged] = useState<PlayingCardInstance | null>(null)
  /** Position + size survive closing the panel and reloads. */
  const [box, setBox] = useState<DeckSearchBox>(() =>
    readStoredDeckSearchBox(currentViewport())
  )
  const resizeRef = useRef<BoxDragState | null>(null)
  const moveRef = useRef<BoxDragState | null>(null)

  const visible = useMemo(
    () => filterLibraryByName(sessionCards, query, owner),
    [sessionCards, query, owner]
  )
  /** One tile per printing; copies show as ×N instead of repeating tiles. */
  const groups = useMemo(() => groupCardsByPrinting(visible), [visible])

  useEffect(() => {
    if (!open) {
      setQuery("")
      setDrag(null)
      dragRef.current = null
      setEnlarged(null)
    }
  }, [open])

  useEffect(() => {
    writeStoredDeckSearchBox(box)
  }, [box])

  useEffect(() => {
    function onResize() {
      setBox((prev) => clampDeckSearchBox(prev, currentViewport()))
    }
    window.addEventListener("resize", onResize)
    return () => window.removeEventListener("resize", onResize)
  }, [])

  useEffect(() => {
    if (!enlarged) return
    function release() {
      setEnlarged(null)
    }
    window.addEventListener("pointerup", release)
    window.addEventListener("blur", release)
    return () => {
      window.removeEventListener("pointerup", release)
      window.removeEventListener("blur", release)
    }
  }, [enlarged])

  useEffect(() => {
    if (!open) return
    function onKeyDown(event: KeyboardEvent) {
      if (event.key !== "Escape") return
      // Sticky “View details” overlay owns Escape; don’t close the search under it.
      if (document.querySelector('.deck-card-enlarge[aria-modal="true"]')) {
        return
      }
      onCancel()
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [open, onCancel])

  useEffect(() => {
    if (!drag) return

    function onMove(event: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== event.pointerId) return
      const dist = Math.hypot(
        event.clientX - current.startX,
        event.clientY - current.startY
      )
      if (dist <= DRAG_THRESHOLD_PX && !current.moved) return
      const next: DragState = {
        ...current,
        moved: true,
        ghostX: event.clientX,
        ghostY: event.clientY,
      }
      dragRef.current = next
      setDrag(next)
    }

    function onUp(event: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== event.pointerId) return
      dragRef.current = null
      setDrag(null)
      if (!current.moved) return
      onCardRelease(current.instanceId, event.clientX, event.clientY)
    }

    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
    return () => {
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onUp)
    }
  }, [drag, onCardRelease])

  if (!open || typeof document === "undefined") return null

  function onCardPointerDown(
    event: ReactPointerEvent<HTMLDivElement>,
    card: PlayingCardInstance
  ) {
    // Hold middle mouse to zoom — stopPropagation so MiddleMouseScroll does not pan.
    if (event.button === 1) {
      event.preventDefault()
      event.stopPropagation()
      setEnlarged(card)
      return
    }
    if (event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    const next: DragState = {
      pointerId: event.pointerId,
      instanceId: card.instanceId,
      startX: event.clientX,
      startY: event.clientY,
      moved: false,
      ghostX: event.clientX,
      ghostY: event.clientY,
      card,
    }
    dragRef.current = next
    setDrag(next)
  }

  function beginBoxDrag(
    event: ReactPointerEvent<HTMLDivElement>,
    into: RefObject<BoxDragState | null>
  ) {
    if (event.button !== 0) return
    event.preventDefault()
    event.stopPropagation()
    into.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      startBox: box,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function endBoxDrag(
    event: ReactPointerEvent<HTMLDivElement>,
    from: RefObject<BoxDragState | null>
  ) {
    const gesture = from.current
    if (!gesture || gesture.pointerId !== event.pointerId) return
    from.current = null
    try {
      event.currentTarget.releasePointerCapture(event.pointerId)
    } catch {
      /* already released */
    }
  }

  function onResizePointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    beginBoxDrag(event, resizeRef)
  }

  function onResizePointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const resize = resizeRef.current
    if (!resize || resize.pointerId !== event.pointerId) return
    setBox(
      clampDeckSearchBox(
        {
          ...resize.startBox,
          width: resize.startBox.width + (event.clientX - resize.startX),
          height: resize.startBox.height + (event.clientY - resize.startY),
        },
        currentViewport()
      )
    )
  }

  function onHeaderPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    // Cancel button / search field keep their own pointer behaviour.
    if (
      event.target instanceof Element &&
      event.target.closest("button, input")
    ) {
      return
    }
    beginBoxDrag(event, moveRef)
  }

  function onHeaderPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const move = moveRef.current
    if (!move || move.pointerId !== event.pointerId) return
    setBox(
      clampDeckSearchBox(
        {
          ...move.startBox,
          x: move.startBox.x + (event.clientX - move.startX),
          y: move.startBox.y + (event.clientY - move.startY),
        },
        currentViewport()
      )
    )
  }

  return createPortal(
    <>
      {/* Non-blocking layer so zones remain drop targets. */}
      <div className="pointer-events-none fixed inset-0 z-[125]">
        <div
          className={cn(
            "pointer-events-auto absolute",
            "border border-cyan-500/40 bg-black/95 shadow-xl"
          )}
          style={{ left: box.x, top: box.y, width: box.width }}
          role="dialog"
          aria-modal="false"
          aria-label="Search deck"
        >
          <div
            className="flex cursor-move items-center gap-2 border-b border-cyan-500/30 p-2 touch-none"
            title="Drag to move · double-click to recentre"
            onPointerDown={onHeaderPointerDown}
            onPointerMove={onHeaderPointerMove}
            onPointerUp={(event) => endBoxDrag(event, moveRef)}
            onPointerCancel={(event) => endBoxDrag(event, moveRef)}
            onDoubleClick={() => setBox(defaultDeckSearchBox(currentViewport()))}
          >
            <button
              type="button"
              className="font-buahs93 shrink-0 border border-cyan-500/40 px-2 py-1 text-[10px] text-cyan-100 hover:bg-cyan-500/10"
              onClick={onCancel}
            >
              Cancel
            </button>
            <input
              type="search"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search deck…"
              autoFocus
              className="min-w-0 flex-1 border border-cyan-500/35 bg-black/80 px-2 py-1 font-mono text-xs text-cyan-50 outline-none placeholder:text-cyan-100/35 focus:border-cyan-300"
            />
            <span className="shrink-0 font-mono text-[10px] text-cyan-100/50">
              {visible.length}
            </span>
          </div>

          <MiddleMouseScroll
            label="Deck search results"
            horizontal={false}
            vertical
            style={{ height: box.height }}
            viewportClassName="grid grid-cols-[repeat(auto-fill,minmax(4.5rem,1fr))] content-start gap-2 p-2 pr-3.5"
          >
            {groups.length === 0 ? (
              <p className="col-span-full py-8 text-center font-mono text-[11px] text-white/40">
                No matching cards.
              </p>
            ) : (
              groups.map((group) => {
                const card = group.display
                const copies = group.instances.length
                return (
                  <div
                    key={group.cardId}
                    role="button"
                    tabIndex={0}
                    aria-label={
                      copies > 1
                        ? `Drag ${card.name}, ${copies} copies in deck`
                        : `Drag ${card.name}`
                    }
                    onPointerDown={(event) => onCardPointerDown(event, card)}
                    onContextMenu={(event) => {
                      event.preventDefault()
                      event.stopPropagation()
                      onCardContextMenu?.(
                        card.instanceId,
                        event.clientX,
                        event.clientY
                      )
                    }}
                    className={cn(
                      "relative flex cursor-grab flex-col items-center touch-none select-none",
                      drag?.instanceId === card.instanceId &&
                        drag.moved &&
                        "opacity-30"
                    )}
                  >
                    <PlayingCard
                      card={{ ...card, faceDown: false }}
                      className="h-24 w-[4.5rem]"
                    />
                    {copies > 1 ? (
                      <span
                        className={cn(
                          "pointer-events-none absolute top-1 right-1 z-10",
                          "border border-cyan-400/50 bg-black/80 px-1 py-0.5",
                          "font-mono text-[10px] text-cyan-100"
                        )}
                      >
                        ×{copies}
                      </span>
                    ) : null}
                    <span className="w-full truncate text-center font-mono text-[9px] leading-tight text-cyan-100/70">
                      {card.name}
                    </span>
                  </div>
                )
              })
            )}
          </MiddleMouseScroll>

          <div
            role="button"
            tabIndex={-1}
            aria-label="Resize deck search"
            title="Drag to resize · double-click to reset"
            className="absolute bottom-0 right-0 z-20 h-4 w-4 cursor-nwse-resize touch-none"
            onPointerDown={onResizePointerDown}
            onPointerMove={onResizePointerMove}
            onPointerUp={(event) => endBoxDrag(event, resizeRef)}
            onPointerCancel={(event) => endBoxDrag(event, resizeRef)}
            onDoubleClick={() => setBox(defaultDeckSearchBox(currentViewport()))}
          >
            <div
              className="absolute right-1 bottom-1 h-2 w-2 border-r-2 border-b-2 border-cyan-400/70"
              aria-hidden
            />
          </div>
        </div>
      </div>

      {drag?.moved ? (
        <div
          className="pointer-events-none fixed z-[135] -translate-x-1/2 -translate-y-1/2"
          style={{
            left: drag.ghostX,
            top: drag.ghostY,
            width: CARD_W,
            height: CARD_H,
          }}
        >
          <PlayingCard
            card={{ ...drag.card, faceDown: false }}
            className="h-full w-full shadow-lg shadow-cyan-500/25"
          />
        </div>
      ) : null}

      <CardEnlargeOverlay
        open={enlarged != null}
        name={enlarged?.name ?? ""}
        artSrc={
          enlarged?.isClassified
            ? null
            : enlarged
              ? cardArtUrl(enlarged.artPath, enlarged.artVersion)
              : null
        }
        classification={
          enlarged?.classification ??
          (enlarged?.isClassified ? "classified" : null)
        }
      />
    </>,
    document.body
  )
}

/**
 * Riffle shuffle on the deck pile: card backs split left/right, then merge back.
 * Two passes, alternating which side leads.
 */

import { useEffect, useState } from "react"
import { useLatestRef } from "@/hooks/useLatestRef"

import { sharedImages } from "@/assets/shared"
import { cn } from "@/lib/utils"

export type DeckShuffleAnimationProps = {
  /** Deck pile rect the riffle plays over. */
  from: { x: number; y: number; w: number; h: number }
  onComplete: () => void
}

const CARD_COUNT = 6
const STEP_MS = 190
/** split → merge → split → merge */
const STEPS = 4

export function DeckShuffleAnimation({
  from,
  onComplete,
}: DeckShuffleAnimationProps) {
  const [step, setStep] = useState(0)
  const onCompleteRef = useLatestRef(onComplete)

  useEffect(() => {
    const timers = Array.from({ length: STEPS }, (_, i) =>
      window.setTimeout(() => setStep(i + 1), (i + 1) * STEP_MS)
    )
    const done = window.setTimeout(
      () => onCompleteRef.current(),
      STEPS * STEP_MS + 140
    )
    return () => {
      for (const t of timers) window.clearTimeout(t)
      window.clearTimeout(done)
    }
  }, [])

  const split = step % 2 === 1
  /** Second pass leads with the opposite side. */
  const pass = step >= 3 ? -1 : 1

  return (
    <div
      className="pointer-events-none fixed z-[90]"
      style={{
        left: from.x,
        top: from.y,
        width: from.w,
        height: from.h,
      }}
    >
      {Array.from({ length: CARD_COUNT }, (_, i) => {
        const side = (i % 2 === 0 ? 1 : -1) * pass
        const spread = 16 + i * 4
        const rise = 6 + i * 3
        const tilt = 3 + i * 1.5
        return (
          <div
            key={`riffle-${i}`}
            className="absolute inset-0"
            style={{
              transform: split
                ? `translate(${side * spread}px, ${-rise}px) rotate(${side * tilt}deg)`
                : "translate(0px, 0px) rotate(0deg)",
              transition: `transform ${STEP_MS}ms cubic-bezier(0.35, 0, 0.3, 1)`,
              zIndex: CARD_COUNT - i,
            }}
          >
            <div
              className={cn(
                "h-full w-full overflow-hidden border border-cyan-400/45 bg-black/80",
                "clip-angled shadow-md shadow-black/50"
              )}
            >
              <img
                src={sharedImages.CARD_BACK}
                alt=""
                draggable={false}
                className="h-full w-full object-cover"
              />
            </div>
          </div>
        )
      })}
    </div>
  )
}

/**
 * Floating, resizable hand window on the play field.
 * Drag the header to move, the corner grip to resize; both persist.
 * No backdrop — cards drag out onto the table underneath.
 */

import {
  useEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  type Ref,
} from "react"

import {
  clampHandFloatBox,
  defaultHandFloatBox,
  readStoredHandFloatBox,
  writeStoredHandFloatBox,
  type HandFloatAnchor,
  type HandFloatBox,
  type ParentSize,
} from "@/components/Playtester/handFloatPanel.logic"

type BoxDragState = {
  pointerId: number
  startX: number
  startY: number
  startBox: HandFloatBox
}

export type FloatingHandPanelProps = {
  parentSize: ParentSize
  anchor?: HandFloatAnchor
  panelRef?: Ref<HTMLDivElement | null>
  /** Centered in the title bar (life total). */
  center?: ReactNode
  children: ReactNode
  label: string
}

export function FloatingHandPanel({
  parentSize,
  anchor = "bottom",
  panelRef,
  center,
  children,
  label,
}: FloatingHandPanelProps) {
  const [box, setBox] = useState<HandFloatBox | null>(null)
  const moveRef = useRef<BoxDragState | null>(null)
  const resizeRef = useRef<BoxDragState | null>(null)

  useEffect(() => {
    if (parentSize.width < 32 || parentSize.height < 32) return
    setBox((prev) =>
      prev
        ? clampHandFloatBox(prev, parentSize)
        : readStoredHandFloatBox(parentSize, anchor)
    )
  }, [parentSize, anchor])

  useEffect(() => {
    if (!box) return
    writeStoredHandFloatBox(box, anchor)
  }, [box, anchor])

  function beginBoxDrag(
    event: ReactPointerEvent<HTMLDivElement>,
    into: typeof moveRef
  ) {
    if (event.button !== 0 || box == null) return
    event.preventDefault()
    event.stopPropagation()
    into.current = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      startBox: box,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  function endBoxDrag(
    event: ReactPointerEvent<HTMLDivElement>,
    from: typeof moveRef
  ) {
    const gesture = from.current
    if (!gesture || gesture.pointerId !== event.pointerId) return
    from.current = null
    try {
      event.currentTarget.releasePointerCapture(event.pointerId)
    } catch {
      /* already released */
    }
  }

  function onHeaderPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    if (
      event.target instanceof Element &&
      event.target.closest("button")
    ) {
      return
    }
    beginBoxDrag(event, moveRef)
  }

  function onHeaderPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const move = moveRef.current
    if (!move || move.pointerId !== event.pointerId) return
    setBox(
      clampHandFloatBox(
        {
          ...move.startBox,
          x: move.startBox.x + (event.clientX - move.startX),
          y: move.startBox.y + (event.clientY - move.startY),
        },
        parentSize
      )
    )
  }

  function onResizePointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const resize = resizeRef.current
    if (!resize || resize.pointerId !== event.pointerId) return
    setBox(
      clampHandFloatBox(
        {
          ...resize.startBox,
          width: resize.startBox.width + (event.clientX - resize.startX),
          height: resize.startBox.height + (event.clientY - resize.startY),
        },
        parentSize
      )
    )
  }

  if (!box || parentSize.width < 32 || parentSize.height < 32) return null

  return (
    <div
      ref={panelRef}
      className="absolute z-40 flex flex-col overflow-hidden border border-cyan-500/40 bg-black/80 shadow-lg shadow-black/50"
      style={{
        left: box.x,
        top: box.y,
        width: box.width,
        height: box.height,
      }}
    >
      <div
        className="grid shrink-0 cursor-grab grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-2 border-b border-cyan-500/25 px-2 py-1 touch-none"
        onPointerDown={onHeaderPointerDown}
        onPointerMove={onHeaderPointerMove}
        onPointerUp={(event) => endBoxDrag(event, moveRef)}
        onPointerCancel={(event) => endBoxDrag(event, moveRef)}
      >
        <p className="min-w-0 truncate font-mono text-[10px] tracking-wide text-cyan-100/80">
          {label}
        </p>
        <div className="justify-self-center">{center}</div>
        <div aria-hidden />
      </div>
      <div className="relative min-h-0 flex-1">{children}</div>
      <div
        role="button"
        tabIndex={-1}
        aria-label="Resize hand"
        title="Drag to resize · double-click to reset"
        className="absolute bottom-0 right-0 z-20 h-4 w-4 cursor-nwse-resize touch-none"
        onPointerDown={(event) => beginBoxDrag(event, resizeRef)}
        onPointerMove={onResizePointerMove}
        onPointerUp={(event) => endBoxDrag(event, resizeRef)}
        onPointerCancel={(event) => endBoxDrag(event, resizeRef)}
        onDoubleClick={() => setBox(defaultHandFloatBox(parentSize, anchor))}
      >
        <div
          className="absolute right-1 bottom-1 h-2 w-2 border-r-2 border-b-2 border-cyan-400/70"
          aria-hidden
        />
      </div>
    </div>
  )
}

/**
 * Free-float play surface — drag cards by {x,y}; ghost escapes overflow to reach hand.
 * Empty-surface drag draws a marquee to multi-select cards.
 * Ctrl/Cmd+click toggles a card in or out of the selection.
 * Dragging a selected card moves / rezones the whole selection as a group.
 *
 * Pointer listeners for marquee + card drag are attached synchronously on
 * pointerdown (not in useEffect) so a quick click cannot miss pointerup.
 * Card drag uses window capture-phase listeners + setPointerCapture so macOS
 * Safari keeps tracking after the pointer leaves the surface.
 *
 * Drag ghosts portal to `document.body`. A CSS `transform` on an ancestor
 * (play-field fit scale) makes `position: fixed` use that ancestor as the
 * containing block — clientX/Y would then land in the wrong place.
 */

import {
  useLayoutEffect,
  useEffect,
  useRef,
  useState,
  type PointerEvent as ReactPointerEvent,
} from "react"
import { createPortal } from "react-dom"

import { LOCAL_SEAT, type PlayerSlot } from "@/components/Playtester/playtesterConstants"
import { scalePlayPile } from "@/components/Playtester/playPileScale.logic"
import {
  PLAY_FLOAT_LOGICAL,
  clientToLogicalField,
  logicalFieldPaintScale,
} from "@/components/Playtester/playFieldScale.logic"
import { PlayingCard } from "@/components/Playtester/PlayingCard"
import {
  type CardCounterKind,
  type PlayingCardInstance,
} from "@/components/Playtester/types"
import { useLatestRef } from "@/hooks/useLatestRef"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"

import { CardEnlargeOverlay } from "./CardLargeOverlay"

const DRAG_THRESHOLD_PX = 5

export type CardMove = {
  instanceId: string
  x: number
  y: number
}

/** Shared callbacks for the in-play FreeFloat mount. */
export type FloatSurfaceActions = {
  onMoveCards: (moves: CardMove[]) => void
  onBringToFront: (instanceId: string) => void
  onToggleExpended: (instanceIds: string[]) => void
  onCardContextMenu?: (
    instanceId: string,
    clientX: number,
    clientY: number
  ) => void
  onCardCounterAdjust?: (
    instanceId: string,
    kind: CardCounterKind,
    delta: number
  ) => void
}

export type FreeFloatSurfaceProps = {
  cards: PlayingCardInstance[]
  className?: string
  actions: FloatSurfaceActions
  onSelectionChange?: (instanceIds: string[]) => void
  /**
   * Pointer-up after a drag. Return `true` if the cards left this surface
   * (hand / pilot / trash / …) so we skip committing an on-field position.
   */
  onCardsReleased?: (
    instanceIds: string[],
    clientX: number,
    clientY: number
  ) => boolean | void
  /** Right-click empty surface (not on a card). */
  onEmptyContextMenu?: (clientX: number, clientY: number) => void
  /** False for a fully read-only mount. Opponent cards on a shared field
   *  still skip drag via `localSeat`. */
  interactive?: boolean
  /** Drop the cyan frame so this surface can sit inside a shared playmat. */
  plain?: boolean
  /** Only this seat's cards can be dragged / selected. */
  localSeat?: PlayerSlot
  /**
   * Same shrink factor as the side-column piles (1 = full `lg`). Keeps
   * battlefield faces proportional to Pilot / Deck on short viewports.
   */
  cardScale?: number
}

type DragState = {
  instanceId: string
  groupIds: string[]
  origins: Record<string, { x: number; y: number }>
  pointerId: number
  offsetX: number
  offsetY: number
  startX: number
  startY: number
  moved: boolean
  ghostX: number
  ghostY: number
}

type MarqueeState = {
  pointerId: number
  x0: number
  y0: number
  x1: number
  y1: number
}

function normalizeRect(x0: number, y0: number, x1: number, y1: number) {
  return {
    left: Math.min(x0, x1),
    top: Math.min(y0, y1),
    right: Math.max(x0, x1),
    bottom: Math.max(y0, y1),
  }
}

function rectsIntersect(
  a: { left: number; top: number; right: number; bottom: number },
  b: { left: number; top: number; right: number; bottom: number }
) {
  return !(
    a.right < b.left ||
    a.left > b.right ||
    a.bottom < b.top ||
    a.top > b.bottom
  )
}

function cardHitBox(
  card: PlayingCardInstance,
  cardW: number,
  cardH: number
) {
  const x = card.x ?? 0
  const y = card.y ?? 0
  if (card.expended) {
    const size = Math.max(cardW, cardH)
    return { left: x, top: y, right: x + size, bottom: y + size }
  }
  return { left: x, top: y, right: x + cardW, bottom: y + cardH }
}

function cardFootprint(
  card: PlayingCardInstance | undefined,
  cardW: number,
  cardH: number
) {
  if (card?.expended) {
    const size = Math.max(cardW, cardH)
    return { w: size, h: size }
  }
  return { w: cardW, h: cardH }
}

/**
 * Keep a drag group fully inside the surface. Shifts the whole group as one
 * rigid body so multi-select spacing is preserved.
 */
function clampMovesToSurface(
  moves: CardMove[],
  cards: PlayingCardInstance[],
  surfaceW: number,
  surfaceH: number,
  cardW: number,
  cardH: number
): CardMove[] {
  if (moves.length === 0 || surfaceW <= 0 || surfaceH <= 0) return moves

  const byId = new Map(cards.map((c) => [c.instanceId, c]))
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity

  for (const move of moves) {
    const { w, h } = cardFootprint(byId.get(move.instanceId), cardW, cardH)
    minX = Math.min(minX, move.x)
    minY = Math.min(minY, move.y)
    maxX = Math.max(maxX, move.x + w)
    maxY = Math.max(maxY, move.y + h)
  }

  let dx = 0
  let dy = 0
  if (minX < 0) dx += -minX
  if (minY < 0) dy += -minY
  if (maxX + dx > surfaceW) dx += surfaceW - (maxX + dx)
  if (maxY + dy > surfaceH) dy += surfaceH - (maxY + dy)
  // Group larger than the surface: pin to the top-left corner.
  if (minX + dx < 0) dx = -minX
  if (minY + dy < 0) dy = -minY

  if (dx === 0 && dy === 0) return moves
  return moves.map((move) => ({
    ...move,
    x: move.x + dx,
    y: move.y + dy,
  }))
}

export function FreeFloatSurface({
  cards,
  className,
  actions,
  onSelectionChange,
  onCardsReleased,
  onEmptyContextMenu,
  interactive = true,
  plain = false,
  localSeat = LOCAL_SEAT,
  cardScale = 1,
}: FreeFloatSurfaceProps) {
  const {
    onMoveCards,
    onBringToFront,
    onToggleExpended,
    onCardContextMenu,
    onCardCounterAdjust,
  } = actions
  const { w: cardW, h: cardH } = scalePlayPile("lg", cardScale)
  const cardSizeRef = useLatestRef({ w: cardW, h: cardH })
  const surfaceRef = useRef<HTMLDivElement>(null)
  const dragRef = useRef<DragState | null>(null)
  const marqueeRef = useRef<MarqueeState | null>(null)
  const [drag, setDrag] = useState<DragState | null>(null)
  const [marquee, setMarquee] = useState<MarqueeState | null>(null)
  const [enlarged, setEnlarged] = useState<PlayingCardInstance | null>(null)
  const [paintScale, setPaintScale] = useState({ sx: 1, sy: 1 })

  const cardsRef = useLatestRef(cards)
  const onSelectionRef = useLatestRef(onSelectionChange)
  const onMoveCardsRef = useLatestRef(onMoveCards)
  /**
   * Position tween must already be ON when left/top change (CSS can't
   * animate a past paint). Keep left/top transition armed; suppress only
   * for the paint that applies a local drop so the source doesn't "follow".
   */
  const [suppressPosTween, setSuppressPosTween] = useState(
    () => new Set<string>()
  )
  const onCardsReleasedRef = useLatestRef(onCardsReleased)
  const localSeatRef = useLatestRef(localSeat)
  const cardDragListenersRef = useRef<{
    move: (event: PointerEvent) => void
    up: (event: PointerEvent) => void
  } | null>(null)
  const marqueeListenersRef = useRef<{
    move: (event: PointerEvent) => void
    up: (event: PointerEvent) => void
  } | null>(null)

  // After the no-tween drop paint, clear suppress so the next remote move tweens.
  useLayoutEffect(() => {
    setSuppressPosTween((prev) => (prev.size === 0 ? prev : new Set()))
  }, [cards])

  useLayoutEffect(() => {
    const surface = surfaceRef.current
    if (!surface) return
    const sync = () => {
      setPaintScale(logicalFieldPaintScale(surface.getBoundingClientRect()))
    }
    const raf = requestAnimationFrame(sync)
    const observer = new ResizeObserver(sync)
    observer.observe(surface)
    return () => {
      cancelAnimationFrame(raf)
      observer.disconnect()
    }
  }, [])

  function detachWindowDrag() {
    const listeners = cardDragListenersRef.current
    if (!listeners) return
    window.removeEventListener("pointermove", listeners.move, true)
    window.removeEventListener("pointerup", listeners.up, true)
    window.removeEventListener("pointercancel", listeners.up, true)
    cardDragListenersRef.current = null
  }

  function detachWindowMarquee() {
    const listeners = marqueeListenersRef.current
    if (!listeners) return
    window.removeEventListener("pointermove", listeners.move)
    window.removeEventListener("pointerup", listeners.up)
    window.removeEventListener("pointercancel", listeners.up)
    marqueeListenersRef.current = null
  }

  // Tear down any leftover window listeners on unmount.
  useEffect(() => {
    return () => {
      detachWindowDrag()
      detachWindowMarquee()
      dragRef.current = null
      marqueeRef.current = null
    }
  }, [])

  useEffect(() => {
    if (!enlarged) return
    function release() {
      setEnlarged(null)
    }
    window.addEventListener("pointerup", release)
    window.addEventListener("blur", release)
    return () => {
      window.removeEventListener("pointerup", release)
      window.removeEventListener("blur", release)
    }
  }, [enlarged])

  function surfacePaintScale() {
    const surface = surfaceRef.current
    if (!surface) return { sx: 1, sy: 1 }
    return logicalFieldPaintScale(surface.getBoundingClientRect())
  }

  function clientToLocal(clientX: number, clientY: number) {
    const surface = surfaceRef.current
    if (!surface) return { x: 0, y: 0 }
    // Painted rect → shared logical field (same board fraction on every screen).
    return clientToLogicalField(
      clientX,
      clientY,
      surface.getBoundingClientRect()
    )
  }

  function onSurfacePointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    if (!interactive) return
    if (event.button !== 0) return
    if (dragRef.current || marqueeRef.current) return
    event.preventDefault()

    const local = clientToLocal(event.clientX, event.clientY)
    const next: MarqueeState = {
      pointerId: event.pointerId,
      x0: local.x,
      y0: local.y,
      x1: local.x,
      y1: local.y,
    }
    marqueeRef.current = next
    setMarquee(next)

    function onMove(moveEvent: PointerEvent) {
      const current = marqueeRef.current
      if (!current || current.pointerId !== moveEvent.pointerId) return
      const point = clientToLocal(moveEvent.clientX, moveEvent.clientY)
      const updated = { ...current, x1: point.x, y1: point.y }
      marqueeRef.current = updated
      setMarquee(updated)
    }

    function onUp(upEvent: PointerEvent) {
      const current = marqueeRef.current
      if (!current || current.pointerId !== upEvent.pointerId) return
      detachWindowMarquee()
      marqueeRef.current = null
      setMarquee(null)

      const draggedFar =
        Math.hypot(current.x1 - current.x0, current.y1 - current.y0) >
        DRAG_THRESHOLD_PX

      if (!draggedFar) {
        onSelectionRef.current?.([])
        return
      }

      const box = normalizeRect(current.x0, current.y0, current.x1, current.y1)
      const { w, h } = cardSizeRef.current
      const hit = cardsRef.current
        .filter(
          (card) =>
            card.owner === localSeatRef.current &&
            rectsIntersect(box, cardHitBox(card, w, h))
        )
        .map((card) => card.instanceId)
      onSelectionRef.current?.(hit)
    }

    marqueeListenersRef.current = { move: onMove, up: onUp }
    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onUp)
  }

  function onCardPointerDown(
    event: ReactPointerEvent<HTMLDivElement>,
    card: PlayingCardInstance
  ) {
    if (!interactive) return
    if (card.owner !== localSeat) return
    // Counter badges own their clicks — do not select / drag / expend.
    if (
      event.target instanceof Element &&
      event.target.closest("[data-counter-badge]")
    ) {
      return
    }
    event.stopPropagation()
    if (event.button === 1) {
      event.preventDefault()
      setEnlarged(card)
      return
    }
    if (event.button !== 0) return
    if (marqueeRef.current) {
      detachWindowMarquee()
      marqueeRef.current = null
      setMarquee(null)
    }

    onBringToFront(card.instanceId)
    event.preventDefault()

    const selectedIds = cards
      .filter((c) => c.selected)
      .map((c) => c.instanceId)

    // Ctrl/Cmd+click toggles membership without starting a drag.
    if (event.ctrlKey || event.metaKey) {
      const nextIds = card.selected
        ? selectedIds.filter((id) => id !== card.instanceId)
        : [...selectedIds, card.instanceId]
      onSelectionRef.current?.(nextIds)
      return
    }

    const local = clientToLocal(event.clientX, event.clientY)
    const x = card.x ?? 0
    const y = card.y ?? 0

    const groupIds =
      card.selected && selectedIds.length > 0
        ? selectedIds
        : [card.instanceId]

    // Clicking an unselected card replaces the selection with just that card.
    if (!card.selected) {
      onSelectionRef.current?.([card.instanceId])
    }

    const origins: Record<string, { x: number; y: number }> = {}
    for (const id of groupIds) {
      const c = cards.find((item) => item.instanceId === id)
      origins[id] = { x: c?.x ?? 0, y: c?.y ?? 0 }
    }

    const { sx, sy } = surfacePaintScale()
    const next: DragState = {
      instanceId: card.instanceId,
      groupIds,
      origins,
      pointerId: event.pointerId,
      offsetX: local.x - x,
      offsetY: local.y - y,
      startX: event.clientX,
      startY: event.clientY,
      moved: false,
      // Ghost is `position: fixed` (screen px); offset is logical — convert.
      ghostX: event.clientX - (local.x - x) * sx,
      ghostY: event.clientY - (local.y - y) * sy,
    }
    dragRef.current = next
    setDrag(next)

    function onMove(moveEvent: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== moveEvent.pointerId) return

      const dist = Math.hypot(
        moveEvent.clientX - current.startX,
        moveEvent.clientY - current.startY
      )
      if (dist <= DRAG_THRESHOLD_PX && !current.moved) return

      const paint = surfacePaintScale()
      const updated: DragState = {
        ...current,
        moved: true,
        ghostX: moveEvent.clientX - current.offsetX * paint.sx,
        ghostY: moveEvent.clientY - current.offsetY * paint.sy,
      }
      dragRef.current = updated
      setDrag(updated)
    }

    function onUp(upEvent: PointerEvent) {
      const current = dragRef.current
      if (!current || current.pointerId !== upEvent.pointerId) return
      detachWindowDrag()

      const clientX = upEvent.clientX
      const clientY = upEvent.clientY
      const moved = current.moved
      const groupIdsAtRelease = current.groupIds

      // Prefer a zone drop (pilot / hand / trash / …) over parking on the
      // field edge — otherwise a near-miss on the side piles leaves the card
      // stuck on the playmat and feels like the slot rejected the drop.
      if (moved) {
        const rezoned = onCardsReleasedRef.current?.(
          groupIdsAtRelease,
          clientX,
          clientY
        )
        if (!rezoned) {
          const point = clientToLocal(clientX, clientY)
          const primaryX = point.x - current.offsetX
          const primaryY = point.y - current.offsetY
          const originPrimary = current.origins[current.instanceId] ?? {
            x: 0,
            y: 0,
          }
          const dx = primaryX - originPrimary.x
          const dy = primaryY - originPrimary.y

          const proposed: CardMove[] = groupIdsAtRelease.map((id) => {
            const origin = current.origins[id] ?? { x: 0, y: 0 }
            return {
              instanceId: id,
              x: origin.x + dx,
              y: origin.y + dy,
            }
          })

          const { w, h } = cardSizeRef.current
          const moves = clampMovesToSurface(
            proposed,
            cardsRef.current,
            PLAY_FLOAT_LOGICAL.width,
            PLAY_FLOAT_LOGICAL.height,
            w,
            h
          )
          setSuppressPosTween(
            new Set(moves.map((move) => move.instanceId))
          )
          onMoveCardsRef.current(moves)
        }
      }

      dragRef.current = null
      setDrag(null)
    }

    try {
      event.currentTarget.setPointerCapture(event.pointerId)
    } catch {
      /* some browsers reject capture on certain targets */
    }
    cardDragListenersRef.current = { move: onMove, up: onUp }
    window.addEventListener("pointermove", onMove, true)
    window.addEventListener("pointerup", onUp, true)
    window.addEventListener("pointercancel", onUp, true)
  }

  const marqueeBox = marquee
    ? normalizeRect(marquee.x0, marquee.y0, marquee.x1, marquee.y1)
    : null

  const draggingIds = drag?.moved ? new Set(drag.groupIds) : null
  const primaryOrigin = drag
    ? (drag.origins[drag.instanceId] ?? { x: 0, y: 0 })
    : null
  const { sx: paintSx, sy: paintSy } = paintScale
  const ghostCards =
    drag?.moved && primaryOrigin
      ? drag.groupIds
          .map((id) => {
            const card = cards.find((c) => c.instanceId === id)
            const origin = drag.origins[id]
            if (!card || !origin) return null
            return {
              card,
              left: drag.ghostX + (origin.x - primaryOrigin.x) * paintSx,
              top: drag.ghostY + (origin.y - primaryOrigin.y) * paintSy,
            }
          })
          .filter(
            (
              item
            ): item is {
              card: PlayingCardInstance
              left: number
              top: number
            } => item != null
          )
      : []

  return (
    <>
      <div
        ref={surfaceRef}
        className={cn(
          "relative h-full min-h-0 w-full overflow-hidden",
          plain
            ? "border-0 bg-transparent"
            : "border border-cyan-500/25 bg-black/40",
          className
        )}
        onPointerDown={onSurfacePointerDown}
        onContextMenu={(event) => {
          // Card handlers stopPropagation; this only fires on empty surface.
          event.preventDefault()
          onEmptyContextMenu?.(event.clientX, event.clientY)
        }}
      >
        {cards.map((card) => {
          const isDragging = Boolean(draggingIds?.has(card.instanceId))
          const suppressTween = suppressPosTween.has(
            card.instanceId
          )

          return (
            <div
              key={card.instanceId}
              className={cn(
                // left/top tween stays armed for remote moves; local drops
                // suppress only position (transform still spins expend/ready).
                "absolute touch-none ease-out",
                isDragging
                  ? "z-20 cursor-grabbing opacity-0"
                  : card.owner === localSeat
                    ? "z-10 cursor-grab"
                    : "z-10 cursor-default",
                card.selected &&
                  !isDragging &&
                  "ring-2 ring-cyan-300 ring-offset-1 ring-offset-black/80"
              )}
              style={{
                left: card.x ?? 0,
                top: card.y ?? 0,
                width: cardW,
                height: cardH,
                transform: card.expended ? "rotate(90deg)" : "rotate(0deg)",
                transition: suppressTween
                  ? "transform 300ms ease-out"
                  : "left 300ms ease-out, top 300ms ease-out, transform 300ms ease-out",
              }}
              onPointerDown={(event) => onCardPointerDown(event, card)}
              onContextMenu={(event) => {
                event.preventDefault()
                event.stopPropagation()
                onCardContextMenu?.(
                  card.instanceId,
                  event.clientX,
                  event.clientY
                )
              }}
              onDoubleClick={(event) => {
                if (card.owner !== localSeat) return
                if (
                  event.target instanceof Element &&
                  event.target.closest("[data-counter-badge]")
                ) {
                  return
                }
                if (card.selected) {
                  const ids = cards
                    .filter((c) => c.selected)
                    .map((c) => c.instanceId)
                  onToggleExpended(ids.length > 0 ? ids : [card.instanceId])
                } else {
                  onToggleExpended([card.instanceId])
                }
              }}
            >
              <PlayingCard
                card={card}
                className="h-full w-full"
                isSelected={card.selected}
                onCounterAdjust={
                  onCardCounterAdjust
                    ? (kind, delta) =>
                        onCardCounterAdjust(card.instanceId, kind, delta)
                    : undefined
                }
              />
            </div>
          )
        })}

        {marqueeBox ? (
          <div
            className="pointer-events-none absolute z-30 border border-cyan-300/80 bg-cyan-400/15"
            style={{
              left: marqueeBox.left,
              top: marqueeBox.top,
              width: marqueeBox.right - marqueeBox.left,
              height: marqueeBox.bottom - marqueeBox.top,
            }}
          />
        ) : null}

        <CardEnlargeOverlay
          open={enlarged != null}
          name={enlarged?.name ?? ""}
          artSrc={
            enlarged ? cardArtUrl(enlarged.artPath, enlarged.artVersion) : null
          }
        />
      </div>

      {ghostCards.length > 0
        ? createPortal(
            <>
              {ghostCards.map(({ card, left, top }) => (
                <div
                  key={`ghost-${card.instanceId}`}
                  className={cn(
                    "pointer-events-none fixed z-[80]",
                    card.expended && "rotate-90",
                    card.selected && "ring-2 ring-cyan-300"
                  )}
                  style={{
                    left,
                    top,
                    width: cardW * paintSx,
                    height: cardH * paintSy,
                  }}
                >
                  <PlayingCard
                    card={card}
                    className="h-full w-full"
                    isSelected={card.selected}
                  />
                </div>
              ))}
            </>,
            document.body
          )
        : null}
    </>
  )
}

/**
 * Face-up trashyard (discard) pile.
 *
 * Collapsed: only the top card shows.
 * Hover: fan condensed unique faces; duplicates share one slot with ×N.
 *
 * Important: stay expanded for the whole drag. Collapsing mid-drag unmounts
 * the pointer-capture target and kills the gesture.
 */

import {
  forwardRef,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type MouseEvent as ReactMouseEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react"
import { createPortal } from "react-dom"

import { CardEnlargeOverlay } from "@/components/Playtester/CardLargeOverlay"
import { PlayingCard } from "@/components/Playtester/PlayingCard"
import { elementCssPaintScale } from "@/components/Playtester/playFieldScale.logic"
import { scalePlayPile } from "@/components/Playtester/playPileScale.logic"
import type { PlayPileSize } from "@/components/Playtester/playtesterConstants"
import type { PlayingCardInstance } from "@/components/Playtester/types"
import { useLatestRef } from "@/hooks/useLatestRef"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"

const DRAG_THRESHOLD_PX = 5

type TrashGroup = {
  cardId: number
  display: PlayingCardInstance
  instances: PlayingCardInstance[]
}

function groupTrashCards(cards: PlayingCardInstance[]): TrashGroup[] {
  const byId = new Map<number, PlayingCardInstance[]>()
  const order: number[] = []
  for (const card of cards) {
    const list = byId.get(card.cardId)
    if (!list) {
      byId.set(card.cardId, [card])
      order.push(card.cardId)
    } else {
      list.push(card)
    }
  }
  return order.map((cardId) => {
    const instances = byId.get(cardId)!
    return {
      cardId,
      display: instances[instances.length - 1]!,
      instances,
    }
  })
}

export type TrashyardPileProps = {
  cards: PlayingCardInstance[]
  className?: string
  /** Zone title under the pile. */
  label?: string
  /** Card footprint. Default `md`. Use `lg` to match the pilot column. */
  size?: PlayPileSize
  onReleaseCard: (
    instanceId: string,
    clientX: number,
    clientY: number
  ) => void
  /** Right-click a pile card (zone actions). */
  onCardContextMenu?: (
    instanceId: string,
    clientX: number,
    clientY: number
  ) => void
  /** Right-click empty pile space (e.g. Move all). */
  onPileContextMenu?: (clientX: number, clientY: number) => void
  /**
   * Optional badge drawn on top of the pile (e.g. pilot +GEN).
   * Shown even when the pile is empty so zone-persistent counters stay visible.
   */
  cardOverlay?: ReactNode
  /**
   * Double-click a pile card to expend / ready (pilot slot).
   * Omit on trashyard / dismantled — those cards are not in-play.
   */
  onToggleExpended?: (instanceId: string) => void
  /**
   * Uniform shrink for short viewports (1 = full size). Applied to the face
   * and fan peek so layout + drag rects stay aligned.
   */
  scale?: number
  /**
   * Which way the hover fan grows from the resting face.
   * Opp piles at the top of the board use `"down"` so cards stay on-screen.
   */
  fanDirection?: "up" | "down"
}

type TrashDrag = {
  instanceId: string
  pointerId: number
  startX: number
  startY: number
  moved: boolean
  ghostX: number
  ghostY: number
}

export const TrashyardPile = forwardRef<HTMLDivElement, TrashyardPileProps>(
  function TrashyardPile(
    {
      cards,
      className,
      label = "Trashyard",
      size = "md",
      onReleaseCard,
      onCardContextMenu,
      onPileContextMenu,
      cardOverlay,
      onToggleExpended,
      scale = 1,
      fanDirection = "up",
    },
    ref
  ) {
    const { w: cardW, h: cardH, peek: fanPeek } = scalePlayPile(size, scale)
    const revealShift = Math.round(cardH * 0.75)
    const fanDown = fanDirection === "down"
    const cardBoxClass = "h-full w-full"
    const measureRef = useRef<HTMLDivElement | null>(null)

    const [pileHovered, setPileHovered] = useState(false)
    /** Index into `groups` — covering cards above this slide away. */
    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null)
    /** Keeps the fan mounted for the whole drag if the gesture started expanded. */
    const [fanLocked, setFanLocked] = useState(false)
    const [drag, setDrag] = useState<TrashDrag | null>(null)
    const [enlarged, setEnlarged] = useState<PlayingCardInstance | null>(null)
    const dragRef = useRef<TrashDrag | null>(null)
    const onReleaseRef = useLatestRef(onReleaseCard)
    const [paintScale, setPaintScale] = useState({ sx: 1, sy: 1 })

    useLayoutEffect(() => {
      const el = measureRef.current
      if (!el) return
      const sync = () => setPaintScale(elementCssPaintScale(el))
      const raf = requestAnimationFrame(sync)
      const observer = new ResizeObserver(sync)
      observer.observe(el)
      return () => {
        cancelAnimationFrame(raf)
        observer.disconnect()
      }
    }, [])

    const groups = groupTrashCards(cards)
    const topCard = cards.length > 0 ? cards[cards.length - 1]! : null
    const expanded = (pileHovered || fanLocked) && groups.length > 0

    const dragging = drag
    const ghostCard = dragging
      ? cards.find((c) => c.instanceId === dragging.instanceId)
      : null

    // Window listeners survive leaving the pile / card bounds.
    useEffect(() => {
      if (!drag) return

      function onMove(event: PointerEvent) {
        const current = dragRef.current
        if (!current || current.pointerId !== event.pointerId) return
        const dist = Math.hypot(
          event.clientX - current.startX,
          event.clientY - current.startY
        )
        if (dist <= DRAG_THRESHOLD_PX && !current.moved) return
        const next: TrashDrag = {
          ...current,
          moved: true,
          ghostX: event.clientX,
          ghostY: event.clientY,
        }
        dragRef.current = next
        setDrag(next)
      }

      function onUp(event: PointerEvent) {
        const current = dragRef.current
        if (!current || current.pointerId !== event.pointerId) return
        dragRef.current = null
        setDrag(null)
        setFanLocked(false)
        setPileHovered(false)
        setHoveredIndex(null)
        if (!current.moved) return
        onReleaseRef.current(
          current.instanceId,
          event.clientX,
          event.clientY
        )
      }

      window.addEventListener("pointermove", onMove)
      window.addEventListener("pointerup", onUp)
      window.addEventListener("pointercancel", onUp)
      return () => {
        window.removeEventListener("pointermove", onMove)
        window.removeEventListener("pointerup", onUp)
        window.removeEventListener("pointercancel", onUp)
      }
    }, [drag])

    useEffect(() => {
      if (!enlarged) return
      function release() {
        setEnlarged(null)
      }
      window.addEventListener("pointerup", release)
      window.addEventListener("blur", release)
      return () => {
        window.removeEventListener("pointerup", release)
        window.removeEventListener("blur", release)
      }
    }, [enlarged])

    function onCardPointerDown(
      event: ReactPointerEvent<HTMLDivElement>,
      instanceId: string
    ) {
      if (event.button === 1) {
        event.preventDefault()
        event.stopPropagation()
        const card = cards.find((c) => c.instanceId === instanceId)
        if (card) setEnlarged(card)
        return
      }
      if (event.button !== 0) return
      event.preventDefault()
      // If the fan is open, lock it open until pointer-up (avoids unmount mid-drag).
      if (pileHovered || fanLocked) setFanLocked(true)
      setHoveredIndex(null)
      const next: TrashDrag = {
        instanceId,
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        moved: false,
        ghostX: event.clientX,
        ghostY: event.clientY,
      }
      dragRef.current = next
      setDrag(next)
    }

    function dragInstanceIdForGroup(group: TrashGroup): string {
      return group.instances[group.instances.length - 1]!.instanceId
    }

    function onCardDoubleClick(
      event: ReactMouseEvent<HTMLDivElement>,
      instanceId: string
    ) {
      if (!onToggleExpended) return
      event.preventDefault()
      event.stopPropagation()
      onToggleExpended(instanceId)
    }

    const { sx: paintSx, sy: paintSy } = paintScale

    return (
      <>
        <div
          ref={(node) => {
            measureRef.current = node
            if (typeof ref === "function") ref(node)
            else if (ref) ref.current = node
          }}
          className={cn(
            "relative flex shrink-0 flex-col items-center self-stretch",
            expanded ? "z-50" : "z-40",
            className
          )}
          style={{ width: cardW }}
        >
          <div
            className="relative shrink-0 overflow-visible"
            style={{ width: cardW, height: cardH }}
            onMouseEnter={() => {
              if (!dragRef.current) setPileHovered(true)
            }}
            onMouseLeave={() => {
              if (!dragRef.current) {
                setPileHovered(false)
                setHoveredIndex(null)
              }
            }}
          >
            {cards.length === 0 ? (
              <div
                className={cn(
                  "absolute inset-x-0 flex items-center justify-center",
                  fanDown ? "top-0" : "bottom-0",
                  "border border-dashed border-cyan-500/25 bg-black/40 clip-angled"
                )}
                style={{ height: cardH }}
                onContextMenu={(event) => {
                  event.preventDefault()
                  event.stopPropagation()
                  onPileContextMenu?.(event.clientX, event.clientY)
                }}
              >
                <span className="font-mono text-[10px] text-white/35">Empty</span>
              </div>
            ) : expanded ? (
              groups.map((group, index) => {
                const qty = group.instances.length
                const instanceId = dragInstanceIdForGroup(group)
                const isDragging =
                  dragging?.instanceId === instanceId && dragging.moved
                const isHovered =
                  hoveredIndex === index && !dragging?.moved
                // Higher index sits further along the fan; covering cards slide
                // away from the resting edge to uncover the hovered face.
                const isCovering =
                  hoveredIndex != null &&
                  index > hoveredIndex &&
                  !isHovered &&
                  !dragging?.moved

                return (
                  <div
                    key={group.cardId}
                    className={cn(
                      "absolute left-0 touch-none select-none",
                      "origin-center transition-[transform,filter] duration-220 ease-out",
                      isDragging
                        ? "cursor-grabbing opacity-30"
                        : "cursor-grab"
                    )}
                    style={{
                      ...(fanDown
                        ? { top: index * fanPeek }
                        : { bottom: index * fanPeek }),
                      width: cardW,
                      height: cardH,
                      zIndex: index + 1,
                      transform: [
                        isHovered
                          ? "scale(1.06)"
                          : isCovering
                            ? `translateY(${fanDown ? revealShift : -revealShift}px)`
                            : "translateY(0) scale(1)",
                        group.display.expended ? "rotate(90deg)" : "",
                      ]
                        .filter(Boolean)
                        .join(" "),
                      filter: isHovered
                        ? "brightness(1.08)"
                        : isCovering
                          ? "brightness(0.88)"
                          : "brightness(0.95)",
                    }}
                    onMouseEnter={() => {
                      if (!dragRef.current) setHoveredIndex(index)
                    }}
                    onPointerDown={(event) =>
                      onCardPointerDown(event, instanceId)
                    }
                    onDoubleClick={(event) =>
                      onCardDoubleClick(event, instanceId)
                    }
                    onContextMenu={(event) => {
                      event.preventDefault()
                      event.stopPropagation()
                      onCardContextMenu?.(
                        instanceId,
                        event.clientX,
                        event.clientY
                      )
                    }}
                  >
                    <PlayingCard
                      card={group.display}
                      className={cardBoxClass}
                    />
                    {qty > 1 ? (
                      <span
                        className={cn(
                          "pointer-events-none absolute bottom-1 right-1 z-10",
                          "border border-cyan-400/50 bg-black/80 px-1.5 py-0.5",
                          "font-mono text-[10px] text-cyan-100"
                        )}
                      >
                        ×{qty}
                      </span>
                    ) : null}
                  </div>
                )
              })
            ) : (
              <div
                className={cn(
                  "absolute inset-x-0 touch-none select-none origin-center transition-transform duration-250 ease-out",
                  fanDown ? "top-0" : "bottom-0",
                  dragging?.moved ? "cursor-grabbing opacity-30" : "cursor-grab",
                  topCard?.expended && "rotate-90"
                )}
                style={{ width: cardW, height: cardH }}
                onPointerDown={(event) => {
                  if (topCard) onCardPointerDown(event, topCard.instanceId)
                }}
                onDoubleClick={(event) => {
                  if (topCard) onCardDoubleClick(event, topCard.instanceId)
                }}
                onContextMenu={(event) => {
                  if (!topCard) return
                  event.preventDefault()
                  event.stopPropagation()
                  onCardContextMenu?.(
                    topCard.instanceId,
                    event.clientX,
                    event.clientY
                  )
                }}
              >
                {topCard ? (
                  <PlayingCard card={topCard} className={cardBoxClass} />
                ) : null}
              </div>
            )}

            {cardOverlay ? (
              <div className="pointer-events-auto absolute top-1 right-1 z-30">
                {cardOverlay}
              </div>
            ) : null}
          </div>
          <p className="pointer-events-none mt-1 whitespace-nowrap font-mono text-[10px] tracking-wide text-cyan-100/70">
            {label} · {cards.length}
          </p>
        </div>

        {ghostCard && dragging?.moved
          ? createPortal(
              <div
                className="pointer-events-none fixed z-[80] -translate-x-1/2 -translate-y-1/2"
                style={{
                  left: dragging.ghostX,
                  top: dragging.ghostY,
                  width: cardW * paintSx,
                  height: cardH * paintSy,
                }}
              >
                <PlayingCard
                  card={ghostCard}
                  className={cn(
                    cardBoxClass,
                    "shadow-lg shadow-cyan-500/20",
                    ghostCard.expended && "rotate-90"
                  )}
                />
              </div>,
              document.body
            )
          : null}

        <CardEnlargeOverlay
          open={enlarged != null}
          name={enlarged?.name ?? ""}
          artSrc={
            enlarged ? cardArtUrl(enlarged.artPath, enlarged.artVersion) : null
          }
        />
      </>
    )
  }
)

/**
 * Room WebSocket + host-authoritative WebRTC datachannel.
 * Same compact messages on the channel; WS relay if ICE never opens.
 */

import { useCallback, useEffect, useRef, useState } from "react"

import {
  iceServersFromEnv,
  isPlayNetMessage,
  PLAY_ICE_TIMEOUT_MS,
  type PlayNetMessage,
  type PlayTransport,
  type SignalPayload,
} from "@/components/Playtester/playNet.logic"
import type { PlayerSlot } from "@/components/Playtester/playtesterConstants"
import { useLatestRef } from "@/hooks/useLatestRef"
import { createPlayRoom, playWsUrl } from "@/lib/api/playRooms"

export type PlayNetStatus =
  | "idle"
  | "connecting"
  | "waiting"
  | "connected"
  | "disconnected"

export type UsePlayNetArgs = {
  token: string | null
  localDeckId: number
}

export function usePlayNet({ token, localDeckId }: UsePlayNetArgs) {
  const [code, setCode] = useState<string | null>(null)
  const [status, setStatus] = useState<PlayNetStatus>("idle")
  const [transport, setTransport] = useState<PlayTransport>("connecting")
  const [seat, setSeat] = useState<PlayerSlot | null>(null)
  const [isHost, setIsHost] = useState(false)
  const [peerDeckId, setPeerDeckId] = useState<number | null>(null)
  const [peerPresent, setPeerPresent] = useState(false)
  /**
   * Sticky once the other seat has been filled. Deck fetches send this as
   * `?room=` to pool preview/unpublished access across both players; keeping it
   * set through a dropped peer avoids re-redacting cards mid-game.
   */
  const [peerSeated, setPeerSeated] = useState(false)
  const [errorText, setErrorText] = useState<string | null>(null)

  const wsRef = useRef<WebSocket | null>(null)
  /** Bumped on every connect attempt so a superseded socket's onclose is ignored. */
  const connectGenRef = useRef(0)
  const joiningRef = useRef(false)
  /** After Leave room — block URL auto-join until the user creates/joins again. */
  const blockAutoJoinRef = useRef(false)
  const pcRef = useRef<RTCPeerConnection | null>(null)
  const dcRef = useRef<RTCDataChannel | null>(null)
  const iceQueueRef = useRef<RTCIceCandidateInit[]>([])
  const remoteSetRef = useRef(false)
  const iceTimerRef = useRef<number | null>(null)
  const handlersRef = useRef<{
    onIntent?: (action: PlayNetMessage & { type: "intent" }) => void
    onFog?: (view: Extract<PlayNetMessage, { type: "fog" }>["view"]) => void
    onSnapshot?: () => void
    onHover?: (msg: Extract<PlayNetMessage, { type: "hover" }>) => void
    onFx?: (fx: Extract<PlayNetMessage, { type: "fx" }>["fx"]) => void
  }>({})

  const tokenRef = useLatestRef(token)
  const deckIdRef = useLatestRef(localDeckId)
  const isHostRef = useLatestRef(isHost)
  const codeRef = useLatestRef(code)

  const sendWs = useCallback((msg: PlayNetMessage) => {
    const ws = wsRef.current
    if (!ws || ws.readyState !== WebSocket.OPEN) return
    ws.send(JSON.stringify(msg))
  }, [])

  const send = useCallback(
    (msg: PlayNetMessage) => {
      const dc = dcRef.current
      if (dc && dc.readyState === "open") {
        dc.send(JSON.stringify(msg))
        return
      }
      sendWs(msg)
    },
    [sendWs]
  )

  const handleGameMessage = useCallback((raw: unknown) => {
    if (!isPlayNetMessage(raw)) return
    if (raw.type === "intent") {
      handlersRef.current.onIntent?.(raw)
      return
    }
    if (raw.type === "fog") {
      handlersRef.current.onFog?.(raw.view)
      return
    }
    if (raw.type === "snapshot") {
      handlersRef.current.onSnapshot?.()
      return
    }
    if (raw.type === "hover") {
      handlersRef.current.onHover?.(raw)
      return
    }
    if (raw.type === "fx") {
      handlersRef.current.onFx?.(raw.fx)
    }
  }, [])

  const bindDataChannel = useCallback(
    (dc: RTCDataChannel) => {
      dcRef.current = dc
      dc.onopen = () => {
        setTransport("p2p")
        if (iceTimerRef.current != null) {
          window.clearTimeout(iceTimerRef.current)
          iceTimerRef.current = null
        }
      }
      dc.onclose = () => {
        if (dcRef.current === dc) {
          dcRef.current = null
          setTransport((prev) => (prev === "p2p" ? "relay" : prev))
        }
      }
      dc.onmessage = (event) => {
        try {
          handleGameMessage(JSON.parse(String(event.data)))
        } catch {
          /* ignore malformed */
        }
      }
    },
    [handleGameMessage]
  )

  const closePeer = useCallback(() => {
    if (iceTimerRef.current != null) {
      window.clearTimeout(iceTimerRef.current)
      iceTimerRef.current = null
    }
    dcRef.current?.close()
    dcRef.current = null
    pcRef.current?.close()
    pcRef.current = null
    iceQueueRef.current = []
    remoteSetRef.current = false
  }, [])

  const startIceTimer = useCallback(() => {
    if (iceTimerRef.current != null) window.clearTimeout(iceTimerRef.current)
    iceTimerRef.current = window.setTimeout(() => {
      iceTimerRef.current = null
      if (dcRef.current?.readyState !== "open") {
        setTransport("relay")
      }
    }, PLAY_ICE_TIMEOUT_MS)
  }, [])

  const ensurePeer = useCallback(() => {
    if (pcRef.current) return pcRef.current
    const pc = new RTCPeerConnection({ iceServers: iceServersFromEnv() })
    pcRef.current = pc
    pc.onicecandidate = (event) => {
      if (!event.candidate) return
      sendWs({
        type: "signal",
        payload: { kind: "ice", candidate: event.candidate.toJSON() },
      })
    }
    pc.oniceconnectionstatechange = () => {
      const state = pc.iceConnectionState
      if (state === "failed" || state === "disconnected") {
        if (dcRef.current?.readyState !== "open") setTransport("relay")
      }
    }
    pc.ondatachannel = (event) => {
      bindDataChannel(event.channel)
    }
    startIceTimer()
    return pc
  }, [bindDataChannel, sendWs, startIceTimer])

  const applySignal = useCallback(
    async (payload: SignalPayload) => {
      const pc = ensurePeer()
      if (payload.kind === "offer") {
        await pc.setRemoteDescription(payload.sdp)
        remoteSetRef.current = true
        for (const c of iceQueueRef.current) {
          await pc.addIceCandidate(c)
        }
        iceQueueRef.current = []
        const answer = await pc.createAnswer()
        await pc.setLocalDescription(answer)
        sendWs({
          type: "signal",
          payload: { kind: "answer", sdp: pc.localDescription ?? answer },
        })
        return
      }
      if (payload.kind === "answer") {
        await pc.setRemoteDescription(payload.sdp)
        remoteSetRef.current = true
        for (const c of iceQueueRef.current) {
          await pc.addIceCandidate(c)
        }
        iceQueueRef.current = []
        return
      }
      if (!remoteSetRef.current) {
        iceQueueRef.current.push(payload.candidate)
        return
      }
      await pc.addIceCandidate(payload.candidate)
    },
    [ensurePeer, sendWs]
  )

  const startHostOffer = useCallback(async () => {
    const pc = ensurePeer()
    if (dcRef.current) return
    const dc = pc.createDataChannel("play", { ordered: true })
    bindDataChannel(dc)
    const offer = await pc.createOffer()
    await pc.setLocalDescription(offer)
    sendWs({
      type: "signal",
      payload: { kind: "offer", sdp: pc.localDescription ?? offer },
    })
  }, [bindDataChannel, ensurePeer, sendWs])

  const connectSocket = useCallback(
    (roomCode: string) => {
      const auth = tokenRef.current
      if (!auth) {
        setErrorText("Sign in to join a room.")
        joiningRef.current = false
        return
      }
      const gen = ++connectGenRef.current
      const prev = wsRef.current
      wsRef.current = null
      prev?.close()
      closePeer()
      setCode(roomCode)
      setStatus("connecting")
      setTransport("connecting")
      setErrorText(null)
      setPeerPresent(false)
      setPeerSeated(false)
      setPeerDeckId(null)

      const ws = new WebSocket(playWsUrl(roomCode, auth))
      wsRef.current = ws

      ws.onopen = () => {
        if (gen !== connectGenRef.current) return
        joiningRef.current = false
        setStatus("waiting")
      }
      ws.onclose = () => {
        if (gen !== connectGenRef.current) return
        if (wsRef.current === ws) {
          wsRef.current = null
          joiningRef.current = false
          setStatus((prevStatus) => {
            if (prevStatus === "idle") return prevStatus
            // Closed before welcome — usually stale seat map / 4409, not mid-game drop.
            if (prevStatus === "connecting") {
              setErrorText("Could not enter room. Leave and create/join again.")
            }
            return "disconnected"
          })
        }
      }
      ws.onerror = () => {
        if (gen !== connectGenRef.current) return
        setErrorText("Room socket failed.")
      }
      ws.onmessage = (event) => {
        if (gen !== connectGenRef.current) return
        let raw: unknown
        try {
          raw = JSON.parse(String(event.data))
        } catch {
          return
        }
        if (!isPlayNetMessage(raw)) return
        if (raw.type === "welcome") {
          if (isHostRef.current) {
            setIsHost(true)
            setSeat("p1")
          } else {
            setSeat(raw.seat)
            setIsHost(raw.host)
          }
          sendWs({ type: "join", deckId: deckIdRef.current })
          if (raw.peer) setPeerSeated(true)
          if (raw.peer?.deckId) {
            const id = Number(raw.peer.deckId)
            if (Number.isFinite(id) && id > 0) setPeerDeckId(id)
          }
          if (raw.peer?.connected) {
            setPeerPresent(true)
            setStatus("connected")
            if (raw.host) {
              void startHostOffer()
            }
          }
          if (!raw.host) {
            send({ type: "snapshot" })
          }
          return
        }
        if (raw.type === "peer-joined") {
          setPeerPresent(true)
          setPeerSeated(true)
          setStatus("connected")
          if (isHostRef.current) {
            void startHostOffer()
          } else {
            closePeer()
            setTransport("connecting")
          }
          return
        }
        if (raw.type === "peer-left") {
          setPeerPresent(false)
          setStatus("waiting")
          closePeer()
          setTransport("connecting")
          return
        }
        if (raw.type === "seat-deck") {
          const id = Number(raw.deckId)
          if (Number.isFinite(id) && id > 0) setPeerDeckId(id)
          setPeerPresent(true)
          setPeerSeated(true)
          setStatus("connected")
          return
        }
        if (raw.type === "signal") {
          void applySignal(raw.payload)
          return
        }
        handleGameMessage(raw)
      }
    },
    [applySignal, closePeer, handleGameMessage, send, sendWs, startHostOffer]
  )

  const createRoom = useCallback(async () => {
    if (!tokenRef.current) {
      setErrorText("Sign in to create a room.")
      return
    }
    if (!Number.isFinite(deckIdRef.current) || deckIdRef.current <= 0) {
      setErrorText("Load a deck first.")
      return
    }
    blockAutoJoinRef.current = false
    isHostRef.current = true
    setIsHost(true)
    setSeat("p1")
    setStatus("connecting")
    try {
      const created = await createPlayRoom(deckIdRef.current, tokenRef.current)
      connectSocket(created.code)
    } catch {
      isHostRef.current = false
      setIsHost(false)
      setSeat(null)
      setStatus("idle")
      setErrorText("Could not create a room.")
    }
  }, [connectSocket])

  const joinRoom = useCallback(
    (roomCode: string) => {
      const trimmed = roomCode.trim().toUpperCase()
      if (trimmed.length < 4) {
        setErrorText("Enter a room code.")
        return
      }
      if (!tokenRef.current) {
        setErrorText("Sign in to join a room.")
        return
      }
      if (joiningRef.current && codeRef.current === trimmed) return
      blockAutoJoinRef.current = false
      joiningRef.current = true
      // Reconnect keeps host flag if this client created the room.
      if (!isHostRef.current) {
        setIsHost(false)
        setSeat("p2")
      }
      connectSocket(trimmed)
    },
    [connectSocket]
  )

  const leaveRoom = useCallback(() => {
    blockAutoJoinRef.current = true
    connectGenRef.current += 1
    joiningRef.current = false
    wsRef.current?.close()
    wsRef.current = null
    closePeer()
    setCode(null)
    setSeat(null)
    setIsHost(false)
    isHostRef.current = false
    setPeerDeckId(null)
    setPeerPresent(false)
    setPeerSeated(false)
    setStatus("idle")
    setTransport("connecting")
    setErrorText(null)
  }, [closePeer])

  /** URL `?room=` auto-join — false after an intentional Leave until create/join. */
  const allowAutoJoin = useCallback(() => !blockAutoJoinRef.current, [])

  useEffect(() => {
    return () => {
      wsRef.current?.close()
      closePeer()
    }
  }, [closePeer])

  const setHandlers = useCallback(
    (handlers: typeof handlersRef.current) => {
      handlersRef.current = handlers
    },
    []
  )

  return {
    code,
    status,
    transport,
    seat,
    isHost,
    peerDeckId,
    peerPresent,
    /** Room code to send with deck fetches, or null when no pooling applies. */
    poolRoom: peerSeated ? code : null,
    errorText,
    createRoom,
    joinRoom,
    leaveRoom,
    allowAutoJoin,
    send,
    setHandlers,
  }
}

/**
 * Playtester session core: card bag + turn/life/pilot.
 * Table mutations go through `dispatch` → `applyAction`. Selection stays local.
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type MutableRefObject,
  type SetStateAction,
} from "react"

import type { ResourceColor } from "@/components/Playtester/accumulateResources.logic"
import { useLatestRef } from "@/hooks/useLatestRef"
import {
  viewToWorld,
} from "@/components/Playtester/augmentRow.logic"
import { peekTopLibrary } from "@/components/Playtester/deckActions.logic"
import { PLAY_FLOAT_LOGICAL } from "@/components/Playtester/playFieldScale.logic"
import {
  LOCAL_SEAT,
  OPENING_MULLIGAN_ENABLED,
  PLAY_ZONE,
  otherSeat,
  type PlayerSlot,
} from "@/components/Playtester/playtesterConstants"
import {
  setupOpeningSession,
  startingLifeFromPilot,
} from "@/components/Playtester/setupOpeningSession.logic"
import {
  applyAction,
  cardsInZone,
  createPlaySessionState,
  materializeFog,
  seatRecord,
  type CardCounterKind,
  type FogView,
  type MoveAllDestinationZone,
  type MoveAllSourceZone,
  type PlaySessionState,
  type PlayingCardInstance,
  type SessionAction,
} from "@/components/Playtester/types"
import { pilotCard } from "@/components/decks/deck.logic"
import type { CardLibraryItem } from "@/lib/api/cards"
import type { DeckDetail } from "@/lib/api/decks"
import type { DeckLoadStatus } from "@/hooks/useDeckDetail"

/** Animation / timer side-effects the page wires after `useDrawAnimations`. */
export type PlaySessionEffects = {
  clearDrawTimers: () => void
  queueStockpileTimeCompletions: (launching: PlayingCardInstance[]) => void
  queueDrawsToHand: (count: number) => void
}

export type PlayNetRole = "local" | "host" | "guest"

export type UsePlaySessionArgs = {
  status: DeckLoadStatus
  deck: DeckDetail | null
  opponentDeck?: DeckDetail | null
  resourceByColor: Map<ResourceColor, CardLibraryItem>
  resourcesReady: boolean
  effectsRef: MutableRefObject<Partial<PlaySessionEffects>>
  /**
   * Seat rendered at the bottom of the table. Hotseat flips this to look from
   * the other side; it never changes who owns which cards.
   */
  localSeat?: PlayerSlot
  /**
   * Seat `deck` is dealt to — the seat this client actually holds. Kept apart
   * from `localSeat` so swapping the view never re-deals the table.
   */
  mySeat?: PlayerSlot
  /** local = solo/hotseat; host applies; guest sends intents and hydrates fog. */
  netRole?: PlayNetRole
  /** Host: true once the other socket is in the room (even before their deck loads). */
  peerPresent?: boolean
  sendIntent?: (action: SessionAction) => void
  onHostCommit?: (action: SessionAction | null, state: PlaySessionState) => void
}

export function usePlaySession({
  status,
  deck,
  opponentDeck = null,
  resourceByColor,
  resourcesReady,
  effectsRef,
  localSeat = LOCAL_SEAT,
  mySeat = LOCAL_SEAT,
  netRole = "local",
  peerPresent = false,
  sendIntent,
  onHostCommit,
}: UsePlaySessionArgs) {
  const [sessionCardsState, setSessionCardsState] = useState<
    PlayingCardInstance[]
  >([])
  const sessionCardsRef = useLatestRef(sessionCardsState)

  const [lifeBySeat, setLifeBySeat] = useState(seatRecord(0))
  const [turn, setTurn] = useState(1)
  const [turnSeat, setTurnSeat] = useState<PlayerSlot>(LOCAL_SEAT)
  const [pilotGenBySeat, setPilotGenBySeat] = useState(seatRecord(0))
  const [pilotHandBySeat, setPilotHandBySeat] = useState(seatRecord(0))
  const [mulliganOpen, setMulliganOpen] = useState(false)
  const [topRevealed, setTopRevealed] = useState(false)
  const rngRef = useRef(1)
  const nextIdRef = useRef(1)
  const seqRef = useRef(0)
  const fogCountsRef = useRef<{
    hand: { p1: number; p2: number }
    library: { p1: number; p2: number }
  } | null>(null)
  const [fogCounts, setFogCounts] = useState<{
    hand: { p1: number; p2: number }
    library: { p1: number; p2: number }
  } | null>(null)
  const guestMulliganArmed = useRef(false)
  const guestPlaceholderDealt = useRef(false)
  const netRoleRef = useLatestRef(netRole)
  const sendIntentRef = useLatestRef(sendIntent)
  const onHostCommitRef = useLatestRef(onHostCommit)
  const lifeRef = useLatestRef(lifeBySeat)
  const turnRef = useLatestRef(turn)
  const turnSeatRef = useLatestRef(turnSeat)
  const pilotGenRef = useLatestRef(pilotGenBySeat)

  const setSessionCards: Dispatch<SetStateAction<PlayingCardInstance[]>> = (
    action
  ) => {
    setSessionCardsState((prev) => {
      const next = typeof action === "function" ? action(prev) : action
      sessionCardsRef.current = next
      return next
    })
  }

  function commitCards(next: PlayingCardInstance[]) {
    sessionCardsRef.current = next
    setSessionCardsState(next)
  }

  const snapshot = useCallback(
    () =>
      createPlaySessionState({
        cards: sessionCardsRef.current,
        life: lifeRef.current,
        turn: turnRef.current,
        turnSeat: turnSeatRef.current,
        pilotGenBonus: pilotGenRef.current,
        rng: rngRef.current,
        nextId: nextIdRef.current,
        seq: seqRef.current,
      }),
    []
  )

  const dispatch = useCallback(
    (action: SessionAction) => {
      if (netRoleRef.current === "guest") {
        sendIntentRef.current?.(action)
        // Keep local seq behind host — fog will set seq. Optimistic so
        // release / expend don't wait on RTT (snap-back / missed spin).
        if (action.t === "ps" || action.t === "xp" || action.t === "rdy") {
          const next = applyAction(snapshot(), action)
          commitCards(next.cards)
        }
        return snapshot()
      }
      const next = applyAction(snapshot(), action)
      rngRef.current = next.rng
      nextIdRef.current = next.nextId
      seqRef.current = next.seq
      commitCards(next.cards)
      setLifeBySeat(next.life)
      setTurn(next.turn)
      setTurnSeat(next.turnSeat)
      setPilotGenBySeat(next.pilotGenBonus)
      onHostCommitRef.current?.(action, next)
      return next
    },
    [snapshot]
  )

  const applyFog = useCallback((view: FogView) => {
    const nextCards = materializeFog(view)
    const viewerHasCards = nextCards.some((c) => c.owner === view.viewer)
    const viewerCounts =
      (view.handCount[view.viewer] ?? 0) + (view.libraryCount[view.viewer] ?? 0)
    if (!viewerHasCards && viewerCounts === 0 && view.seq === 0) {
      return
    }
    seqRef.current = view.seq
    commitCards(nextCards)
    setLifeBySeat(view.life)
    setTurn(view.turn)
    setTurnSeat(view.turnSeat)
    setPilotGenBySeat(view.pilotGenBonus ?? { p1: 0, p2: 0 })
    const counts = { hand: view.handCount, library: view.libraryCount }
    fogCountsRef.current = counts
    setFogCounts(counts)
    if (OPENING_MULLIGAN_ENABLED && view.seq === 0) {
      guestMulliganArmed.current = false
    }
    if (
      OPENING_MULLIGAN_ENABLED &&
      !guestMulliganArmed.current &&
      cardsInZone(nextCards, PLAY_ZONE.hand, view.viewer).length > 0
    ) {
      guestMulliganArmed.current = true
      setMulliganOpen(true)
    }
  }, [])

  // Opponent row only when a second deck exists, or this client is the guest
  // waiting on / rendering a fog view. Creating a room must not flip the
  // local table — host keeps the solo layout until someone joins.
  const twoSeat =
    Boolean(opponentDeck) ||
    netRole === "guest" ||
    (netRole === "host" && peerPresent)

  useEffect(() => {
    if (status !== "ready" || !deck) {
      commitCards([])
      setLifeBySeat(seatRecord(0))
      setTurn(1)
      setTurnSeat(LOCAL_SEAT)
      setPilotGenBySeat(seatRecord(0))
      setPilotHandBySeat(seatRecord(0))
      setMulliganOpen(false)
      setTopRevealed(false)
      effectsRef.current.clearDrawTimers?.()
      return
    }
    if (netRole === "guest") {
      if (!fogCountsRef.current && !guestPlaceholderDealt.current) {
        guestPlaceholderDealt.current = true
        const mine = setupOpeningSession(deck, resourceByColor, mySeat)
        const pilot = pilotCard(deck.cards, deck.categories)
        commitCards(mine)
        setLifeBySeat((prev) => ({
          ...prev,
          [mySeat]: startingLifeFromPilot(pilot),
        }))
        setPilotHandBySeat((prev) => ({
          ...prev,
          [mySeat]: Math.max(0, Math.floor(pilot?.hand_size ?? 0)),
        }))
        setTurnSeat(mySeat)
        if (OPENING_MULLIGAN_ENABLED) {
          setMulliganOpen(cardsInZone(mine, "hand", mySeat).length > 0)
        }
      }
      return
    }
    guestPlaceholderDealt.current = false
    if (!resourcesReady) return
    // Host waiting for a guest: keep the current solo deal at the bottom.
    // Re-deal both seats only once the opponent deck is actually loaded.
    if ((twoSeat || netRole === "host") && !opponentDeck) return

    const theirSeat = otherSeat(mySeat)
    const mine = setupOpeningSession(deck, resourceByColor, mySeat)
    const theirs = opponentDeck
      ? setupOpeningSession(opponentDeck, resourceByColor, theirSeat)
      : []
    const opening = [...mine, ...theirs]
    const pilot = pilotCard(deck.cards, deck.categories)
    const oppPilot = opponentDeck
      ? pilotCard(opponentDeck.cards, opponentDeck.categories)
      : null
    rngRef.current = (Date.now() ^ deck.id ^ (opponentDeck?.id ?? 0)) >>> 0
    nextIdRef.current = 1
    seqRef.current = 0
    commitCards(opening)
    const life = seatRecord(0)
    life[mySeat] = startingLifeFromPilot(pilot)
    life[theirSeat] = startingLifeFromPilot(oppPilot)
    const handSizes = seatRecord(0)
    handSizes[mySeat] = Math.max(0, Math.floor(pilot?.hand_size ?? 0))
    handSizes[theirSeat] = Math.max(0, Math.floor(oppPilot?.hand_size ?? 0))
    setLifeBySeat(life)
    setTurn(1)
    setTurnSeat(mySeat)
    setPilotGenBySeat(seatRecord(0))
    setPilotHandBySeat(handSizes)
    if (OPENING_MULLIGAN_ENABLED) {
      setMulliganOpen(cardsInZone(opening, "hand", mySeat).length > 0)
    }
    setTopRevealed(false)
    if (netRole === "host") {
      onHostCommitRef.current?.(
        null,
        createPlaySessionState({
          cards: opening,
          life,
          turn: 1,
          turnSeat: mySeat,
          rng: rngRef.current,
          nextId: nextIdRef.current,
          seq: seqRef.current,
        })
      )
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- resourceByColor identity tracked via resourcesReady+deck
  }, [status, deck, opponentDeck, resourcesReady, resourceByColor, twoSeat, mySeat, netRole])

  const oppSeat = otherSeat(localSeat)

  const handCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.hand, localSeat),
    [sessionCardsState, localSeat]
  )
  const oppHandCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.hand, oppSeat),
    [sessionCardsState, oppSeat]
  )
  const battlefieldCards = useMemo(
    () => sessionCardsState.filter((c) => c.zone === PLAY_ZONE.battlefield),
    [sessionCardsState]
  )
  const localStockpileCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.stockpile, localSeat),
    [sessionCardsState, localSeat]
  )
  const oppStockpileCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.stockpile, oppSeat),
    [sessionCardsState, oppSeat]
  )
  const pilotCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.pilot, localSeat),
    [sessionCardsState, localSeat]
  )
  const oppPilotCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.pilot, oppSeat),
    [sessionCardsState, oppSeat]
  )
  const libraryCount = useMemo(
    () =>
      fogCounts
        ? fogCounts.library[localSeat]
        : cardsInZone(sessionCardsState, PLAY_ZONE.library, localSeat).length,
    [sessionCardsState, localSeat, fogCounts]
  )
  const oppLibraryCount = useMemo(
    () =>
      fogCounts
        ? fogCounts.library[oppSeat]
        : cardsInZone(sessionCardsState, PLAY_ZONE.library, oppSeat).length,
    [sessionCardsState, oppSeat, fogCounts]
  )
  const trashCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.trashyard, localSeat),
    [sessionCardsState, localSeat]
  )
  const oppTrashCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.trashyard, oppSeat),
    [sessionCardsState, oppSeat]
  )
  const dismantledCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.dismantled, localSeat),
    [sessionCardsState, localSeat]
  )
  const oppDismantledCards = useMemo(
    () => cardsInZone(sessionCardsState, PLAY_ZONE.dismantled, oppSeat),
    [sessionCardsState, oppSeat]
  )
  const topLibraryCard = useMemo(
    () =>
      topRevealed
        ? (peekTopLibrary(sessionCardsState, 1, localSeat)[0] ?? null)
        : null,
    [sessionCardsState, topRevealed, localSeat]
  )

  const life = lifeBySeat[localSeat]
  const oppLife = lifeBySeat[oppSeat]
  const pilotGenBonus = pilotGenBySeat[localSeat]
  const oppPilotGenBonus = pilotGenBySeat[oppSeat]
  const pilotHandSize = pilotHandBySeat[localSeat]

  function moveCards(moves: { instanceId: string; x: number; y: number }[]) {
    if (moves.length === 0) return
    dispatch({
      t: "ps",
      i: moves.map((m) => {
        const world = viewToWorld(m.x, m.y, localSeat, PLAY_FLOAT_LOGICAL)
        return { id: m.instanceId, x: world.x, y: world.y }
      }),
    })
  }

  function bringToFront(instanceId: string) {
    dispatch({ t: "fr", i: instanceId })
  }

  function sendToBack(instanceId: string) {
    dispatch({ t: "bk", i: instanceId })
  }

  function toggleExpendedIds(instanceIds: string[]) {
    if (instanceIds.length === 0) return
    dispatch({ t: "xp", i: instanceIds })
  }

  function changeFloatSelection(instanceIds: string[]) {
    const selected = new Set(instanceIds)
    setSessionCards((prev) =>
      prev.map((card) => {
        if (
          card.zone !== PLAY_ZONE.battlefield &&
          card.zone !== PLAY_ZONE.stockpile
        ) {
          return card.selected ? { ...card, selected: false } : card
        }
        const nextSelected = selected.has(card.instanceId)
        return card.selected === nextSelected
          ? card
          : { ...card, selected: nextSelected }
      })
    )
  }

  function changeHandSelection(instanceIds: string[]) {
    const selected = new Set(instanceIds)
    setSessionCards((prev) =>
      prev.map((card) => {
        if (card.zone === PLAY_ZONE.hand && card.owner === localSeat) {
          const nextSelected = selected.has(card.instanceId)
          return card.selected === nextSelected
            ? card
            : { ...card, selected: nextSelected }
        }
        if (
          (card.zone === "battlefield" || card.zone === "stockpile") &&
          card.selected
        ) {
          return { ...card, selected: false }
        }
        return card
      })
    )
  }

  function startTurn(blocked: boolean) {
    if (blocked) return
    const before = sessionCardsRef.current
    const after = dispatch({ t: "rdy", seat: localSeat })
    const launching = after.cards.filter((c) => {
      const prev = before.find((b) => b.instanceId === c.instanceId)
      return (
        prev?.zone === PLAY_ZONE.stockpile &&
        c.zone === PLAY_ZONE.battlefield
      )
    })
    effectsRef.current.queueStockpileTimeCompletions?.(launching)
  }

  function endTurn(blocked: boolean) {
    if (blocked) return
    const targetHand = Math.max(0, pilotHandSize - 2)
    const handCount = cardsInZone(
      sessionCardsRef.current,
      PLAY_ZONE.hand,
      localSeat
    ).length
    const need = Math.max(0, targetHand - handCount)

    if (need > 0) {
      const libCount = cardsInZone(
        sessionCardsRef.current,
        PLAY_ZONE.library,
        localSeat
      ).length
      const drawCount = Math.min(need, libCount)
      const lifeLoss = need - drawCount
      if (lifeLoss > 0) {
        dispatch({ t: "lf", seat: localSeat, d: -lifeLoss })
      }
      if (drawCount > 0) {
        effectsRef.current.queueDrawsToHand?.(drawCount)
      }
    }

    dispatch({ t: "ts", seat: oppSeat })
  }

  function deleteCards(instanceIds: string[]) {
    if (instanceIds.length === 0) return
    dispatch({ t: "rm", i: instanceIds })
  }

  function adjustCounters(
    instanceIds: string[],
    kind: CardCounterKind,
    delta: number
  ) {
    if (instanceIds.length === 0) return
    const before = sessionCardsRef.current
    const after = dispatch({ t: "ct", i: instanceIds, k: kind, d: delta })
    if (kind !== "time") return
    const launching = after.cards.filter((c) => {
      const prev = before.find((b) => b.instanceId === c.instanceId)
      return (
        prev?.zone === PLAY_ZONE.stockpile &&
        c.zone === PLAY_ZONE.battlefield
      )
    })
    effectsRef.current.queueStockpileTimeCompletions?.(launching)
  }

  function spawnResourceColor(
    color: ResourceColor,
    onMissing?: () => void,
    at?: { x: number; y: number }
  ): boolean {
    const template = resourceByColor.get(color)
    if (!template) {
      onMissing?.()
      return false
    }
    const world = at
      ? viewToWorld(at.x, at.y, localSeat, PLAY_FLOAT_LOGICAL)
      : undefined
    dispatch({
      t: "tk",
      seat: localSeat,
      cardId: template.id,
      name: template.card_name,
      artPath: template.card_art_path,
      artVersion: template.card_art_version ?? null,
      cost: Array.isArray(template.cost) ? template.cost.map(String) : [],
      x: world?.x,
      y: world?.y,
    })
    return true
  }

  function adjustPilotGenBonus(delta: number) {
    dispatch({ t: "pg", seat: localSeat, d: delta })
  }

  function putOnLibraryBottom(instanceIds: string[]) {
    dispatch({ t: "lb", i: instanceIds })
  }

  function setFaceDown(instanceIds: string[], faceDown: boolean) {
    dispatch({ t: "fd", i: instanceIds, down: faceDown })
  }

  function duplicateCards(instanceIds: string[]) {
    dispatch({ t: "cp", i: instanceIds })
  }

  function moveAll(from: MoveAllSourceZone, to: MoveAllDestinationZone) {
    dispatch({ t: "ma", seat: localSeat, from, to })
  }

  function putDeckTopOnBottom(count: number) {
    dispatch({ t: "tb", seat: localSeat, n: count })
  }

  function shuffleLibraryCards() {
    dispatch({ t: "sh", seat: localSeat })
  }

  function reorderTop(orderedIds: string[]) {
    dispatch({ t: "ro", seat: localSeat, i: orderedIds })
  }

  function confirmMulligan(selectedIds: string[]) {
    if (selectedIds.length > 0) {
      dispatch({ t: "lb", i: selectedIds })
    }
    setMulliganOpen(false)
    if (selectedIds.length > 0) {
      effectsRef.current.queueDrawsToHand?.(selectedIds.length)
    }
  }

  function finishAccumulateSpawn(
    card: PlayingCardInstance,
    colors: ResourceColor[],
    homes: Array<{ x: number; y: number }> = []
  ) {
    dispatch({ t: "lb", i: [card.instanceId] })
    colors.forEach((color, index) => {
      const template = resourceByColor.get(color)
      if (!template) return
      const at = homes[index]
      const world = at
        ? viewToWorld(at.x, at.y, localSeat, PLAY_FLOAT_LOGICAL)
        : undefined
      dispatch({
        t: "tk",
        seat: localSeat,
        cardId: template.id,
        name: template.card_name,
        artPath: template.card_art_path,
        artVersion: template.card_art_version ?? null,
        cost: Array.isArray(template.cost) ? template.cost.map(String) : [],
        x: world?.x,
        y: world?.y,
      })
    })
  }

  function setLifeForLocal(next: number | ((prev: number) => number)) {
    const current = lifeRef.current[localSeat]
    const value = typeof next === "function" ? next(current) : next
    dispatch({ t: "lf", seat: localSeat, d: value - current })
  }

  return {
    sessionCards: sessionCardsState,
    setSessionCards,
    sessionCardsRef,
    commitCards,
    dispatch,
    applyFog,
    snapshot,
    localSeat,
    oppSeat,
    twoSeat,
    life,
    oppLife,
    setLife: setLifeForLocal,
    lifeBySeat,
    turn,
    turnSeat,
    pilotGenBonus,
    oppPilotGenBonus,
    pilotHandSize,
    mulliganOpen,
    setMulliganOpen,
    topRevealed,
    setTopRevealed,
    handCards,
    oppHandCards,
    battlefieldCards,
    localStockpileCards,
    oppStockpileCards,
    pilotCards,
    oppPilotCards,
    libraryCount,
    oppLibraryCount,
    topLibraryCard,
    trashCards,
    oppTrashCards,
    dismantledCards,
    oppDismantledCards,
    moveCards,
    bringToFront,
    sendToBack,
    toggleExpendedIds,
    changeFloatSelection,
    changeHandSelection,
    startTurn,
    endTurn,
    deleteCards,
    adjustCounters,
    spawnResourceColor,
    adjustPilotGenBonus,
    putOnLibraryBottom,
    setFaceDown,
    duplicateCards,
    moveAll,
    putDeckTopOnBottom,
    shuffleLibraryCards,
    reorderTop,
    confirmMulligan,
    finishAccumulateSpawn,
  }
}

