export type CardLibraryBrowserProps = {
  token?: string | null
  /** Tighter filters + denser grid for the deck side panel. */
  compact?: boolean
  /** Enable HTML5 drag with library sentinel payload (deck editor). */
  draggable?: boolean
  className?: string
  /** Optional heading above filters (compact panel). */
  title?: string
  /**
   * When set (deck editor): left-click adds the card.
   * Detail zoom moves to right-click. Without this, left-click opens detail.
   */
  onCardActivate?: (card: CardLibraryItem) => void | Promise<void>
}

export function CardLibraryBrowser({
  token = null,
  compact = false,
  draggable = false,
  className,
  title,
  onCardActivate,
}: CardLibraryBrowserProps) {
  const suppressClickRef = useRef(false)
  const [facets, setFacets] = useState<CardLibraryFacets>(EMPTY_FACETS)
  const [items, setItems] = useState<CardLibraryItem[]>([])
  const [total, setTotal] = useState(0)
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")
  const [errorText, setErrorText] = useState("")

  const [nameQuery, setNameQuery] = useState("")
  const [debouncedName, setDebouncedName] = useState("")
  const [descriptionQuery, setDescriptionQuery] = useState("")
  const [debouncedDescription, setDebouncedDescription] = useState("")
  const [colors, setColors] = useState<string[]>([])
  const [invokeMin, setInvokeMin] = useState("")
  const [invokeMax, setInvokeMax] = useState("")
  const [typesLine, setTypesLine] = useState("")
  const [superType, setSuperType] = useState("")
  const [subType, setSubType] = useState("")
  const [offset, setOffset] = useState(0)
  const [selected, setSelected] = useState<CardLibraryItem | null>(null)
  const [advancedOpen, setAdvancedOpen] = useState(false)
  /** Compact deck panel: keep advanced filters collapsed so the grid stays large. */
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [pageSize, setPageSize] = useState<PageSizeOption>(() =>
    typeof window === "undefined" ? PAGE_SIZE_DEFAULT : readStoredPageSize()
  )
  const [previewCardMinPx, setPreviewCardMinPx] = useState(() =>
    typeof window === "undefined"
      ? PREVIEW_CARD_DEFAULT_PX
      : readStoredPreviewCardMinPx()
  )

  useEffect(() => {
    try {
      window.localStorage.setItem(PAGE_SIZE_STORAGE_KEY, String(pageSize))
    } catch {
      /* private mode / quota */
    }
  }, [pageSize])

  useEffect(() => {
    try {
      window.localStorage.setItem(
        PREVIEW_CARD_STORAGE_KEY,
        String(previewCardMinPx)
      )
    } catch {
      /* private mode / quota */
    }
  }, [previewCardMinPx])

  useEffect(() => {
    const timer = window.setTimeout(() => setDebouncedName(nameQuery.trim()), 200)
    return () => window.clearTimeout(timer)
  }, [nameQuery])

  useEffect(() => {
    const timer = window.setTimeout(
      () => setDebouncedDescription(descriptionQuery.trim()),
      200
    )
    return () => window.clearTimeout(timer)
  }, [descriptionQuery])

  useEffect(() => {
    let cancelled = false
    fetchCardFacets(token)
      .then((data) => {
        if (!cancelled) setFacets(data)
      })
      .catch(() => {
        /* keep EMPTY_FACETS fallback */
      })
    return () => {
      cancelled = true
    }
  }, [token])

  useEffect(() => {
    setOffset(0)
  }, [
    debouncedName,
    debouncedDescription,
    colors,
    invokeMin,
    invokeMax,
    typesLine,
    superType,
    subType,
    pageSize,
  ])

  useEffect(() => {
    let cancelled = false
    setStatus("loading")
    setErrorText("")

    const min =
      invokeMin.trim() === "" ? null : Number.parseInt(invokeMin, 10)
    const max =
      invokeMax.trim() === "" ? null : Number.parseInt(invokeMax, 10)

    void fetchCardLibrary(
      {
        q: debouncedName || undefined,
        description: debouncedDescription || undefined,
        colors,
        invokeCostMin: Number.isFinite(min) ? min : null,
        invokeCostMax: Number.isFinite(max) ? max : null,
        typesLine: typesLine || undefined,
        superType: superType || undefined,
        subType: subType || undefined,
        limit: pageSize,
        offset,
      },
      token
    )
      .then((result) => {
        if (cancelled) return
        setItems(result.items)
        setTotal(result.total)
        setStatus("ready")
      })
      .catch((error: unknown) => {
        if (cancelled) return
        setStatus("error")
        setItems([])
        setTotal(0)
        setErrorText(
          error instanceof ApiError
            ? "Could not load the card library."
            : "Could not reach the server."
        )
      })

    return () => {
      cancelled = true
    }
  }, [
    debouncedName,
    debouncedDescription,
    colors,
    invokeMin,
    invokeMax,
    typesLine,
    superType,
    subType,
    offset,
    token,
    pageSize,
  ])

  function toggleColor(color: string) {
    setColors((prev) =>
      prev.includes(color) ? prev.filter((c) => c !== color) : [...prev, color]
    )
  }

  function clearFilters() {
    setNameQuery("")
    setDescriptionQuery("")
    setColors([])
    setInvokeMin("")
    setInvokeMax("")
    setTypesLine("")
    setSuperType("")
    setSubType("")
    setOffset(0)
  }

  function onLibraryDragStart(
    event: ReactDragEvent<HTMLButtonElement>,
    card: CardLibraryItem
  ) {
    if (!draggable) {
      event.preventDefault()
      return
    }
    suppressClickRef.current = true
    const payload: DeckCardDragPayload = {
      cardId: card.id,
      fromCategoryId: LIBRARY_DRAG_CATEGORY_ID,
    }
    beginDeckCardDrag(payload)
    const encoded = JSON.stringify(payload)
    event.dataTransfer.setData(DECK_CARD_DRAG_MIME, encoded)
    event.dataTransfer.setData("text/plain", encoded)
    event.dataTransfer.effectAllowed = "copy"
  }

  function onCardButtonClick(card: CardLibraryItem) {
    if (suppressClickRef.current) return
    if (onCardActivate) {
      void onCardActivate(card)
      return
    }
    setSelected(card)
  }

  const pageStart = total === 0 ? 0 : offset + 1
  const pageEnd = Math.min(offset + items.length, total)
  const canPrev = offset > 0
  const canNext = offset + pageSize < total
  const paginationSummary =
    status === "loading"
      ? "Scanning archive…"
      : `${pageStart}–${pageEnd} of ${total}`
  const goPrev = () => setOffset((prev) => Math.max(0, prev - pageSize))
  const goNext = () => setOffset((prev) => prev + pageSize)
  const paginationDisabled = status === "loading"
  const advancedActive =
    descriptionQuery.trim() !== "" ||
    invokeMin.trim() !== "" ||
    invokeMax.trim() !== "" ||
    typesLine !== "" ||
    superType !== "" ||
    subType !== ""

  const paginationBar = (placement: "top" | "bottom") => (
    <SearchPaginationBar
      className={cn(
        compact ? "shrink-0" : undefined,
        placement === "top" ? (compact ? "mb-2" : "mb-3") : compact ? "mt-2" : "mt-3"
      )}
      summary={paginationSummary}
      canPrev={canPrev}
      canNext={canNext}
      disabled={paginationDisabled}
      compact={compact}
      onPrev={goPrev}
      onNext={goNext}
    />
  )

  const previewSizeControl = (
    <div
      className={cn(
        "flex flex-wrap items-center gap-3 border border-cyan-500/35 bg-black/70 px-3 py-2",
        compact ? "shrink-0" : "mb-3"
      )}
    >
      <span className="font-buahs93 shrink-0 text-xs tracking-wide text-cyan-100">
        CARD SIZE
      </span>
      <input
        type="range"
        min={PREVIEW_CARD_MIN_PX}
        max={PREVIEW_CARD_MAX_PX}
        step={4}
        value={previewCardMinPx}
        aria-valuemin={PREVIEW_CARD_MIN_PX}
        aria-valuemax={PREVIEW_CARD_MAX_PX}
        aria-valuenow={previewCardMinPx}
        aria-label="Preview card size"
        onChange={(event) =>
          setPreviewCardMinPx(clampPreviewCardMinPx(Number(event.target.value)))
        }
        className="h-2 min-w-0 flex-1 cursor-pointer accent-cyan-400"
      />
      <span className="w-9 shrink-0 text-right font-mono text-[11px] text-cyan-200/80">
        {previewCardMinPx}px
      </span>
      <label className="flex shrink-0 items-center gap-2 border-l border-cyan-500/25 pl-3">
        <span className="font-buahs93 text-xs tracking-wide text-cyan-100">
          SHOW
        </span>
        <select
          value={pageSize}
          aria-label="Cards per page"
          onChange={(event) => {
            const next = Number(event.target.value)
            if (!isPageSizeOption(next)) return
            setPageSize(next)
            setOffset(0)
          }}
          className={cn(
            "h-8 rounded-none border border-cyan-500/35 bg-black/80 px-2",
            "font-mono text-xs text-cyan-50 outline-none focus-visible:border-cyan-300"
          )}
        >
          {PAGE_SIZE_OPTIONS.map((n) => (
            <option key={n} value={n}>
              {n}
            </option>
          ))}
        </select>
      </label>
    </div>
  )

  const colorCostFilters = (
    <div>
      <p className="mb-2 font-buahs93 text-xs text-cyan-200/70">COLOR COST</p>
      <div className="grid w-fit grid-cols-3 gap-2">
        {facets.colors.map((color) => {
          const on = colors.includes(color)
          const icon = costTokenToIcon(color)
          return (
            <Button
              key={color}
              type="button"
              variant="outline"
              size="icon"
              aria-pressed={on}
              aria-label={`Filter ${color}`}
              title={color}
              className={cn(
                "size-9 overflow-visible rounded-none border",
                on
                  ? "border-cyan-400 bg-cyan-700 hover:bg-cyan-800"
                  : "border-cyan-500/40 bg-black/70 hover:border-cyan-400/70 hover:bg-cyan-500/10"
              )}
              onClick={() => toggleColor(color)}
            >
              {icon ? (
                <GameIcon
                  name={icon}
                  className="!h-5 !w-5 shrink-0 object-contain"
                />
              ) : (
                <span className="font-buahs93 text-[10px] text-cyan-100">
                  {color}
                </span>
              )}
            </Button>
          )
        })}
      </div>
      <GlitchFx
        type="button"
        label="CLEAR FILTERS"
        className={cn(
          secondaryActionClassName,
          compact ? "mt-3 w-full px-2 text-xs" : "mt-4"
        )}
        onClick={clearFilters}
      />
    </div>
  )

  const header = title ? (
    <header
      className={cn(
        compact ? "mb-2 shrink-0 border-b border-cyan-500/20 pb-1.5" : "mb-3"
      )}
    >
      <p className="font-buahs93 text-xs tracking-widest text-cyan-400/70">
        ARCHIVE
      </p>
      <h2
        className={cn(
          "font-glitch text-cyan-300",
          compact ? "mt-0.5 text-lg leading-tight" : "mt-1 text-3xl"
        )}
      >
        {title}
      </h2>
      {!compact && onCardActivate ? (
        <p className="mt-1 font-mono text-[10px] text-white/45">
          Click to add · middle/right-click for details
          {draggable ? " · drag onto a section" : ""}
        </p>
      ) : null}
      {!compact && !onCardActivate && draggable ? (
        <p className="mt-1 font-mono text-[10px] text-white/45">
          Drag a card onto a deck section to add it.
        </p>
      ) : null}
    </header>
  ) : null

  const filterFields = (
    <>
      <div className="space-y-3">
        <CardSearchBar
          label="NAME"
          value={nameQuery}
          onChange={setNameQuery}
          placeholder="Closest name match…"
        />

        <div>
          <button
            type="button"
            aria-expanded={advancedOpen}
            className={cn(
              "flex w-full items-center justify-between border border-cyan-500/30 bg-black/60 px-3 py-2",
              "font-buahs93 text-xs tracking-wide text-cyan-100 hover:border-cyan-400/50 hover:bg-cyan-500/10"
            )}
            onClick={() => setAdvancedOpen((prev) => !prev)}
          >
            <span className="inline-flex items-center gap-2">
              ADVANCED SEARCH
              {advancedActive ? (
                <span
                  className="inline-block size-1.5 rounded-full bg-cyan-400"
                  title="Filters active"
                  aria-label="Advanced filters active"
                />
              ) : null}
            </span>
            <span className="font-mono text-[10px] text-cyan-300/70">
              {advancedOpen ? "▲" : "▼"}
            </span>
          </button>

          {advancedOpen ? (
            <div
              className={cn(
                "mt-2 grid gap-3 border border-cyan-500/20 border-t-0 bg-black/40 p-3",
                !compact && "sm:grid-cols-2"
              )}
            >
              <label className={cn("block", !compact && "sm:col-span-2")}>
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  DESCRIPTION
                </span>
                <EditBox
                  value={descriptionQuery}
                  onChange={(e) => setDescriptionQuery(e.target.value)}
                  placeholder={
                    compact ? "Rules text…" : "Rules text contains…"
                  }
                  size="sm"
                  autoComplete="off"
                />
              </label>

              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  INVOKE MIN
                </span>
                <EditBox
                  value={invokeMin}
                  onChange={(e) =>
                    setInvokeMin(e.target.value.replace(/\D/g, ""))
                  }
                  placeholder={`${facets.invoke_cost_min}`}
                  size="sm"
                  inputMode="numeric"
                />
              </label>

              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  INVOKE MAX
                </span>
                <EditBox
                  value={invokeMax}
                  onChange={(e) =>
                    setInvokeMax(e.target.value.replace(/\D/g, ""))
                  }
                  placeholder={`${facets.invoke_cost_max}`}
                  size="sm"
                  inputMode="numeric"
                />
              </label>

              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  TYPE LINE
                </span>
                <select
                  value={typesLine}
                  onChange={(e) => setTypesLine(e.target.value)}
                  className={filterSelectClassName}
                >
                  <option value="">Any</option>
                  {facets.types_lines.map((line) => (
                    <option key={line} value={line}>
                      {line}
                    </option>
                  ))}
                </select>
              </label>

              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  SUPER TYPE
                </span>
                <select
                  value={superType}
                  onChange={(e) => setSuperType(e.target.value)}
                  className={filterSelectClassName}
                >
                  <option value="">Any</option>
                  {facets.super_types.map((value) => (
                    <option key={value} value={value}>
                      {value}
                    </option>
                  ))}
                </select>
              </label>

              <label className={cn("block", !compact && "sm:col-span-2")}>
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  SUB TYPE
                </span>
                <select
                  value={subType}
                  onChange={(e) => setSubType(e.target.value)}
                  className={filterSelectClassName}
                >
                  <option value="">Any</option>
                  {facets.sub_types.map((value) => (
                    <option key={value} value={value}>
                      {value}
                    </option>
                  ))}
                </select>
              </label>
            </div>
          ) : null}
        </div>
      </div>
    </>
  )

  const filters = compact ? (
    <div className="mb-2 shrink-0 space-y-3 border border-cyan-500/25 bg-black/55 p-3">
      <CardSearchBar
        label="NAME"
        value={nameQuery}
        onChange={setNameQuery}
        placeholder="Closest name match…"
      />
      {colorCostFilters}
      {previewSizeControl}
      <div>
        <button
          type="button"
          aria-expanded={filtersOpen}
          className={cn(
            "flex w-full items-center justify-between border border-cyan-500/30 bg-black/60 px-3 py-2",
            "font-buahs93 text-xs tracking-wide text-cyan-100 hover:bg-cyan-500/10"
          )}
          onClick={() => setFiltersOpen((prev) => !prev)}
        >
          <span className="inline-flex min-w-0 items-center gap-2">
            ADVANCED FILTERS
            {advancedActive ? (
              <span
                className="inline-block size-1.5 shrink-0 rounded-full bg-cyan-400"
                title="Filters active"
                aria-label="Advanced filters active"
              />
            ) : null}
          </span>
          <span className="font-mono text-[10px] text-cyan-300/70">
            {filtersOpen ? "▲" : "▼"}
          </span>
        </button>
        {filtersOpen ? (
          <div className="mt-2 space-y-3 border border-cyan-500/20 border-t-0 bg-black/40 p-3">
            <div className="grid gap-3">
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                DESCRIPTION
              </span>
              <EditBox
                value={descriptionQuery}
                onChange={(e) => setDescriptionQuery(e.target.value)}
                placeholder="Rules text…"
                size="sm"
                autoComplete="off"
              />
            </label>
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                INVOKE MIN
              </span>
              <EditBox
                value={invokeMin}
                onChange={(e) =>
                  setInvokeMin(e.target.value.replace(/\D/g, ""))
                }
                placeholder={`${facets.invoke_cost_min}`}
                size="sm"
                inputMode="numeric"
              />
            </label>
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                INVOKE MAX
              </span>
              <EditBox
                value={invokeMax}
                onChange={(e) =>
                  setInvokeMax(e.target.value.replace(/\D/g, ""))
                }
                placeholder={`${facets.invoke_cost_max}`}
                size="sm"
                inputMode="numeric"
              />
            </label>
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                TYPE LINE
              </span>
              <select
                value={typesLine}
                onChange={(e) => setTypesLine(e.target.value)}
                className={filterSelectClassName}
              >
                <option value="">Any</option>
                {facets.types_lines.map((line) => (
                  <option key={line} value={line}>
                    {line}
                  </option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                SUPER TYPE
              </span>
              <select
                value={superType}
                onChange={(e) => setSuperType(e.target.value)}
                className={filterSelectClassName}
              >
                <option value="">Any</option>
                {facets.super_types.map((value) => (
                  <option key={value} value={value}>
                    {value}
                  </option>
                ))}
              </select>
            </label>
            <label className="block">
              <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                SUB TYPE
              </span>
              <select
                value={subType}
                onChange={(e) => setSubType(e.target.value)}
                className={filterSelectClassName}
              >
                <option value="">Any</option>
                {facets.sub_types.map((value) => (
                  <option key={value} value={value}>
                    {value}
                  </option>
                ))}
              </select>
            </label>
          </div>
          </div>
        ) : null}
      </div>
    </div>
  ) : (
    <div className="mb-6 grid gap-4 border border-cyan-500/25 bg-black/55 p-4 lg:grid-cols-[minmax(0,1fr)_14rem]">
      {filterFields}
      {colorCostFilters}
    </div>
  )

  const results = (
    <>
      {errorText ? (
        <p className="mb-4 text-sm text-red-400" role="alert">
          {errorText}
        </p>
      ) : null}

      {status === "ready" && items.length === 0 ? (
        <div className="border border-dashed border-cyan-500/30 bg-black/40 px-4 py-8 text-center">
          <p className="font-buahs93 text-lg text-cyan-200/80">NO MATCHES</p>
          <p className="mt-2 text-sm text-white/50">
            Try a shorter name, fewer colors, or clear filters.
          </p>
        </div>
      ) : null}

      <ul
        className="grid gap-2"
        style={{
          gridTemplateColumns: `repeat(auto-fill, minmax(${previewCardMinPx}px, 1fr))`,
        }}
      >
        {items.map((card) => {
          const art = cardArtUrl(card.card_art_path, card.card_art_version)
          return (
            <li key={card.id}>
              <button
                type="button"
                aria-label={card.card_name}
                title={
                  onCardActivate
                    ? `${card.card_name} — click to add · middle/right-click details${
                        draggable ? " · drag to a section" : ""
                      }`
                    : `${card.card_name} — click or middle-click for details`
                }
                className={cn(
                  "group w-full overflow-hidden border border-cyan-500/20 bg-black/50 transition-colors hover:border-cyan-400/60",
                  draggable && "cursor-grab active:cursor-grabbing"
                )}
                draggable={draggable}
                onDragStart={(event) => onLibraryDragStart(event, card)}
                onDragEnd={() => {
                  endDeckCardDrag()
                  window.setTimeout(() => {
                    suppressClickRef.current = false
                  }, 0)
                }}
                onClick={() => onCardButtonClick(card)}
                onPointerDown={(event) => {
                  // Middle mouse → zoom/detail (stop scroll pan from stealing it).
                  if (event.button !== 1) return
                  event.preventDefault()
                  event.stopPropagation()
                  setSelected(card)
                }}
                onAuxClick={(event) => {
                  if (event.button === 1) event.preventDefault()
                }}
                onContextMenu={(event) => {
                  event.preventDefault()
                  setSelected(card)
                }}
              >
                {art ? (
                  <img
                    src={art}
                    alt=""
                    draggable={false}
                    className="aspect-[2/3] w-full object-cover transition-transform group-hover:scale-[1.02]"
                  />
                ) : (
                  <div className="flex aspect-[2/3] w-full items-center justify-center border border-dashed border-cyan-500/20 font-mono text-[10px] text-cyan-500/40">
                    NO ART
                  </div>
                )}
              </button>
            </li>
          )
        })}
      </ul>
    </>
  )

  // Deck side panel: grow with the grid. Advanced filters expand in-flow.
  if (compact) {
    return (
      <div className={cn("flex min-h-0 flex-col", className)}>
        {header}
        {filters}
        {paginationBar("top")}
        {results}
        {paginationBar("bottom")}
        <CardDetailOverlay card={selected} onClose={() => setSelected(null)} />
      </div>
    )
  }

  return (
    <div className={cn("flex min-h-0 flex-col", className)}>
      {header}
      {filters}
      {paginationBar("top")}
      {previewSizeControl}
      {results}
      {paginationBar("bottom")}
      <CardDetailOverlay card={selected} onClose={() => setSelected(null)} />
    </div>
  )
}

/**
 * Typeahead card search — pick a hit to add it to the deck (Main).
 */

import { useEffect, useId, useRef, useState } from "react"

import { CardSearchBar } from "@/components/cards/CardSearchBar"
import { useLatestRef } from "@/hooks/useLatestRef"
import { searchCards, type CardSearchHit } from "@/lib/api/cards"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"

type DeckCardSearchProps = {
  disabled?: boolean
  /** When set (e.g. admin JWT), search can include unpublished cards. */
  token?: string | null
  onPick: (card: CardSearchHit) => void | Promise<void>
  onOpenChange?: (open: boolean) => void
}

export function DeckCardSearch({
  disabled = false,
  token = null,
  onPick,
  onOpenChange,
}: DeckCardSearchProps) {
  const listId = useId()
  const inputId = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const onOpenChangeRef = useLatestRef(onOpenChange)
  const [query, setQuery] = useState("")
  const [hits, setHits] = useState<CardSearchHit[]>([])
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const [busyPick, setBusyPick] = useState(false)

  function setMenuOpen(next: boolean) {
    setOpen((prev) => {
      if (prev !== next) onOpenChangeRef.current?.(next)
      return next
    })
  }

  useEffect(() => {
    const q = query.trim()
    if (q.length < 1) {
      setHits([])
      setMenuOpen(false)
      setLoading(false)
      return
    }

    let cancelled = false
    setLoading(true)
    const timer = window.setTimeout(() => {
      void (async () => {
        try {
          const results = await searchCards(q, 12, token)
          if (cancelled) return
          setHits(results)
          setActiveIndex(0)
          setMenuOpen(true)
        } catch {
          if (cancelled) return
          setHits([])
          setMenuOpen(true)
        } finally {
          if (!cancelled) setLoading(false)
        }
      })()
    }, 180)

    return () => {
      cancelled = true
      window.clearTimeout(timer)
    }
  }, [query, token])

  useEffect(() => {
    if (!open) return

    function onPointerDown(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        setMenuOpen(false)
      }
    }

    document.addEventListener("mousedown", onPointerDown)
    return () => document.removeEventListener("mousedown", onPointerDown)
  }, [open])

  async function choose(hit: CardSearchHit) {
    if (disabled || busyPick) return
    setBusyPick(true)
    try {
      await onPick(hit)
      setQuery("")
      setHits([])
      setMenuOpen(false)
    } finally {
      setBusyPick(false)
    }
  }

  return (
    <div
      ref={rootRef}
      className={cn(
        "relative w-full max-w-xl",
        // Above card stacks (hover uses ~z-50) while the menu is open.
        open && "z-[100]"
      )}
    >
      <CardSearchBar
        id={inputId}
        label="ADD CARD"
        value={query}
        onChange={setQuery}
        placeholder="Search cards…"
        disabled={disabled || busyPick}
        onFocus={() => {
          if (hits.length > 0) setMenuOpen(true)
        }}
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        onKeyDown={(event) => {
          if (!open || hits.length === 0) return
          if (event.key === "ArrowDown") {
            event.preventDefault()
            setActiveIndex((i) => (i + 1) % hits.length)
          } else if (event.key === "ArrowUp") {
            event.preventDefault()
            setActiveIndex((i) => (i - 1 + hits.length) % hits.length)
          } else if (event.key === "Enter") {
            event.preventDefault()
            const hit = hits[activeIndex]
            if (hit) void choose(hit)
          } else if (event.key === "Escape") {
            setMenuOpen(false)
          }
        }}
      />

      {open ? (
        <ul
          id={listId}
          role="listbox"
          className="absolute left-0 right-0 top-full z-[100] mt-1 max-h-80 overflow-y-auto border border-cyan-500/30 bg-black/95 shadow-lg"
        >
          {loading && hits.length === 0 ? (
            <li className="px-3 py-2 font-mono text-xs text-cyan-300/60">
              Searching…
            </li>
          ) : null}
          {!loading && hits.length === 0 ? (
            <li className="px-3 py-2 font-mono text-xs text-white/40">
              No matches
            </li>
          ) : null}
          {hits.map((hit, index) => {
            const art = cardArtUrl(hit.card_art_path, hit.card_art_version)
            const active = index === activeIndex
            return (
              <li key={hit.id} role="option" aria-selected={active}>
                <button
                  type="button"
                  className={cn(
                    "flex w-full items-center gap-3 px-2 py-1.5 text-left",
                    active ? "bg-cyan-500/20" : "hover:bg-cyan-500/10"
                  )}
                  onMouseEnter={() => setActiveIndex(index)}
                  onClick={() => void choose(hit)}
                  disabled={busyPick}
                >
                  {art ? (
                    <img
                      src={art}
                      alt=""
                      className="h-12 w-9 shrink-0 border border-cyan-500/25 object-cover"
                    />
                  ) : (
                    <span className="flex h-12 w-9 shrink-0 items-center justify-center border border-dashed border-cyan-500/20 bg-black/60 font-mono text-[8px] text-cyan-500/40">
                      N/A
                    </span>
                  )}
                  <span className="min-w-0 flex-1">
                    <span className="block truncate font-buahs93 text-sm text-white">
                      {hit.card_name}
                    </span>
                    <span className="block truncate font-mono text-[10px] text-cyan-400/60">
                      {hit.card_set_name} · {hit.rarity}
                    </span>
                  </span>
                </button>
              </li>
            )
          })}
        </ul>
      ) : null}
    </div>
  )
}

/**
 * One deck category block: name + ⋯ menu (rename/delete), then card stack.
 * Droppable target for moving cards between sections.
 */

import { useEffect, useState, type DragEvent } from "react"

import {
  deckCardDropEffect,
  isDeckCardDrag,
  parseDeckCardDrag,
  type DeckCardDragPayload,
} from "@/components/decks/deckCardDrag"
import {
  DeckCardStack,
} from "@/components/decks/DeckCardStack"
import type { DeckCardViewMode } from "@/components/decks/DeckCardViewControls"
import { Button } from "@/components/ui/button"
import { DropdownMenu } from "@/components/ui/DropdownMenu"
import { PublicTextField } from "@/components/ui/PublicTextField"
import type { DeckCardEntry, DeckCategoryOut } from "@/lib/api/decks"
import { isPublicTextClean } from "@/lib/profanity"
import { cn } from "@/lib/utils"

type DeckCategorySectionProps = {
  category: DeckCategoryOut
  cards: DeckCardEntry[]
  canEdit: boolean
  disabled?: boolean
  viewMode?: DeckCardViewMode
  onRename: (name: string) => Promise<void>
  onDelete: () => Promise<void>
  onSetInDeck?: (inDeck: boolean) => Promise<void>
  onCardDrop?: (payload: DeckCardDragPayload) => void | Promise<void>
  onQuantityDelta?: (card: DeckCardEntry, delta: 1 | -1) => void
  selectedKeys?: ReadonlySet<string>
  onSelectCard?: (
    card: DeckCardEntry,
    mode: "toggle" | "range"
  ) => void
  onClearSelect?: (card?: DeckCardEntry) => void
  /** Hide rename/delete — used for reserved slots like Augments. */
  reserved?: boolean
}

export function DeckCategorySection({
  category,
  cards,
  canEdit,
  disabled = false,
  viewMode = "cards",
  onRename,
  onDelete,
  onSetInDeck,
  onCardDrop,
  onQuantityDelta,
  selectedKeys,
  onSelectCard,
  onClearSelect,
  reserved = false,
}: DeckCategorySectionProps) {
  const [renaming, setRenaming] = useState(false)
  const [draftName, setDraftName] = useState(category.name)
  const [busy, setBusy] = useState(false)
  const [dropActive, setDropActive] = useState(false)

  const cardTotal = cards.reduce((sum, c) => sum + c.quantity, 0)
  const locked = disabled || busy
  const acceptsDrops = canEdit && Boolean(onCardDrop) && !locked

  useEffect(() => {
    setDraftName(category.name)
  }, [category.name])

  async function commitRename() {
    const next = draftName.trim()
    if (!next || next === category.name) {
      setRenaming(false)
      setDraftName(category.name)
      return
    }
    if (!isPublicTextClean(next)) return
    setBusy(true)
    try {
      await onRename(next)
      setRenaming(false)
    } finally {
      setBusy(false)
    }
  }

  async function commitDelete() {
    setBusy(true)
    try {
      await onDelete()
    } finally {
      setBusy(false)
    }
  }

  function parseDragPayload(event: DragEvent): DeckCardDragPayload | null {
    return parseDeckCardDrag(event)
  }

  function isCardDrag(event: DragEvent): boolean {
    return isDeckCardDrag(event)
  }

  return (
    <section
      className={cn(
        "deck-board__slot rounded-none border border-transparent p-1 transition-[border-color,background-color] duration-150",
        dropActive && "border-cyan-400/50 bg-cyan-500/10"
      )}
      onDragEnter={(event) => {
        if (!acceptsDrops || !isCardDrag(event)) return
        event.preventDefault()
        setDropActive(true)
      }}
      onDragOver={(event) => {
        if (!acceptsDrops || !isCardDrag(event)) return
        event.preventDefault()
        event.dataTransfer.dropEffect = deckCardDropEffect()
        setDropActive(true)
      }}
      onDragLeave={(event) => {
        if (!acceptsDrops) return
        const related = event.relatedTarget as Node | null
        if (related && event.currentTarget.contains(related)) return
        setDropActive(false)
      }}
      onDrop={(event) => {
        if (!acceptsDrops || !onCardDrop) return
        event.preventDefault()
        setDropActive(false)
        const payload = parseDragPayload(event)
        if (!payload) return
        const items = payload.cards?.length
          ? payload.cards
          : [
              {
                cardId: payload.cardId,
                fromCategoryId: payload.fromCategoryId,
              },
            ]
        if (items.every((item) => item.fromCategoryId === category.id)) return
        void onCardDrop(payload)
      }}
    >
      <div className="mb-3 flex flex-wrap items-center gap-2 border-b border-cyan-500/15 pb-2">
        {renaming && canEdit && !reserved ? (
          <div className="flex min-w-0 flex-wrap items-center gap-2">
            <PublicTextField
              value={draftName}
              onChange={setDraftName}
              size="sm"
              autoWidth
              disabled={locked}
              autoFocus
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault()
                  void commitRename()
                }
                if (e.key === "Escape") {
                  setRenaming(false)
                  setDraftName(category.name)
                }
              }}
            />
            <Button
              type="button"
              className="font-buahs93 h-8 rounded-none bg-cyan-800 px-3 text-xs text-white hover:bg-cyan-900"
              disabled={
                locked || !draftName.trim() || !isPublicTextClean(draftName)
              }
              onClick={() => void commitRename()}
            >
              SAVE
            </Button>
            <Button
              type="button"
              variant="ghost"
              className="font-buahs93 h-8 rounded-none px-3 text-xs text-cyan-200/80"
              disabled={locked}
              onClick={() => {
                setRenaming(false)
                setDraftName(category.name)
              }}
            >
              CANCEL
            </Button>
          </div>
        ) : (
          <>
            <h2
              className={cn(
                "font-buahs93 text-lg text-white",
                canEdit && !reserved && !locked && "cursor-text select-none"
              )}
              title={
                canEdit && !reserved ? "Double-click to rename" : undefined
              }
              onDoubleClick={() => {
                if (!canEdit || reserved || locked) return
                setDraftName(category.name)
                setRenaming(true)
              }}
            >
              {category.name}
            </h2>
            {reserved ? null : canEdit && onSetInDeck && !locked ? (
              <button
                type="button"
                aria-pressed={category.in_deck !== false}
                aria-label={
                  category.in_deck === false
                    ? "Not listed in deck"
                    : "Listed in deck"
                }
                className="font-mono text-[10px] text-cyan-200/80 hover:text-white"
                onClick={() => {
                  void onSetInDeck(category.in_deck === false)
                }}
              >
                {category.in_deck === false ? "✕" : "✓"}
              </button>
            ) : (
              <span
                className="font-mono text-[10px] text-cyan-200/70"
                title={
                  category.in_deck === false
                    ? "Not listed in deck"
                    : "Listed in deck"
                }
              >
                {category.in_deck === false ? "✕" : "✓"}
              </span>
            )}
            <span className="font-mono text-[10px] text-cyan-500/60">
              {cardTotal} cards
            </span>
            {canEdit && !reserved ? (
              <DropdownMenu
                label={`${category.name} options`}
                disabled={locked}
                align="right"
                className="ml-auto"
                items={[
                  {
                    id: "rename",
                    label: "Rename",
                    onSelect: () => {
                      setDraftName(category.name)
                      setRenaming(true)
                    },
                  },
                  {
                    id: "in-deck",
                    label: (
                      <span className="flex w-full items-center justify-between gap-3">
                        In deck
                        <span className="font-mono">
                          {category.in_deck === false ? "✕" : "✓"}
                        </span>
                      </span>
                    ),
                    onSelect: () => {
                      void onSetInDeck?.(category.in_deck === false)
                    },
                  },
                  {
                    id: "delete",
                    label: "Delete",
                    tone: "danger",
                    onSelect: () => {
                      void commitDelete()
                    },
                  },
                ]}
              />
            ) : null}
          </>
        )}
      </div>

      <div
        className={cn(
          cards.length === 0
            ? "min-h-10 py-1"
            : viewMode === "list"
              ? "w-full"
              : "flex justify-start"
        )}
      >
        {cards.length === 0 ? (
          <p className="font-mono text-xs text-white/35">
            {acceptsDrops
              ? "Drop cards here."
              : "No cards in this section."}
          </p>
        ) : (
          <DeckCardStack
            cards={cards}
            viewMode={viewMode}
            draggable={canEdit}
            disabled={locked}
            selectedKeys={selectedKeys}
            onSelectCard={canEdit ? onSelectCard : undefined}
            onClearSelect={canEdit ? onClearSelect : undefined}
            onQuantityDelta={canEdit ? onQuantityDelta : undefined}
          />
        )}
      </div>
    </section>
  )
}

/**
 * Tag typeahead — closest-name suggestions while the owner types.
 * Layout: input + sibling button share one row (same height).
 */

import { useEffect, useId, useRef, useState } from "react"

import { EditBox } from "@/components/ui/EditBox"
import {
  fetchDeckTagSuggestions,
  type DeckTagSuggestion,
} from "@/lib/api/decks"
import { containsProfanity } from "@/lib/profanity"
import { cn } from "@/lib/utils"

/**
 * Capitalize the first letter of the tag and of each word after a space.
 * Other characters are left as typed (so "mid-range" stays Mid-range).
 */
export function titleCaseTagWords(raw: string): string {
  return raw.replace(/(^| )([a-zA-Z])/g, (_, space: string, ch: string) => {
    return space + ch.toUpperCase()
  })
}

type DeckTagSuggestInputProps = {
  value: string
  onChange: (value: string) => void
  /** Tags already on this deck — hidden from the menu. */
  exclude?: string[]
  disabled?: boolean
  placeholder?: string
  className?: string
  /** Called when the user picks a suggestion (parent usually adds the tag). */
  onPick?: (tag: string) => void
}

export function DeckTagSuggestInput({
  value,
  onChange,
  exclude = [],
  disabled = false,
  placeholder = "Add tag…",
  className,
  onPick,
}: DeckTagSuggestInputProps) {
  const listId = useId()
  const inputId = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const [hits, setHits] = useState<DeckTagSuggestion[]>([])
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)

  useEffect(() => {
    const q = value.trim()
    if (q.length < 1) {
      setHits([])
      setOpen(false)
      setLoading(false)
      return
    }

    let cancelled = false
    setLoading(true)
    const timer = window.setTimeout(() => {
      void (async () => {
        try {
          const results = await fetchDeckTagSuggestions({
            q,
            limit: 12,
            exclude,
          })
          if (cancelled) return
          setHits(results)
          setActiveIndex(0)
          setOpen(true)
        } catch {
          if (cancelled) return
          setHits([])
          setOpen(true)
        } finally {
          if (!cancelled) setLoading(false)
        }
      })()
    }, 150)

    return () => {
      cancelled = true
      window.clearTimeout(timer)
    }
    // exclude joined so array identity churn doesn't spam requests
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, exclude.join("\0")])

  useEffect(() => {
    if (!open) return
    function onPointerDown(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener("mousedown", onPointerDown)
    return () => document.removeEventListener("mousedown", onPointerDown)
  }, [open])

  function choose(tag: string) {
    const next = titleCaseTagWords(tag.trim())
    if (!next || containsProfanity(next)) return
    onChange(next)
    setOpen(false)
    onPick?.(next)
  }

  return (
    <div ref={rootRef} className={cn("relative min-w-0 flex-1", className)}>
      <EditBox
        id={inputId}
        value={value}
        onChange={(e) => {
          onChange(titleCaseTagWords(e.target.value))
        }}
        className={cn(
          "w-full min-w-0",
          containsProfanity(value) &&
            "border-red-400/80 focus-visible:border-red-300"
        )}
        aria-invalid={containsProfanity(value) || undefined}
        onFocus={() => {
          if (value.trim().length > 0) setOpen(true)
        }}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            setOpen(false)
            return
          }
          if (event.key === "ArrowDown") {
            if (!open || hits.length === 0) return
            event.preventDefault()
            setActiveIndex((i) => Math.min(i + 1, hits.length - 1))
            return
          }
          if (event.key === "ArrowUp") {
            if (!open || hits.length === 0) return
            event.preventDefault()
            setActiveIndex((i) => Math.max(i - 1, 0))
            return
          }
          if (event.key === "Enter") {
            event.preventDefault()
            // Prefer the highlighted suggestion when the menu is open;
            // otherwise commit whatever the user typed (same as ADD TAG).
            if (open && hits.length > 0 && hits[activeIndex]) {
              choose(hits[activeIndex].tag)
              return
            }
            const next = value.trim()
            if (next) choose(next)
          }
        }}
        placeholder={placeholder}
        size="sm"
        disabled={disabled}
        autoComplete="off"
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
      />

      {open && value.trim().length > 0 ? (
        <ul
          id={listId}
          role="listbox"
          className="absolute left-0 right-0 z-30 mt-1 max-h-48 overflow-auto border border-cyan-500/35 bg-black/95 shadow-lg"
        >
          {loading && hits.length === 0 ? (
            <li className="px-3 py-2 font-mono text-[11px] text-white/45">
              Searching tags…
            </li>
          ) : null}
          {hits.map((hit, index) => (
            <li key={hit.tag} role="option" aria-selected={index === activeIndex}>
              <button
                type="button"
                className={cn(
                  "flex w-full items-center justify-between gap-2 px-3 py-2 text-left font-mono text-xs",
                  index === activeIndex
                    ? "bg-cyan-500/20 text-cyan-50"
                    : "text-cyan-100/90 hover:bg-cyan-500/10"
                )}
                onMouseEnter={() => setActiveIndex(index)}
                onClick={() => choose(hit.tag)}
              >
                <span>{hit.tag}</span>
                <span className="shrink-0 text-[10px] text-white/40">
                  {hit.uses}×
                </span>
              </button>
            </li>
          ))}
          {!loading && hits.length === 0 ? (
            <li className="px-3 py-2 font-mono text-[11px] text-white/45">
              No matching tags — add as new
            </li>
          ) : null}
        </ul>
      ) : null}
    </div>
  )
}

/**
 * Generic right-click / cursor-position menu.
 * Controlled: parent opens it at (x, y) and closes via onClose.
 * Renders in a portal so overflow:hidden ancestors do not clip it.
 * Items may declare `submenu` for a nested flyout.
 *
 * Placement: the root menu is clamped into the viewport; open submenus portal
 * with fixed coords and flip to the left / shift up when they would clip.
 */

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type RefObject,
} from "react"
import { createPortal } from "react-dom"

import type { DropdownMenuItem } from "@/components/ui/DropdownMenu"
import {
  clampMenuPosition,
  CONTEXT_MENU_VIEWPORT_PAD,
  planSubmenuFixedPosition,
} from "@/components/ui/contextMenuPosition.logic"
import { cn } from "@/lib/utils"

export type ContextMenuProps = {
  open: boolean
  /** Viewport X (usually event.clientX). */
  x: number
  /** Viewport Y (usually event.clientY). */
  y: number
  items: DropdownMenuItem[]
  onClose: () => void
  /** Accessible name for the menu. */
  label?: string
  className?: string
}

function SubmenuFlyout({
  anchorRef,
  panelRef,
  items,
  onRun,
}: {
  anchorRef: RefObject<HTMLElement | null>
  panelRef: RefObject<HTMLDivElement | null>
  items: DropdownMenuItem[]
  onRun: (item: DropdownMenuItem) => void
}) {
  const [coords, setCoords] = useState<{ left: number; top: number } | null>(
    null
  )

  useLayoutEffect(() => {
    const anchor = anchorRef.current
    const panel = panelRef.current
    if (!anchor || !panel) return

    const parent = anchor.getBoundingClientRect()
    const { width, height } = panel.getBoundingClientRect()
    const next = planSubmenuFixedPosition(
      parent,
      { width, height },
      window.innerWidth,
      window.innerHeight,
      CONTEXT_MENU_VIEWPORT_PAD
    )
    setCoords({ left: next.left, top: next.top })
  }, [anchorRef, panelRef, items])

  if (typeof document === "undefined") return null

  return createPortal(
    <div
      ref={panelRef}
      role="menu"
      className="fixed z-[10101] min-w-[9rem] border border-cyan-500/30 bg-black/95 py-1 shadow-lg"
      style={{
        left: coords?.left ?? -9999,
        top: coords?.top ?? 0,
        visibility: coords ? "visible" : "hidden",
      }}
    >
      {items.map((sub) => (
        <button
          key={sub.id}
          type="button"
          role="menuitem"
          disabled={sub.disabled}
          className={cn(
            "font-buahs93 inline-flex w-full items-center gap-1.5 px-3 py-2 text-left text-xs hover:bg-cyan-500/15 disabled:opacity-50",
            sub.tone === "danger"
              ? "text-red-300/90 hover:bg-red-500/15"
              : "text-cyan-100"
          )}
          onClick={(event) => {
            event.preventDefault()
            event.stopPropagation()
            onRun(sub)
          }}
        >
          {sub.label}
        </button>
      ))}
    </div>,
    document.body
  )
}

export function ContextMenu({
  open,
  x,
  y,
  items,
  onClose,
  label = "Context menu",
  className,
}: ContextMenuProps) {
  const menuId = useId()
  const menuRef = useRef<HTMLDivElement>(null)
  const submenuPanelRef = useRef<HTMLDivElement>(null)
  const [pos, setPos] = useState({ left: x, top: y })
  const [openSubmenuId, setOpenSubmenuId] = useState<string | null>(null)
  /** Anchor row for the open submenu (viewport rect → fixed flyout). */
  const submenuAnchorRef = useRef<HTMLDivElement | null>(null)

  useLayoutEffect(() => {
    if (!open) {
      setOpenSubmenuId(null)
      submenuAnchorRef.current = null
      return
    }
    const el = menuRef.current
    if (!el) {
      setPos({ left: x, top: y })
      return
    }

    const { width, height } = el.getBoundingClientRect()
    setPos(
      clampMenuPosition(
        x,
        y,
        width,
        height,
        window.innerWidth,
        window.innerHeight,
        CONTEXT_MENU_VIEWPORT_PAD
      )
    )
  }, [open, x, y, items])

  useEffect(() => {
    if (!open) return

    function onPointerDown(event: PointerEvent) {
      const target = event.target as Node
      if (menuRef.current?.contains(target)) return
      if (submenuPanelRef.current?.contains(target)) return
      onClose()
    }

    function onKeyDown(event: KeyboardEvent) {
      if (event.key !== "Escape") return
      if (openSubmenuId) {
        setOpenSubmenuId(null)
        submenuAnchorRef.current = null
        return
      }
      onClose()
    }

    // Capture phase: zone cards call stopPropagation on pointerdown, so a
    // bubble-only listener on document would never see outside clicks.
    // Defer so the same right-click that opened the menu does not close it.
    const timer = window.setTimeout(() => {
      document.addEventListener("pointerdown", onPointerDown, true)
    }, 0)
    document.addEventListener("keydown", onKeyDown)

    return () => {
      window.clearTimeout(timer)
      document.removeEventListener("pointerdown", onPointerDown, true)
      document.removeEventListener("keydown", onKeyDown)
    }
  }, [open, onClose, openSubmenuId])

  if (!open || typeof document === "undefined") return null

  function runLeaf(item: DropdownMenuItem) {
    onClose()
    if (item.disabled) return
    queueMicrotask(() => item.onSelect?.())
  }

  const openSubmenu = items.find((item) => item.id === openSubmenuId)

  return createPortal(
    <>
      <div
        ref={menuRef}
        id={menuId}
        role="menu"
        aria-label={label}
        className={cn(
          "fixed z-[10100] max-h-[calc(100vh-16px)] min-w-[9rem] overflow-y-auto border border-cyan-500/30 bg-black/95 py-1 shadow-lg",
          className
        )}
        style={{ left: pos.left, top: pos.top }}
        onContextMenu={(event) => event.preventDefault()}
      >
        {items.map((item) => {
          const hasSubmenu = Boolean(item.submenu?.length)
          const submenuOpen = openSubmenuId === item.id
          const countInput = item.countInput

          return (
            <div
              key={item.id}
              className="relative"
              ref={submenuOpen ? submenuAnchorRef : undefined}
            >
              <div
                className={cn(
                  "flex w-full items-center gap-1",
                  countInput ? "px-2 py-1" : undefined
                )}
              >
                <button
                  type="button"
                  role="menuitem"
                  aria-haspopup={hasSubmenu ? "menu" : undefined}
                  aria-expanded={hasSubmenu ? submenuOpen : undefined}
                  disabled={item.disabled}
                  className={cn(
                    "font-buahs93 flex min-w-0 flex-1 items-center gap-1.5 text-left text-xs hover:bg-cyan-500/15 disabled:opacity-50",
                    countInput ? "px-1.5 py-1.5" : "px-3 py-2",
                    item.tone === "danger"
                      ? "text-red-300/90 hover:bg-red-500/15"
                      : "text-cyan-100"
                  )}
                  onClick={(event) => {
                    event.preventDefault()
                    event.stopPropagation()
                    if (item.disabled) {
                      onClose()
                      return
                    }
                    if (hasSubmenu) {
                      setOpenSubmenuId((prev) => {
                        if (prev === item.id) {
                          submenuAnchorRef.current = null
                          return null
                        }
                        return item.id
                      })
                      return
                    }
                    runLeaf(item)
                  }}
                >
                  <span className="inline-flex min-w-0 flex-1 items-center gap-1.5">
                    {item.label}
                  </span>
                  {hasSubmenu ? (
                    <span className="shrink-0 text-cyan-300/70" aria-hidden>
                      ›
                    </span>
                  ) : null}
                </button>

                {countInput ? (
                  <input
                    type="number"
                    inputMode="numeric"
                    min={countInput.min ?? 1}
                    max={countInput.max}
                    value={countInput.value}
                    aria-label={
                      countInput.ariaLabel ?? `${String(item.label)} count`
                    }
                    disabled={countInput.disabled ?? item.disabled}
                    className={cn(
                      "h-7 w-12 shrink-0 border border-cyan-500/40 bg-black/80 px-1",
                      "font-mono text-xs text-cyan-50 outline-none",
                      "focus:border-cyan-300 disabled:opacity-50"
                    )}
                    onPointerDown={(event) => event.stopPropagation()}
                    onClick={(event) => event.stopPropagation()}
                    onChange={(event) =>
                      countInput.onChange(event.target.value)
                    }
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault()
                        event.stopPropagation()
                        if (!item.disabled) runLeaf(item)
                      }
                    }}
                  />
                ) : null}
              </div>
            </div>
          )
        })}
      </div>

      {openSubmenu?.submenu ? (
        <SubmenuFlyout
          anchorRef={submenuAnchorRef}
          panelRef={submenuPanelRef}
          items={openSubmenu.submenu}
          onRun={runLeaf}
        />
      ) : null}
    </>,
    document.body
  )
}

/**
 * Multi-select state for deck / playtester card boards.
 *
 * Keys are `${categoryId}:${cardId}` (see deckCardSelectionKey).
 */

import { useCallback, useEffect, useRef, useState } from "react"

import {
  deckCardSelectionKey,
} from "@/components/decks/deckCardDrag"
import type { DeckCardSortMode } from "@/components/decks/DeckCardSortControls"
import {
  orderedSelectionKeys,
  selectionRangeKeys,
  toggleSelectionKey,
} from "@/components/decks/deck.logic"
import type { DeckCardEntry, DeckDetail } from "@/lib/api/decks"

export type UseCardSelectionOptions = {
  deck: DeckDetail | null
  sortMode: DeckCardSortMode
  /** When false, selection clears and Escape is not bound (e.g. read-only deck). */
  enabled?: boolean
}

export type UseCardSelectionResult = {
  selectedKeys: ReadonlySet<string>
  selectCard: (card: DeckCardEntry, mode: "toggle" | "range") => void
  clearCardSelection: (card?: DeckCardEntry) => void
}

export function useCardSelection({
  deck,
  sortMode,
  enabled = true,
}: UseCardSelectionOptions): UseCardSelectionResult {
  const [selectedKeys, setSelectedKeys] = useState<ReadonlySet<string>>(
    () => new Set()
  )
  const selectionAnchorKeyRef = useRef<string | null>(null)

  const clearCardSelection = useCallback((card?: DeckCardEntry) => {
    setSelectedKeys(new Set())
    if (card) {
      selectionAnchorKeyRef.current = deckCardSelectionKey(
        card.category_id,
        card.card_id
      )
    }
  }, [])

  const selectCard = useCallback(
    (card: DeckCardEntry, mode: "toggle" | "range") => {
      const key = deckCardSelectionKey(card.category_id, card.card_id)

      if (mode === "toggle") {
        selectionAnchorKeyRef.current = key
        setSelectedKeys((prev) => toggleSelectionKey(prev, key))
        return
      }

      if (!deck) {
        selectionAnchorKeyRef.current = key
        setSelectedKeys(new Set([key]))
        return
      }

      const orderedKeys = orderedSelectionKeys(
        deck.cards,
        deck.categories,
        sortMode
      )
      const anchorKey = selectionAnchorKeyRef.current
      const targetIndex = orderedKeys.indexOf(key)
      const anchorIndex =
        anchorKey != null ? orderedKeys.indexOf(anchorKey) : -1

      if (targetIndex < 0 || anchorIndex < 0) {
        selectionAnchorKeyRef.current = key
      }
      setSelectedKeys(new Set(selectionRangeKeys(orderedKeys, anchorKey, key)))
    },
    [deck, sortMode]
  )

  useEffect(() => {
    if (!enabled) {
      clearCardSelection()
      selectionAnchorKeyRef.current = null
      return
    }

    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") clearCardSelection()
    }

    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [enabled, clearCardSelection])

  return { selectedKeys, selectCard, clearCardSelection }
}

/**
 * Admin — catalogue cards DB: search, multi-select, bulk publish + lagality.
 */

import { useEffect, useMemo, useState } from "react"

import { useAuth } from "@/app/providers/AuthProvider"
import { CardDetailOverlay } from "@/components/cards/CardDetailOverlay"
import { costTokenToIcon } from "@/components/cards/CardCostIcons"
import { CardSearchBar } from "@/components/cards/CardSearchBar"
import { SearchPaginationBar } from "@/components/cards/SearchPaginationBar"
import { GameIcon } from "@/components/common/GameIcon"
import { Button } from "@/components/ui/button"
import { EditBox } from "@/components/ui/EditBox"
import { ApiError } from "@/lib/api/client"
import {
  fetchCardFacets,
  type CardLibraryFacets,
} from "@/lib/api/cards"
import {
  LAGALITY_OPTIONS,
  PUBLISH_STATUSES,
  bulkUpdateAdminCards,
  fetchAdminCardDetail,
  fetchAdminCardLibrary,
  type AdminCardDetail,
  type AdminCardItem,
  type PublishStatus,
} from "@/lib/api/cards_admin"
import { cardArtUrl } from "@/lib/api/decks"
import { cn } from "@/lib/utils"
import { AdminPageShell } from "@/pages/admin/AdminPageShell"

const PAGE_SIZE = 48

const EMPTY_FACETS: CardLibraryFacets = {
  colors: ["LIF", "MET", "POW", "RAM", "TIM", "STL"],
  super_types: [],
  sub_types: [],
  types_lines: [],
  invoke_cost_min: 0,
  invoke_cost_max: 15,
}

const primaryActionClassName =
  "font-buahs93 h-9 rounded-none bg-cyan-700 px-4 text-sm text-white hover:bg-cyan-900 disabled:opacity-60"

const secondaryActionClassName =
  "font-buahs93 h-9 rounded-none border border-cyan-500/35 bg-black/70 px-3 text-sm text-cyan-100 hover:border-cyan-400/60 hover:bg-cyan-500/10 hover:text-white disabled:opacity-60"

const selectClassName =
  "h-9 rounded-none border border-cyan-500/35 bg-black/80 px-2.5 font-mono text-xs text-cyan-50 outline-none focus-visible:border-cyan-300"

const filterSelectClassName = selectClassName

function publishTone(status: string): string {
  if (status === "published") return "text-emerald-300/90"
  if (status === "preview") return "text-amber-300/90"
  return "text-white/45"
}

export function AdminCardsPage() {
  const { token } = useAuth()

  const [facets, setFacets] = useState<CardLibraryFacets>(EMPTY_FACETS)
  const [nameQuery, setNameQuery] = useState("")
  const [debouncedName, setDebouncedName] = useState("")
  const [descriptionQuery, setDescriptionQuery] = useState("")
  const [debouncedDescription, setDebouncedDescription] = useState("")
  const [colors, setColors] = useState<string[]>([])
  const [invokeMin, setInvokeMin] = useState("")
  const [invokeMax, setInvokeMax] = useState("")
  const [typesLine, setTypesLine] = useState("")
  const [superType, setSuperType] = useState("")
  const [subType, setSubType] = useState("")
  const [publishedFilter, setPublishedFilter] = useState<PublishStatus | "">(
    ""
  )
  const [items, setItems] = useState<AdminCardItem[]>([])
  const [total, setTotal] = useState(0)
  const [offset, setOffset] = useState(0)
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")
  const [errorText, setErrorText] = useState("")
  const [selectedIds, setSelectedIds] = useState<Set<number>>(() => new Set())
  const [bulkPublish, setBulkPublish] = useState<PublishStatus | "">("")
  const [bulkLagality, setBulkLagality] = useState<string>("")
  const [busy, setBusy] = useState(false)
  const [actionMessage, setActionMessage] = useState("")
  const [detail, setDetail] = useState<AdminCardDetail | null>(null)
  const [detailLoading, setDetailLoading] = useState(false)

  useEffect(() => {
    const timer = window.setTimeout(() => setDebouncedName(nameQuery.trim()), 200)
    return () => window.clearTimeout(timer)
  }, [nameQuery])

  useEffect(() => {
    const timer = window.setTimeout(
      () => setDebouncedDescription(descriptionQuery.trim()),
      200
    )
    return () => window.clearTimeout(timer)
  }, [descriptionQuery])

  useEffect(() => {
    if (!token) return
    let cancelled = false
    fetchCardFacets(token)
      .then((data) => {
        if (!cancelled) setFacets(data)
      })
      .catch(() => {
        /* keep EMPTY_FACETS fallback */
      })
    return () => {
      cancelled = true
    }
  }, [token])

  useEffect(() => {
    setOffset(0)
    setSelectedIds(new Set())
  }, [
    debouncedName,
    debouncedDescription,
    colors,
    invokeMin,
    invokeMax,
    typesLine,
    superType,
    subType,
    publishedFilter,
  ])

  useEffect(() => {
    if (!token) return

    let cancelled = false
    setStatus("loading")
    setErrorText("")

    const min =
      invokeMin.trim() === "" ? null : Number.parseInt(invokeMin, 10)
    const max =
      invokeMax.trim() === "" ? null : Number.parseInt(invokeMax, 10)

    void fetchAdminCardLibrary(token, {
      q: debouncedName || undefined,
      description: debouncedDescription || undefined,
      colors,
      invokeCostMin: Number.isFinite(min) ? min : null,
      invokeCostMax: Number.isFinite(max) ? max : null,
      typesLine: typesLine || undefined,
      superType: superType || undefined,
      subType: subType || undefined,
      published: publishedFilter || undefined,
      limit: PAGE_SIZE,
      offset,
    })
      .then((result) => {
        if (cancelled) return
        setItems(result.items)
        setTotal(result.total)
        setStatus("ready")
      })
      .catch((error: unknown) => {
        if (cancelled) return
        setStatus("error")
        setItems([])
        setTotal(0)
        setErrorText(
          error instanceof ApiError
            ? error.status === 403
              ? "Admin access required."
              : "Could not load the cards database."
            : "Could not reach the server."
        )
      })

    return () => {
      cancelled = true
    }
  }, [
    token,
    debouncedName,
    debouncedDescription,
    colors,
    invokeMin,
    invokeMax,
    typesLine,
    superType,
    subType,
    publishedFilter,
    offset,
  ])

  function toggleColor(color: string) {
    setColors((prev) =>
      prev.includes(color) ? prev.filter((c) => c !== color) : [...prev, color]
    )
  }

  function clearFilters() {
    setNameQuery("")
    setDescriptionQuery("")
    setColors([])
    setInvokeMin("")
    setInvokeMax("")
    setTypesLine("")
    setSuperType("")
    setSubType("")
    setPublishedFilter("")
    setOffset(0)
  }

  const pageIds = useMemo(() => items.map((item) => item.id), [items])
  const allPageSelected =
    pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id))
  const selectedCount = selectedIds.size

  function toggleOne(id: number) {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  function togglePage() {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (allPageSelected) {
        for (const id of pageIds) next.delete(id)
      } else {
        for (const id of pageIds) next.add(id)
      }
      return next
    })
  }

  function clearSelection() {
    setSelectedIds(new Set())
  }

  async function openDetail(cardId: number) {
    if (!token || detailLoading) return
    setDetailLoading(true)
    setActionMessage("")
    try {
      const data = await fetchAdminCardDetail(token, cardId)
      setDetail(data)
    } catch (error) {
      setActionMessage(
        error instanceof ApiError
          ? "Could not load card details."
          : "Could not reach the server."
      )
    } finally {
      setDetailLoading(false)
    }
  }

  async function applyBulk() {
    if (!token || selectedCount === 0) return
    if (!bulkPublish && !bulkLagality) {
      setActionMessage("Choose a publish status and/or lagality first.")
      return
    }

    setBusy(true)
    setActionMessage("")
    try {
      const result = await bulkUpdateAdminCards(token, {
        card_ids: [...selectedIds],
        published: bulkPublish || undefined,
        lagality: bulkLagality || undefined,
      })

      setItems((prev) =>
        prev.map((item) => {
          if (!selectedIds.has(item.id)) return item
          return {
            ...item,
            published: bulkPublish || item.published,
            lagality: bulkLagality || item.lagality,
          }
        })
      )
      setActionMessage(`Updated ${result.updated} row(s).`)
      setBulkPublish("")
      setBulkLagality("")
      clearSelection()
    } catch (error: unknown) {
      setActionMessage(
        error instanceof ApiError
          ? "Bulk update failed."
          : "Could not reach the server."
      )
    } finally {
      setBusy(false)
    }
  }

  const pageStart = total === 0 ? 0 : offset + 1
  const pageEnd = Math.min(offset + items.length, total)
  const canPrev = offset > 0
  const canNext = offset + PAGE_SIZE < total

  return (
    <AdminPageShell
      wide
      title="CARDS DB"
      description="Search and filter the catalogue like the public library, multi-select cards, then set publish status or lagality in bulk."
    >
      <div className="mb-4 grid gap-4 border border-cyan-500/25 bg-black/55 p-4 lg:grid-cols-[minmax(0,1fr)_14rem]">
        <div className="grid gap-3 sm:grid-cols-2">
          <div className="sm:col-span-2">
            <CardSearchBar
              label="NAME"
              value={nameQuery}
              onChange={setNameQuery}
              placeholder="Closest name match…"
            />
          </div>

          <label className="block sm:col-span-2">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              DESCRIPTION
            </span>
            <EditBox
              value={descriptionQuery}
              onChange={(e) => setDescriptionQuery(e.target.value)}
              placeholder="Rules text contains…"
              size="sm"
              autoComplete="off"
            />
          </label>

          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              INVOKE MIN
            </span>
            <EditBox
              value={invokeMin}
              onChange={(e) => setInvokeMin(e.target.value.replace(/\D/g, ""))}
              placeholder={`${facets.invoke_cost_min}`}
              size="sm"
              inputMode="numeric"
            />
          </label>

          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              INVOKE MAX
            </span>
            <EditBox
              value={invokeMax}
              onChange={(e) => setInvokeMax(e.target.value.replace(/\D/g, ""))}
              placeholder={`${facets.invoke_cost_max}`}
              size="sm"
              inputMode="numeric"
            />
          </label>

          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              TYPE LINE
            </span>
            <select
              value={typesLine}
              onChange={(e) => setTypesLine(e.target.value)}
              className={filterSelectClassName}
            >
              <option value="">Any</option>
              {facets.types_lines.map((line) => (
                <option key={line} value={line}>
                  {line}
                </option>
              ))}
            </select>
          </label>

          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              SUPER TYPE
            </span>
            <select
              value={superType}
              onChange={(e) => setSuperType(e.target.value)}
              className={filterSelectClassName}
            >
              <option value="">Any</option>
              {facets.super_types.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </label>

          <label className="block sm:col-span-2">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              SUB TYPE
            </span>
            <select
              value={subType}
              onChange={(e) => setSubType(e.target.value)}
              className={filterSelectClassName}
            >
              <option value="">Any</option>
              {facets.sub_types.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </label>

          <label className="block sm:col-span-2">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              PUBLISH STATUS
            </span>
            <select
              value={publishedFilter}
              onChange={(e) =>
                setPublishedFilter(e.target.value as PublishStatus | "")
              }
              className={filterSelectClassName}
            >
              <option value="">Any</option>
              {PUBLISH_STATUSES.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </label>
        </div>

        <div>
          <p className="mb-2 font-buahs93 text-xs text-cyan-200/70">
            COLOR COST
          </p>
          <div className="grid w-fit grid-cols-3 gap-2">
            {facets.colors.map((color) => {
              const on = colors.includes(color)
              const icon = costTokenToIcon(color)
              return (
                <Button
                  key={color}
                  type="button"
                  variant="outline"
                  size="icon"
                  aria-pressed={on}
                  aria-label={`Filter ${color}`}
                  title={color}
                  className={cn(
                    "size-9 rounded-none border",
                    on
                      ? "border-cyan-400 bg-cyan-700 hover:bg-cyan-800"
                      : "border-cyan-500/40 bg-black/70 hover:border-cyan-400/70 hover:bg-cyan-500/10"
                  )}
                  onClick={() => toggleColor(color)}
                >
                  {icon ? (
                    <GameIcon
                      name={icon}
                      className="h-5 w-auto lg:h-5 2xl:h-5"
                    />
                  ) : (
                    <span className="font-buahs93 text-[10px] text-cyan-100">
                      {color}
                    </span>
                  )}
                </Button>
              )
            })}
          </div>
          <Button
            type="button"
            className={cn(secondaryActionClassName, "mt-4")}
            onClick={clearFilters}
          >
            CLEAR FILTERS
          </Button>
        </div>
      </div>

      <div className="mb-4 flex flex-col gap-3 border border-cyan-500/25 bg-black/55 p-4 sm:flex-row sm:items-end sm:justify-between">
        <p className="font-mono text-xs text-cyan-300/60 sm:pb-2">
          {status === "loading"
            ? "Loading…"
            : `${pageStart}–${pageEnd} of ${total}`}
        </p>
      </div>

      <div className="mb-4 flex flex-col gap-3 border border-cyan-500/25 bg-black/55 p-4 lg:flex-row lg:items-end lg:justify-between">
        <div className="flex flex-wrap items-end gap-3">
          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              PUBLISH
            </span>
            <select
              className={selectClassName}
              value={bulkPublish}
              onChange={(e) =>
                setBulkPublish(e.target.value as PublishStatus | "")
              }
              disabled={busy || selectedCount === 0}
            >
              <option value="">— leave unchanged —</option>
              {PUBLISH_STATUSES.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </label>

          <label className="block">
            <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
              LAGALITY
            </span>
            <select
              className={selectClassName}
              value={bulkLagality}
              onChange={(e) => setBulkLagality(e.target.value)}
              disabled={busy || selectedCount === 0}
            >
              <option value="">— leave unchanged —</option>
              {LAGALITY_OPTIONS.map((value) => (
                <option key={value} value={value}>
                  {value}
                </option>
              ))}
            </select>
          </label>

          <Button
            type="button"
            className={primaryActionClassName}
            disabled={busy || selectedCount === 0}
            onClick={() => void applyBulk()}
          >
            APPLY TO {selectedCount || 0}
          </Button>
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <Button
            type="button"
            className={secondaryActionClassName}
            disabled={busy || pageIds.length === 0}
            onClick={togglePage}
          >
            {allPageSelected ? "CLEAR PAGE" : "SELECT PAGE"}
          </Button>
          <Button
            type="button"
            className={secondaryActionClassName}
            disabled={busy || selectedCount === 0}
            onClick={clearSelection}
          >
            CLEAR SELECTION
          </Button>
        </div>
      </div>

      {actionMessage ? (
        <p className="mb-3 font-mono text-xs text-cyan-200/80">{actionMessage}</p>
      ) : null}

      {status === "error" ? (
        <p className="mb-4 border border-red-500/40 bg-red-950/40 px-4 py-3 font-mono text-sm text-red-200">
          {errorText}
        </p>
      ) : null}

      <SearchPaginationBar
        variant="plain"
        className="mb-3"
        canPrev={canPrev}
        canNext={canNext}
        disabled={busy || status === "loading"}
        onPrev={() => setOffset((o) => Math.max(0, o - PAGE_SIZE))}
        onNext={() => setOffset((o) => o + PAGE_SIZE)}
      />

      <div className="overflow-x-auto border border-cyan-500/25 bg-black/55">
        <table className="w-full min-w-[44rem] border-collapse text-left">
          <thead>
            <tr className="border-b border-cyan-500/25 font-buahs93 text-xs tracking-wide text-cyan-300/80">
              <th className="w-10 px-3 py-2">
                <input
                  type="checkbox"
                  checked={allPageSelected}
                  onChange={togglePage}
                  disabled={pageIds.length === 0 || busy}
                  aria-label="Select all on page"
                />
              </th>
              <th className="px-2 py-2">CARD</th>
              <th className="px-2 py-2">SET</th>
              <th className="px-2 py-2">PUBLISH</th>
              <th className="px-2 py-2">LAGALITY</th>
            </tr>
          </thead>
          <tbody>
            {status === "loading" && items.length === 0 ? (
              <tr>
                <td
                  colSpan={5}
                  className="px-4 py-10 text-center font-mono text-xs text-cyan-300/50"
                >
                  Loading catalogue…
                </td>
              </tr>
            ) : null}
            {status === "ready" && items.length === 0 ? (
              <tr>
                <td
                  colSpan={5}
                  className="px-4 py-10 text-center font-mono text-xs text-white/40"
                >
                  No cards match this search.
                </td>
              </tr>
            ) : null}
            {items.map((item) => {
              const art = cardArtUrl(item.card_art_path, item.card_art_version)
              const checked = selectedIds.has(item.id)
              return (
                <tr
                  key={item.id}
                  className={cn(
                    "border-b border-cyan-500/10",
                    checked ? "bg-cyan-500/10" : "hover:bg-cyan-500/5"
                  )}
                >
                  <td className="px-3 py-2 align-middle">
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={() => toggleOne(item.id)}
                      disabled={busy}
                      aria-label={`Select ${item.card_name}`}
                    />
                  </td>
                  <td className="px-2 py-2">
                    <button
                      type="button"
                      className="flex w-full items-center gap-3 text-left"
                      disabled={busy || detailLoading}
                      title={`View details for ${item.card_name}`}
                      onClick={() => void openDetail(item.id)}
                    >
                      {art ? (
                        <img
                          src={art}
                          alt=""
                          className="h-14 w-10 shrink-0 border border-cyan-500/25 object-cover"
                        />
                      ) : (
                        <span className="flex h-14 w-10 shrink-0 items-center justify-center border border-dashed border-cyan-500/20 bg-black/60 font-mono text-[8px] text-cyan-500/40">
                          N/A
                        </span>
                      )}
                      <div className="min-w-0">
                        <p className="truncate font-buahs93 text-sm text-white underline-offset-2 hover:underline">
                          {item.card_name}
                        </p>
                        <p className="truncate font-mono text-[10px] text-cyan-400/55">
                          #{item.id}
                          {item.is_deprecated ? " · deprecated" : ""}
                          {" · "}
                          {item.rarity}
                        </p>
                      </div>
                    </button>
                  </td>
                  <td className="px-2 py-2 font-mono text-xs text-white/60">
                    {item.card_set_name}
                  </td>
                  <td
                    className={cn(
                      "px-2 py-2 font-mono text-xs",
                      publishTone(item.published)
                    )}
                  >
                    {item.published}
                  </td>
                  <td className="px-2 py-2 font-mono text-xs text-cyan-100/80">
                    {item.lagality}
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>

      <SearchPaginationBar
        variant="plain"
        className="mt-4"
        canPrev={canPrev}
        canNext={canNext}
        disabled={busy || status === "loading"}
        onPrev={() => setOffset((o) => Math.max(0, o - PAGE_SIZE))}
        onNext={() => setOffset((o) => o + PAGE_SIZE)}
      />

      <CardDetailOverlay
        card={
          detail
            ? {
                ...detail,
                cost: detail.cost.map(String),
                keywords: detail.keywords.map(String),
                super_types: detail.super_types.map(String),
                sub_types: detail.sub_types.map(String),
                metaLine: `#${detail.id} · ${detail.published} · ${detail.lagality}${
                  detail.is_deprecated ? " · deprecated" : ""
                }`,
              }
            : null
        }
        onClose={() => setDetail(null)}
      />
    </AdminPageShell>
  )
}

/**
 * Admin — user accounts: roles, feature grants, invite, disable, delete.
 */

import { useCallback, useEffect, useState, type FormEvent } from "react"

import { useAuth } from "@/app/providers/AuthProvider"
import { Button } from "@/components/ui/button"
import { EditBox } from "@/components/ui/EditBox"
import { ApiError } from "@/lib/api/client"
import {
  createAdminUser,
  deleteAdminUser,
  fetchAdminFeatures,
  fetchAdminUsers,
  inviteAdminUser,
  patchAdminUser,
  type AdminUserItem,
  type FeatureCatalogItem,
  type UserRole,
} from "@/lib/api/users_admin"
import { cn } from "@/lib/utils"
import { AdminPageShell } from "@/pages/admin/AdminPageShell"

const PAGE_SIZE = 48
const ROLES: UserRole[] = ["user", "distributor", "admin"]

const primaryActionClassName =
  "font-buahs93 h-9 rounded-none bg-cyan-700 px-4 text-sm text-white hover:bg-cyan-900 disabled:opacity-60"

const secondaryActionClassName =
  "font-buahs93 h-9 rounded-none border border-cyan-500/35 bg-black/70 px-3 text-sm text-cyan-100 hover:border-cyan-400/60 hover:bg-cyan-500/10 hover:text-white disabled:opacity-60"

const dangerActionClassName =
  "font-buahs93 h-9 rounded-none border border-red-500/50 bg-black/70 px-3 text-sm text-red-200 hover:border-red-400 hover:bg-red-500/10 disabled:opacity-60"

const selectClassName =
  "h-9 rounded-none border border-cyan-500/35 bg-black/80 px-2.5 font-mono text-xs text-cyan-50 outline-none focus-visible:border-cyan-300"

function errorText(error: unknown): string {
  if (error instanceof ApiError) {
    switch (error.detail) {
      case "cannot_delete_self":
        return "You cannot delete your own account."
      case "cannot_disable_self":
        return "You cannot disable your own account."
      case "cannot_demote_self":
        return "You cannot demote yourself."
      case "cannot_remove_last_admin":
        return "Cannot remove the last active admin."
      case "username_or_email_taken":
        return "Username or email already in use."
      case "email_not_configured":
        return "SMTP is not configured on the server."
      case "email_send_failed":
        return "Could not send email. Check SMTP settings."
      case "user_delete_blocked":
        return "Delete blocked (user still owns related data)."
      default:
        return error.detail
    }
  }
  return "Request failed."
}

export function AdminUsersPage() {
  const { token, user } = useAuth()
  const [q, setQ] = useState("")
  const [roleFilter, setRoleFilter] = useState<UserRole | "">("")
  const [activeFilter, setActiveFilter] = useState<"all" | "yes" | "no">("all")
  const [offset, setOffset] = useState(0)
  const [total, setTotal] = useState(0)
  const [items, setItems] = useState<AdminUserItem[]>([])
  const [catalog, setCatalog] = useState<FeatureCatalogItem[]>([])
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const [createOpen, setCreateOpen] = useState(false)
  const [inviteOpen, setInviteOpen] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<AdminUserItem | null>(null)

  const [formName, setFormName] = useState("")
  const [formEmail, setFormEmail] = useState("")
  const [formPassword, setFormPassword] = useState("")
  const [formRole, setFormRole] = useState<UserRole>("user")
  const [formFeatures, setFormFeatures] = useState<string[]>([])

  const load = useCallback(async () => {
    if (!token) return
    setLoading(true)
    setError(null)
    try {
      const [list, features] = await Promise.all([
        fetchAdminUsers(token, {
          q,
          role: roleFilter,
          is_active:
            activeFilter === "all" ? null : activeFilter === "yes",
          limit: PAGE_SIZE,
          offset,
        }),
        fetchAdminFeatures(token),
      ])
      setItems(list.items)
      setTotal(list.total)
      setCatalog(features)
    } catch (err) {
      setError(errorText(err))
    } finally {
      setLoading(false)
    }
  }, [token, q, roleFilter, activeFilter, offset])

  useEffect(() => {
    void load()
  }, [load])

  function toggleFormFeature(key: string) {
    setFormFeatures((prev) =>
      prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]
    )
  }

  async function onCreate(event: FormEvent) {
    event.preventDefault()
    if (!token) return
    setError(null)
    setMessage(null)
    try {
      await createAdminUser(token, {
        user_name: formName.trim(),
        email: formEmail.trim(),
        password: formPassword,
        role: formRole,
        feature_keys: formFeatures,
      })
      setMessage("User created — verification email sent.")
      setCreateOpen(false)
      setFormName("")
      setFormEmail("")
      setFormPassword("")
      setFormFeatures([])
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function onInvite(event: FormEvent) {
    event.preventDefault()
    if (!token) return
    setError(null)
    setMessage(null)
    try {
      await inviteAdminUser(token, {
        email: formEmail.trim(),
        user_name: formName.trim() || undefined,
        role: formRole,
        feature_keys: formFeatures,
      })
      setMessage("Invite email sent.")
      setInviteOpen(false)
      setFormName("")
      setFormEmail("")
      setFormFeatures([])
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function setRole(item: AdminUserItem, role: UserRole) {
    if (!token) return
    try {
      await patchAdminUser(token, item.id, { role })
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function setActive(item: AdminUserItem, is_active: boolean) {
    if (!token) return
    try {
      await patchAdminUser(token, item.id, { is_active })
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function toggleGrant(item: AdminUserItem, key: string) {
    if (!token) return
    const next = item.features.includes(key)
      ? item.features.filter((k) => k !== key)
      : [...item.features, key]
    try {
      await patchAdminUser(token, item.id, { feature_keys: next })
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function resendVerify(item: AdminUserItem) {
    if (!token) return
    try {
      await patchAdminUser(token, item.id, { resend_verification: true })
      setMessage(`Verification resent to ${item.email}.`)
    } catch (err) {
      setError(errorText(err))
    }
  }

  async function confirmDelete() {
    if (!token || !deleteTarget) return
    try {
      await deleteAdminUser(token, deleteTarget.id)
      setMessage(`Deleted ${deleteTarget.user_name}.`)
      setDeleteTarget(null)
      await load()
    } catch (err) {
      setError(errorText(err))
    }
  }

  const canPrev = offset > 0
  const canNext = offset + PAGE_SIZE < total

  return (
    <AdminPageShell
      title="USERS"
      description="Create and invite accounts, change roles, grant paid features without Stripe, disable or permanently delete users. Playtester is always public and is not listed here."
    >
      <div className="flex flex-col gap-3 lg:flex-row lg:items-end">
        <label className="flex w-full min-w-0 flex-col gap-1 lg:min-w-[14rem] lg:flex-1">
          <span className="font-mono text-[10px] uppercase text-white/45">
            Search
          </span>
          <EditBox
            value={q}
            onChange={(e) => {
              setOffset(0)
              setQ(e.target.value)
            }}
            placeholder="username or email"
            className="w-full min-w-0"
          />
        </label>
        <div className="flex w-full flex-wrap items-end gap-3 lg:w-auto lg:shrink-0">
          <label className="flex min-w-[8rem] flex-1 flex-col gap-1 sm:flex-none">
            <span className="font-mono text-[10px] uppercase text-white/45">
              Role
            </span>
            <select
              className={cn(selectClassName, "w-full sm:w-auto")}
              value={roleFilter}
              onChange={(e) => {
                setOffset(0)
                setRoleFilter(e.target.value as UserRole | "")
              }}
            >
              <option value="">All</option>
              {ROLES.map((role) => (
                <option key={role} value={role}>
                  {role}
                </option>
              ))}
            </select>
          </label>
          <label className="flex min-w-[8rem] flex-1 flex-col gap-1 sm:flex-none">
            <span className="font-mono text-[10px] uppercase text-white/45">
              Active
            </span>
            <select
              className={cn(selectClassName, "w-full sm:w-auto")}
              value={activeFilter}
              onChange={(e) => {
                setOffset(0)
                setActiveFilter(e.target.value as "all" | "yes" | "no")
              }}
            >
              <option value="all">All</option>
              <option value="yes">Active</option>
              <option value="no">Disabled</option>
            </select>
          </label>
          <Button
            type="button"
            className={secondaryActionClassName}
            onClick={() => {
              setCreateOpen(true)
              setInviteOpen(false)
            }}
          >
            ADD USER
          </Button>
          <Button
            type="button"
            className={primaryActionClassName}
            onClick={() => {
              setInviteOpen(true)
              setCreateOpen(false)
            }}
          >
            INVITE
          </Button>
        </div>
      </div>

      {message ? (
        <p className="mt-3 text-sm text-emerald-300/90">{message}</p>
      ) : null}
      {error ? <p className="mt-3 text-sm text-red-300/90">{error}</p> : null}

      {(createOpen || inviteOpen) && (
        <form
          onSubmit={inviteOpen ? onInvite : onCreate}
          className="mt-4 border border-cyan-500/25 bg-black/50 p-4"
        >
          <h2 className="font-buahs93 text-cyan-200">
            {inviteOpen ? "INVITE USER" : "CREATE USER"}
          </h2>
          <div className="mt-3 grid gap-3 sm:grid-cols-2">
            <label className="flex flex-col gap-1">
              <span className="font-mono text-[10px] text-white/45">
                Username {inviteOpen ? "(optional)" : ""}
              </span>
              <EditBox
                value={formName}
                onChange={(e) => setFormName(e.target.value)}
                required={!inviteOpen}
              />
            </label>
            <label className="flex flex-col gap-1">
              <span className="font-mono text-[10px] text-white/45">Email</span>
              <EditBox
                value={formEmail}
                onChange={(e) => setFormEmail(e.target.value)}
                required
              />
            </label>
            {!inviteOpen ? (
              <label className="flex flex-col gap-1">
                <span className="font-mono text-[10px] text-white/45">
                  Password
                </span>
                <EditBox
                  password
                  value={formPassword}
                  onChange={(e) => setFormPassword(e.target.value)}
                  required
                />
              </label>
            ) : null}
            <label className="flex flex-col gap-1">
              <span className="font-mono text-[10px] text-white/45">Role</span>
              <select
                className={selectClassName}
                value={formRole}
                onChange={(e) => setFormRole(e.target.value as UserRole)}
              >
                {ROLES.map((role) => (
                  <option key={role} value={role}>
                    {role}
                  </option>
                ))}
              </select>
            </label>
          </div>
          <fieldset className="mt-3">
            <legend className="font-mono text-[10px] text-white/45">
              Feature grants
            </legend>
            <div className="mt-2 flex flex-wrap gap-3">
              {catalog.map((feature) => (
                <label
                  key={feature.key}
                  className="flex items-center gap-2 text-sm text-cyan-100"
                  title={feature.description}
                >
                  <input
                    type="checkbox"
                    checked={formFeatures.includes(feature.key)}
                    onChange={() => toggleFormFeature(feature.key)}
                  />
                  {feature.label}
                </label>
              ))}
            </div>
          </fieldset>
          <div className="mt-4 flex gap-2">
            <Button type="submit" className={primaryActionClassName}>
              {inviteOpen ? "SEND INVITE" : "CREATE"}
            </Button>
            <Button
              type="button"
              className={secondaryActionClassName}
              onClick={() => {
                setCreateOpen(false)
                setInviteOpen(false)
              }}
            >
              CANCEL
            </Button>
          </div>
        </form>
      )}

      <div className="mt-4 overflow-x-auto border border-cyan-500/20">
        <table className="w-full min-w-[56rem] border-collapse text-left text-sm">
          <thead className="bg-black/70 font-mono text-[10px] uppercase text-white/50">
            <tr>
              <th className="px-3 py-2">User</th>
              <th className="px-3 py-2">Role</th>
              <th className="px-3 py-2">Status</th>
              <th className="px-3 py-2">Features</th>
              <th className="px-3 py-2">Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item) => {
              const isSelf = user?.id === item.id
              return (
                <tr
                  key={item.id}
                  className="border-t border-cyan-500/10 bg-black/40"
                >
                  <td className="px-3 py-3 align-top">
                    <div className="font-medium text-cyan-100">
                      {item.user_name}
                    </div>
                    <div className="font-mono text-xs text-white/45">
                      {item.email}
                    </div>
                  </td>
                  <td className="px-3 py-3 align-top">
                    <select
                      className={selectClassName}
                      value={item.role}
                      disabled={isSelf}
                      onChange={(e) =>
                        void setRole(item, e.target.value as UserRole)
                      }
                    >
                      {ROLES.map((role) => (
                        <option key={role} value={role}>
                          {role}
                        </option>
                      ))}
                    </select>
                  </td>
                  <td className="px-3 py-3 align-top font-mono text-xs">
                    <div
                      className={
                        item.is_active ? "text-emerald-300/90" : "text-red-300/80"
                      }
                    >
                      {item.is_active ? "active" : "disabled"}
                    </div>
                    <div
                      className={
                        item.email_verified
                          ? "text-white/45"
                          : "text-amber-300/90"
                      }
                    >
                      {item.email_verified ? "verified" : "unverified"}
                    </div>
                  </td>
                  <td className="px-3 py-3 align-top">
                    <div className="flex flex-col gap-1">
                      {catalog.map((feature) => (
                        <label
                          key={feature.key}
                          className="flex items-center gap-2 text-xs text-cyan-100/90"
                          title={feature.description}
                        >
                          <input
                            type="checkbox"
                            checked={item.features.includes(feature.key)}
                            onChange={() => void toggleGrant(item, feature.key)}
                          />
                          {feature.label}
                        </label>
                      ))}
                    </div>
                  </td>
                  <td className="px-3 py-3 align-top">
                    <div className="flex flex-wrap gap-2">
                      <Button
                        type="button"
                        className={secondaryActionClassName}
                        disabled={isSelf}
                        onClick={() => void setActive(item, !item.is_active)}
                      >
                        {item.is_active ? "DISABLE" : "ENABLE"}
                      </Button>
                      {!item.email_verified ? (
                        <Button
                          type="button"
                          className={secondaryActionClassName}
                          onClick={() => void resendVerify(item)}
                        >
                          RESEND VERIFY
                        </Button>
                      ) : null}
                      <Button
                        type="button"
                        className={dangerActionClassName}
                        disabled={isSelf}
                        onClick={() => setDeleteTarget(item)}
                      >
                        DELETE
                      </Button>
                    </div>
                  </td>
                </tr>
              )
            })}
            {!loading && items.length === 0 ? (
              <tr>
                <td
                  colSpan={5}
                  className="px-3 py-8 text-center text-white/45"
                >
                  No users match these filters.
                </td>
              </tr>
            ) : null}
          </tbody>
        </table>
      </div>

      <div className="mt-3 flex items-center justify-between gap-3">
        <p className="font-mono text-xs text-white/45">
          {loading ? "Loading…" : `${total} user(s)`}
        </p>
        <div className="flex gap-2">
          <Button
            type="button"
            className={secondaryActionClassName}
            disabled={!canPrev || loading}
            onClick={() => setOffset((o) => Math.max(0, o - PAGE_SIZE))}
          >
            PREV
          </Button>
          <Button
            type="button"
            className={secondaryActionClassName}
            disabled={!canNext || loading}
            onClick={() => setOffset((o) => o + PAGE_SIZE)}
          >
            NEXT
          </Button>
        </div>
      </div>

      {deleteTarget ? (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4"
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-user-title"
        >
          <div className="w-full max-w-md border border-red-500/40 bg-black p-5">
            <h2
              id="delete-user-title"
              className="font-buahs93 text-lg text-red-200"
            >
              PERMANENT DELETE
            </h2>
            <p className="mt-3 text-sm text-white/70">
              This cannot be undone. Delete{" "}
              <span className="text-cyan-200">{deleteTarget.user_name}</span> (
              {deleteTarget.email})?
            </p>
            <div className="mt-5 flex justify-end gap-2">
              <Button
                type="button"
                className={secondaryActionClassName}
                onClick={() => setDeleteTarget(null)}
              >
                CANCEL
              </Button>
              <Button
                type="button"
                className={cn(dangerActionClassName, "border-red-400")}
                onClick={() => void confirmDelete()}
              >
                DELETE PERMANENTLY
              </Button>
            </div>
          </div>
        </div>
      ) : null}
    </AdminPageShell>
  )
}

import { useEffect, useState } from "react"
import { Link, useSearchParams } from "react-router-dom"

import {
  HELP_TONE_CLASS,
  type HelpTone,
} from "@/components/auth/authFormStyles"
import { verifyEmailRequest } from "@/lib/api/email_auth"
import { ApiError } from "@/lib/api/client"
import { ROUTES } from "@/lib/route"
import { cn } from "@/lib/utils"
import { AuthUtilityShell } from "@/pages/auth/AuthUtilityShell"

export function VerifyEmailPage() {
  const [params] = useSearchParams()
  const token = params.get("token")?.trim() ?? ""
  const [tone, setTone] = useState<HelpTone>("pending")
  const [text, setText] = useState("Verifying your email…")

  useEffect(() => {
    if (!token) {
      setTone("error")
      setText("Missing verification token.")
      return
    }
    let cancelled = false
    void (async () => {
      try {
        await verifyEmailRequest(token)
        if (!cancelled) {
          setTone("success")
          setText("Email verified. You can log in now.")
        }
      } catch (error) {
        if (cancelled) return
        setTone("error")
        setText(
          error instanceof ApiError
            ? error.detail === "invalid_or_expired_token"
              ? "This link is invalid or expired."
              : error.detail
            : "Verification failed."
        )
      }
    })()
    return () => {
      cancelled = true
    }
  }, [token])

  return (
    <AuthUtilityShell title="VERIFY EMAIL">
      <p className={cn("text-sm", HELP_TONE_CLASS[tone])}>{text}</p>
      <Link
        to={ROUTES.LOGIN}
        className="mt-4 inline-block text-cyan-300 underline hover:text-cyan-200"
      >
        GO TO LOGIN
      </Link>
    </AuthUtilityShell>
  )
}

/**
 * Account subscription page — Standard Supporter plan + Stripe Checkout.
 * Preview cards gate on entitlement; playtester stays public (no account).
 */

import { useEffect, useState } from "react"
import { useSearchParams } from "react-router-dom"

import { useAuth } from "@/app/providers/AuthProvider"
import { sharedImages } from "@/assets"
import { Button } from "@/components/ui/button"
import { ApiError } from "@/lib/api/client"
import { fetchCurrentUser } from "@/lib/api/auth"
import {
  createCheckoutSession,
  createPortalSession,
  fetchBillingPlan,
  fetchBillingStatus,
  syncBillingFromStripe,
  type BillingPlan,
  type BillingStatus,
} from "@/lib/api/billing"
import {
  formatSubscriptionDate,
  isUserSubscribed,
  subscriptionPeriodLabel,
} from "@/lib/subscription.logic"
import { cn } from "@/lib/utils"

const primaryActionClassName =
  "font-buahs93 h-10 rounded-none bg-cyan-700 px-6 text-sm text-white hover:bg-cyan-900 disabled:opacity-60"

const secondaryActionClassName =
  "font-buahs93 h-10 rounded-none border border-cyan-500/35 bg-black/70 px-5 text-sm text-cyan-100 hover:border-cyan-400/60 hover:bg-cyan-500/10 hover:text-white disabled:opacity-60"

export function SubscribePage() {
  const { token, user, setSession } = useAuth()
  const [params] = useSearchParams()
  const [plan, setPlan] = useState<BillingPlan | null>(null)
  const [status, setStatus] = useState<BillingStatus | null>(null)
  const [busy, setBusy] = useState(false)
  const [errorText, setErrorText] = useState("")
  const [infoText, setInfoText] = useState("")

  const entitled = isUserSubscribed(user) || Boolean(status?.is_subscribed)
  const stripeReady =
    plan?.stripe_configured ?? status?.stripe_configured ?? false

  useEffect(() => {
    if (params.get("success") === "1") {
      setInfoText(
        "Payment complete — syncing your subscription…"
      )
    } else if (params.get("canceled") === "1") {
      setInfoText("Checkout canceled. You can try again anytime.")
    }
  }, [params])

  useEffect(() => {
    let cancelled = false
    void fetchBillingPlan()
      .then((data) => {
        if (!cancelled) setPlan(data)
      })
      .catch(() => {
        if (!cancelled) setPlan(null)
      })
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!token) return

    let cancelled = false
    const afterCheckout = params.get("success") === "1"

    // After Checkout, pull Stripe → DB so entitlement works even if the webhook
    // was missed (common locally when `stripe listen` is not running).
    const statusPromise = afterCheckout
      ? syncBillingFromStripe(token)
      : fetchBillingStatus(token)

    void statusPromise
      .then(async (data) => {
        if (cancelled) return
        setStatus(data)
        if (afterCheckout && data.is_subscribed) {
          setInfoText("Payment complete — subscription is active.")
        }
        // Refresh /auth/me so header/gates see the new entitlement.
        try {
          const fresh = await fetchCurrentUser(token)
          if (!cancelled) setSession(token, fresh)
        } catch {
          /* keep existing session */
        }
      })
      .catch(() => {
        if (!cancelled) {
          setStatus(null)
          if (afterCheckout) {
            setInfoText(
              "Payment may have succeeded, but we could not sync yet. Refresh in a moment."
            )
          }
        }
      })

    if (!afterCheckout) {
      void fetchCurrentUser(token)
        .then((fresh) => {
          if (!cancelled) setSession(token, fresh)
        })
        .catch(() => {
          /* keep existing session */
        })
    }

    return () => {
      cancelled = true
    }
  }, [token, setSession, params])

  async function onSubscribe() {
    if (!token) return
    setBusy(true)
    setErrorText("")
    try {
      const { url } = await createCheckoutSession(token)
      window.location.assign(url)
    } catch (error: unknown) {
      setBusy(false)
      if (error instanceof ApiError) {
        if (error.detail === "already_subscribed") {
          setErrorText("You already have an active subscription.")
        } else if (error.detail === "admin_already_entitled") {
          setErrorText("Admins already have full access — no subscription needed.")
        } else if (error.detail === "stripe_not_configured") {
          setErrorText(
            "Stripe is not configured on the server yet (missing keys / price id)."
          )
        } else {
          setErrorText("Could not start checkout.")
        }
      } else {
        setErrorText("Could not reach the server.")
      }
    }
  }

  async function onManage() {
    if (!token) return
    setBusy(true)
    setErrorText("")
    try {
      const { url } = await createPortalSession(token)
      window.location.assign(url)
    } catch (error: unknown) {
      setBusy(false)
      if (error instanceof ApiError && error.detail === "no_stripe_customer") {
        setErrorText("No Stripe customer yet — subscribe first.")
      } else {
        setErrorText("Could not open the billing portal.")
      }
    }
  }

  return (
    <section
      className="relative min-h-screen bg-cover bg-center bg-no-repeat px-4 py-12 sm:px-6"
      style={{ backgroundImage: `url(${sharedImages.ZONE_BACKGROUND})` }}
    >
      <div className="absolute inset-0 bg-black/70" aria-hidden />
      <div className="relative z-10 mx-auto w-full max-w-xl pt-14">
        <header className="mb-8 border-b border-cyan-500/20 pb-5">
          <p className="font-buahs93 text-xs tracking-widest text-cyan-400/70">
            ACCOUNT
          </p>
          <h1 className="font-glitch mt-1 text-3xl text-cyan-300 sm:text-4xl">
            SUBSCRIBE
          </h1>
          <p className="mt-2 text-sm text-white/55">
            {plan?.tagline ??
              "Support Mirror Image development and unlock early-access play spaces."}
          </p>
        </header>

        <article className="mb-4 border border-cyan-500/25 bg-black/55 p-5">
          <div className="flex flex-wrap items-baseline justify-between gap-3">
            <h2 className="font-buahs93 text-xl text-cyan-200">
              {plan?.name ?? "Standard Supporter"}
            </h2>
            <p className="font-glitch text-2xl text-white">
              {plan?.price_display ?? "…"}
            </p>
          </div>
          <p className="mt-1 font-mono text-[10px] uppercase tracking-wide text-cyan-400/55">
            tier · {plan?.type ?? "standard supporter"}
          </p>

          <ul className="mt-5 space-y-2 border-t border-cyan-500/15 pt-4">
            {(plan?.features ?? [
              "Access preview cards still in design",
              "Play with friends in the Playtester",
            ]).map((feature) => (
              <li
                key={feature}
                className="flex gap-2 font-mono text-xs text-cyan-50/85"
              >
                <span className="text-cyan-400/70" aria-hidden>
                  ▸
                </span>
                <span>
                  {feature}
                  <span className="ml-2 text-white/35"></span>
                </span>
              </li>
            ))}
          </ul>
        </article>

        <div className="border border-cyan-500/25 bg-black/55 p-5">
          <dl className="space-y-2 font-mono text-xs text-cyan-100/80">
            <div className="flex justify-between gap-4">
              <dt className="text-cyan-400/60">Status</dt>
              <dd
                className={cn(
                  entitled ? "text-emerald-300/90" : "text-white/55"
                )}
              >
                {status?.subscription_status ??
                  user?.subscription_status ??
                  "none"}
              </dd>
            </div>
            <div className="flex justify-between gap-4">
              <dt className="text-cyan-400/60">Type</dt>
              <dd>
                {status?.subscription_type ||
                  user?.subscription_type ||
                  "—"}
              </dd>
            </div>
            <div className="flex justify-between gap-4">
              <dt className="text-cyan-400/60">Entitled</dt>
              <dd>{entitled ? "yes" : "no"}</dd>
            </div>
            {status?.subscription_current_period_end ? (
              <div className="flex justify-between gap-4">
                <dt className="text-cyan-400/60">
                  {subscriptionPeriodLabel(status)}
                </dt>
                <dd>
                  {formatSubscriptionDate(
                    status.subscription_current_period_end
                  )}
                </dd>
              </div>
            ) : null}
          </dl>

          {infoText ? (
            <p className="mt-4 font-mono text-xs text-cyan-200/80">{infoText}</p>
          ) : null}
          {errorText ? (
            <p className="mt-4 font-mono text-xs text-red-300" role="alert">
              {errorText}
            </p>
          ) : null}

          <div className="mt-6 flex flex-wrap gap-3">
            {!entitled ? (
              <Button
                type="button"
                className={primaryActionClassName}
                disabled={busy || !stripeReady}
                onClick={() => void onSubscribe()}
              >
                {busy ? "REDIRECTING…" : "BECOME A SUPPORTER"}
              </Button>
            ) : null}
            {entitled ? (
              <Button
                type="button"
                className={secondaryActionClassName}
                disabled={busy}
                onClick={() => void onManage()}
              >
                MANAGE BILLING
              </Button>
            ) : null}
          </div>

          {!stripeReady ? (
            <p className="mt-4 font-mono text-[11px] text-amber-200/80">
              Server is missing STRIPE_SECRET_KEY / STRIPE_PRICE_ID. Add them to
              your `.env`, then rebuild the API.
            </p>
          ) : null}
        </div>
      </div>
    </section>
  )
}

/**
 * Community deck browse — search + advanced filters (author, tag, card, sort).
 */

import { useEffect, useState } from "react"

import { useAuth } from "@/app/providers/AuthProvider"
import { sharedImages } from "@/assets/shared"
import { CardSearchBar } from "@/components/cards/CardSearchBar"
import { DeckListCard } from "@/components/decks/DeckListCard"
import { SearchPaginationBar } from "@/components/cards/SearchPaginationBar"
import { EditBox } from "@/components/ui/EditBox"
import { GlitchFx } from "@/components/effects/GlitchFx"
import {
  fetchPublicDecks,
  type DeckSummary,
  type PublicDeckQuery,
} from "@/lib/api/decks"
import { cn } from "@/lib/utils"

const PAGE_SIZE = 24

type SortMode = NonNullable<PublicDeckQuery["sort"]>

export function ComunityDecksPage() {
  const { token } = useAuth()
  const [decks, setDecks] = useState<DeckSummary[]>([])
  const [total, setTotal] = useState(0)
  const [offset, setOffset] = useState(0)
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")

  const [nameQuery, setNameQuery] = useState("")
  const [debouncedQ, setDebouncedQ] = useState("")
  const [advancedOpen, setAdvancedOpen] = useState(false)
  const [author, setAuthor] = useState("")
  const [tag, setTag] = useState("")
  const [card, setCard] = useState("")
  const [sort, setSort] = useState<SortMode>("newest")

  // Debounce free-text search like the card library.
  useEffect(() => {
    const handle = window.setTimeout(() => {
      setDebouncedQ(nameQuery.trim())
      setOffset(0)
    }, 300)
    return () => window.clearTimeout(handle)
  }, [nameQuery])

  useEffect(() => {
    setOffset(0)
  }, [author, tag, card, sort])

  useEffect(() => {
    let cancelled = false
    setStatus("loading")

    fetchPublicDecks({
      q: debouncedQ || undefined,
      author: author.trim() || undefined,
      tag: tag.trim() || undefined,
      card: card.trim() || undefined,
      sort,
      limit: PAGE_SIZE,
      offset,
      token,
    })
      .then((page) => {
        if (cancelled) return
        setDecks(page.items)
        setTotal(page.total)
        setStatus("ready")
      })
      .catch(() => {
        if (cancelled) return
        setStatus("error")
      })

    return () => {
      cancelled = true
    }
  }, [debouncedQ, author, tag, card, sort, offset, token])

  const advancedActive =
    author.trim() !== "" || tag.trim() !== "" || card.trim() !== "" || sort !== "newest"

  const pageStart = total === 0 ? 0 : offset + 1
  const pageEnd = Math.min(offset + decks.length, total)
  const canPrev = offset > 0
  const canNext = offset + PAGE_SIZE < total

  function clearFilters() {
    setNameQuery("")
    setDebouncedQ("")
    setAuthor("")
    setTag("")
    setCard("")
    setSort("newest")
    setOffset(0)
  }

  return (
    <section
      className="relative min-h-screen bg-cover bg-center bg-no-repeat px-4 py-12 sm:px-6 lg:px-8 xl:px-10 2xl:px-12"
      style={{ backgroundImage: `url(${sharedImages.ZONE_BACKGROUND})` }}
    >
      <div className="absolute inset-0 bg-black/65" aria-hidden />

      <div className="relative z-10 mx-auto w-full max-w-4xl pt-8">
        <h1 className="font-glitch text-3xl text-cyan-300">COMMUNITY DECKS</h1>
        <p className="mt-2 text-sm text-white/50">
          Browse public decks — search by name, author, tags, or cards inside.
        </p>

        <div className="mt-6 space-y-3 border border-cyan-500/20 bg-black/50 p-4">
          <CardSearchBar
            label="SEARCH"
            value={nameQuery}
            onChange={setNameQuery}
            placeholder="Deck name or description…"
          />

          <button
            type="button"
            aria-expanded={advancedOpen}
            className={cn(
              "flex w-full items-center justify-between border border-cyan-500/30 bg-black/60 px-3 py-2",
              "font-buahs93 text-xs tracking-wide text-cyan-100 hover:border-cyan-400/50 hover:bg-cyan-500/10"
            )}
            onClick={() => setAdvancedOpen((prev) => !prev)}
          >
            <span className="inline-flex items-center gap-2">
              FILTERS
              {advancedActive ? (
                <span
                  className="inline-block size-1.5 rounded-full bg-cyan-400"
                  title="Filters active"
                  aria-label="Filters active"
                />
              ) : null}
            </span>
            <span className="font-mono text-[10px] text-cyan-300/70">
              {advancedOpen ? "▲" : "▼"}
            </span>
          </button>

          {advancedOpen ? (
            <div className="grid gap-3 border border-cyan-500/20 border-t-0 bg-black/40 p-3 sm:grid-cols-2">
              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  AUTHOR
                </span>
                <EditBox
                  value={author}
                  onChange={(e) => setAuthor(e.target.value)}
                  placeholder="Username contains…"
                  size="sm"
                  autoComplete="off"
                />
              </label>

              <label className="block">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  TAG
                </span>
                <EditBox
                  value={tag}
                  onChange={(e) => setTag(e.target.value)}
                  placeholder="Exact tag…"
                  size="sm"
                  autoComplete="off"
                />
              </label>

              <label className="block sm:col-span-2">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  CONTAINS CARD
                </span>
                <EditBox
                  value={card}
                  onChange={(e) => setCard(e.target.value)}
                  placeholder="Card name contains…"
                  size="sm"
                  autoComplete="off"
                />
              </label>

              <label className="block sm:col-span-2">
                <span className="mb-1 block font-buahs93 text-xs text-cyan-200/70">
                  SORT
                </span>
                <select
                  value={sort}
                  onChange={(e) => setSort(e.target.value as SortMode)}
                  className="w-full border border-white/40 bg-black/80 px-3 py-2 font-mono text-sm text-white outline-none focus-visible:border-white"
                >
                  <option value="newest">Newest</option>
                  <option value="likes">Most likes</option>
                  <option value="views">Most views</option>
                  <option value="name">Name A–Z</option>
                </select>
              </label>

              {advancedActive ? (
                <div className="sm:col-span-2">
                  <GlitchFx
                    type="button"
                    label="CLEAR FILTERS"
                    className="font-buahs93 h-8 w-full rounded-none border border-cyan-500/30 bg-transparent text-xs text-cyan-100 hover:bg-cyan-500/10"
                    onClick={clearFilters}
                  />
                </div>
              ) : null}
            </div>
          ) : null}
        </div>

        <SearchPaginationBar
          className="mt-4"
          summary={
            status === "loading"
              ? "Scanning archive…"
              : `${pageStart}–${pageEnd} of ${total}`
          }
          canPrev={canPrev}
          canNext={canNext}
          disabled={status === "loading"}
          onPrev={() => setOffset((prev) => Math.max(0, prev - PAGE_SIZE))}
          onNext={() => setOffset((prev) => prev + PAGE_SIZE)}
        />

        {status === "error" && (
          <p className="mt-4" role="alert">
            Could not load community decks.
          </p>
        )}
        {status === "ready" && decks.length === 0 && (
          <p className="mt-6 text-white/50">NO PUBLIC DECKS MATCH</p>
        )}
        {status === "ready" && decks.length > 0 && (
          <ul className="mt-6 grid gap-4 sm:grid-cols-2">
            {decks.map((deck) => (
              <li key={deck.id}>
                <DeckListCard deck={deck} showAuthor />
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  )
}

